/* =============================================================================
 * TYPE-SAFE ACCESS HELPERS
 * ============================================================================= */

/**
 * Type-safe array element access that throws on out-of-bounds indices.
 *
 * @remarks
 * TypeScript's standard array index signature returns `T | undefined`.
 * This helper narrows the return type to `T` by throwing an explicit error
 * when the index is out of range, eliminating the need for non-null assertions
 * (`!`) throughout the implementation.
 *
 * This function appears in every hot path, so its overhead should be considered
 * when evaluating performance-sensitive code paths.
 *
 * @typeParam T - The element type of the array
 * @param array - A readonly array from which to read
 * @param index - Zero-based index to access
 * @returns The element at `array[index]`
 *
 * @throws `Error` if `index` is out of bounds (i.e., `array[index] === undefined`)
 *
 * @example
 * ```typescript
 * const xs = [10n, 20n, 30n] as const;
 * const val = getElement(xs, 1); // 20n — type is bigint, not bigint | undefined
 * getElement(xs, 5);             // throws: "Array index 5 out of bounds (length: 3)"
 * ```
 *
 * @internal
 */
function getElement<T>(array: readonly T[], index: number): T {
  const element = array[index];
  if (element === undefined) {
    throw new Error(`Array index ${String(index)} out of bounds (length: ${String(array.length)})`);
  }
  return element;
}

/**
 * Type-safe matrix element access that throws on out-of-bounds row or column.
 *
 * @remarks
 * Delegates to `getElement` twice: once for the row array and once for the
 * column element within that row. Both bounds are checked, so an informative
 * error is thrown if either dimension is out of range.
 *
 * Matrices in this implementation are stored in row-major order as
 * `bigint[][]` where `matrix[rowIndex][colIndex]`.
 *
 * @param matrix - A readonly row-major 2D matrix
 * @param row - Zero-based row index
 * @param col - Zero-based column index
 * @returns The element at `matrix[row][col]`
 *
 * @throws `Error` if `row` or `col` is out of bounds
 *
 * @example
 * ```typescript
 * const m = [[1n, 2n], [3n, 4n]];
 * getMatrixElement(m, 1, 0); // 3n
 * getMatrixElement(m, 2, 0); // throws
 * ```
 *
 * @internal
 */
function getMatrixElement(
  matrix: readonly (readonly bigint[])[],
  row: number,
  col: number,
): bigint {
  const rowArray = getElement(matrix, row);
  return getElement(rowArray, col);
}

/* =============================================================================
 * SHAKE256 XOF INTERFACE
 *
 * Typed wrapper for the SHAKE256 XOF functionality from @noble/hashes.
 * The library does not export a public XOF type, so we define one here.
 * ============================================================================= */

/**
 * A minimal interface for SHAKE256 operating in extendable output (XOF) mode.
 *
 * @remarks
 * `@noble/hashes` exposes a `.xof(n)` method at runtime on the SHAKE256 hasher
 * but does not include it in its public TypeScript type declarations. This
 * interface captures the XOF contract so the rest of the implementation can
 * call `.xof()` in a type-safe way after the runtime assertion in
 * `assertXofMode` succeeds.
 *
 * @see `assertXofMode` — the runtime type guard that narrows a hasher to this interface
 *
 * @internal
 */
interface Shake256ExtendableOutputHasher {
  /**
   * Feeds additional data into the SHAKE256 state.
   *
   * @param data - Raw bytes to absorb
   * @returns `this` for method chaining
   */
  update: (data: Uint8Array) => Shake256ExtendableOutputHasher;

  /**
   * Squeezes exactly `length` bytes from the XOF output stream.
   *
   * @remarks
   * Unlike a fixed-output hash, successive calls to `xof()` on the same
   * hasher advance a read cursor, producing non-overlapping output segments.
   * This property is exploited by `createShake256FieldElementSampler` to
   * stream field elements one at a time without re-seeding.
   *
   * @param length - Number of bytes to squeeze
   * @returns A `Uint8Array` of exactly `length` bytes
   */
  xof: (length: number) => Uint8Array;
}

/**
 * Runtime type assertion that a `shake256` hasher supports XOF output.
 *
 * @remarks
 * `@noble/hashes` attaches `.xof()` to the SHAKE family at runtime but does not
 * include it in the public TypeScript interface (which only declares `.digest()`).
 * This function performs an `"xof" in hasher` check and, if it passes, narrows
 * the type to `Shake256ExtendableOutputHasher` via TypeScript's `asserts` narrowing.
 *
 * If the check fails (e.g., after a library upgrade that changes this behaviour),
 * a descriptive error is thrown early so that callers do not encounter cryptic
 * undefined-property errors at field-sampling time.
 *
 * @param hasher - A freshly created `shake256` hasher instance
 *
 * @throws `Error` if the hasher does not expose a `.xof()` method
 *
 * @example
 * ```typescript
 * const h = shake256.create({ dkLen: 48 });
 * assertXofMode(h);
 * const bytes = h.xof(48); // now type-safe
 * ```
 *
 * @internal
 */
function assertXofMode(
  hasher: ReturnType<typeof shake256.create>,
): asserts hasher is ReturnType<typeof shake256.create> & Shake256ExtendableOutputHasher {
  if (!("xof" in hasher)) {
    throw new Error("shake256 hasher does not support XOF mode");
  }
}

/* =============================================================================
 * SERIALIZATION
 * ============================================================================= */

/**
 * Serialises a `bigint` as a fixed-length little-endian byte array.
 *
 * @remarks
 * Iterates from the least significant byte to the most significant byte,
 * masking off one byte at a time with `0xff` and shifting right.
 *
 * If `value` has more significant bits than `lengthInBytes * 8`, the excess
 * high bits are silently truncated. Callers are responsible for ensuring the
 * value fits in the requested byte length.
 *
 * This function is used to serialise ciphertext field elements into 32-byte
 * `number[]` arrays for the `RescueCipherInstance.encrypt` return type, and
 * also to convert the nonce bigint back for key schedule inputs.
 *
 * @param value - The non-negative bigint to serialise
 * @param lengthInBytes - The exact byte length of the output array
 * @returns A `Uint8Array` of `lengthInBytes` bytes in little-endian order
 *
 * @example
 * ```typescript
 * serializeBigintToLittleEndianBytes(256n, 4);
 * // Uint8Array [0, 1, 0, 0]  (256 = 0x100 in LE)
 *
 * serializeBigintToLittleEndianBytes(1n, 32);
 * // Uint8Array [1, 0, 0, ..., 0]  (32 bytes, first byte = 1)
 * ```
 *
 * @internal
 */
function serializeBigintToLittleEndianBytes(value: bigint, lengthInBytes: number): Uint8Array {
  const result = new Uint8Array(lengthInBytes);
  let remaining = value;
  for (let byteIndex = 0; byteIndex < lengthInBytes; byteIndex++) {
    result[byteIndex] = Number(remaining & 0xffn);
    remaining >>= 8n;
  }
  return result;
}

/**
 * Deserialises a little-endian byte array into a `bigint`.
 *
 * @remarks
 * Each byte at position `i` contributes `byte * 2^(8*i)` to the result.
 * The function uses JavaScript's built-in `BigInt()` constructor and bitwise
 * OR to accumulate the value without intermediate modular reduction.
 *
 * Used to convert:
 * - 16-byte nonces into bigints for the CTR counter block
 * - 32-byte shared secrets into field elements for the KDF input
 * - 32-byte ciphertext elements back into bigints during decryption
 * - 48-byte SHAKE256 samples into split `low256`/`high128` bigints for
 *   field-element reduction
 *
 * @param bytes - A `Uint8Array` of bytes in little-endian order
 * @returns The reconstructed non-negative `bigint`
 *
 * @example
 * ```typescript
 * deserializeLittleEndianBytesToBigint(new Uint8Array([0, 1, 0, 0]));
 * // 256n  (0x100)
 *
 * deserializeLittleEndianBytesToBigint(new Uint8Array([255, 255]));
 * // 65535n  (0xFFFF)
 * ```
 *
 * @internal
 */
function deserializeLittleEndianBytesToBigint(bytes: Uint8Array): bigint {
  let result = 0n;
  for (const [byteIndex, byte] of bytes.entries()) {
    result |= BigInt(byte) << (BigInt(byteIndex) * 8n);
  }
  return result;
}

/* =============================================================================
 * FIELD OPERATIONS
 * ============================================================================= */

/**
 * Module-level singleton cache for the default `FieldArithmetic` adapter.
 *
 * @remarks
 * Lazily initialised on the first call to `getFieldArithmetic()`. Storing the
 * adapter as a module-level variable avoids re-creating the object on every
 * cipher or hash instantiation.
 *
 * @internal
 */
let cachedFieldArithmetic: FieldArithmetic | null = null;

/**
 * Creates a new `FieldArithmetic` adapter wrapping the SDK's `math/curve25519`
 * module functions.
 *
 * @remarks
 * The adapter maps the generic `FieldArithmetic` interface to the
 * concrete curve25519 field operations exported from
 * `../../math/curve25519/field-arithmetic`. The `create` method performs a
 * double modulo to handle negative inputs correctly:
 * ```
 * create(v) = ((v % p) + p) % p
 * ```
 *
 * @returns A fresh `FieldArithmetic` object; not cached — callers should use
 *   `getFieldArithmetic()` instead to get the cached singleton
 *
 * @example
 * ```typescript
 * const F = createFieldArithmeticAdapter();
 * F.add(F.ORDER - 1n, 1n); // 0n  (wraps around)
 * F.mul(2n, F.inv(2n));     // 1n
 * ```
 *
 * @internal
 */
function createFieldArithmeticAdapter(): FieldArithmetic {
  return {
    ORDER: CURVE25519_FIELD_PRIME,
    BYTES: 32,
    ZERO: 0n,
    ONE: 1n,
    create: (value: bigint) =>
      ((value % CURVE25519_FIELD_PRIME) + CURVE25519_FIELD_PRIME) % CURVE25519_FIELD_PRIME,
    add: curve25519ModuloAdd,
    sub: curve25519ModuloSub,
    mul: curve25519ModuloMul,
    inv: curve25519ModuloInv,
    pow: curve25519ModuloPow,
    is0: (a: bigint) => a === 0n,
  };
}

/**
 * Returns the singleton `FieldArithmetic` adapter for the Curve25519 base field.
 *
 * @remarks
 * On the first call, `createFieldArithmeticAdapter()` is invoked and the result
 * is stored in the module-level `cachedFieldArithmetic` variable. Subsequent
 * calls return the cached instance without any allocation.
 *
 * This function is exported so that callers (e.g., the key derivation function
 * injected via `RescueCipherDeps`) can retrieve the same field arithmetic
 * instance that the cipher and hash use internally.
 *
 * @returns The cached `FieldArithmetic` adapter operating over GF(2^255 - 19)
 *
 * @example
 * ```typescript
 * import { getFieldArithmetic } from "./index";
 *
 * const F = getFieldArithmetic();
 * const a = F.create(-1n);      // FIELD_PRIME - 1n
 * const b = F.add(a, F.ONE);    // 0n
 * const c = F.pow(2n, 10n);     // 1024n
 * ```
 *
 * @public
 */
export function getFieldArithmetic(): FieldArithmetic {
  if (cachedFieldArithmetic !== null) {
    return cachedFieldArithmetic;
  }
  cachedFieldArithmetic = createFieldArithmeticAdapter();
  return cachedFieldArithmetic;
}

/* =============================================================================
 * MATRIX OPERATIONS
 *
 * Matrices are stored as bigint[][] where data[row][col].
 * Column vectors are data[row][0] (m rows, 1 column).
 * ============================================================================= */

/**
 * Computes the product of two matrices using field arithmetic.
 *
 * @remarks
 * Implements the standard matrix multiplication algorithm:
 * ```
 * result[i][j] = sum_{k} (a[i][k] * b[k][j])  (all arithmetic mod p)
 * ```
 *
 * The caller is responsible for ensuring that the inner dimensions are
 * compatible: `matrixA[0].length === matrixB.length`. No dimension validation
 * is performed; a mismatch will cause `getElement` to throw an out-of-bounds error.
 *
 * This is the most computationally expensive operation in the Rescue permutation:
 * for an `m x m` MDS matrix, each permutation call requires `m^2` field
 * multiplications per half-round.
 *
 * @param fieldArithmetic - Field arithmetic to use for element-wise operations
 * @param matrixA - Left operand, `r x k` matrix stored as `bigint[][]`
 * @param matrixB - Right operand, `k x c` matrix stored as `bigint[][]`
 * @returns A new `r x c` matrix stored as `bigint[][]`
 *
 * @example
 * ```typescript
 * const F = getFieldArithmetic();
 * const identity = [[1n, 0n], [0n, 1n]];
 * const m = [[2n, 3n], [4n, 5n]];
 * multiplyMatrices(F, identity, m); // [[2n, 3n], [4n, 5n]]
 * ```
 *
 * @internal
 */
function multiplyMatrices(
  fieldArithmetic: FieldArithmetic,
  matrixA: bigint[][],
  matrixB: bigint[][],
): bigint[][] {
  const rowCount = matrixA.length;
  const columnCount = getElement(matrixB, 0).length;
  const innerDimension = getElement(matrixA, 0).length;
  const result: bigint[][] = [];
  for (let rowIndex = 0; rowIndex < rowCount; rowIndex++) {
    const row: bigint[] = [];
    for (let colIndex = 0; colIndex < columnCount; colIndex++) {
      let sum = 0n;
      for (let innerIndex = 0; innerIndex < innerDimension; innerIndex++) {
        sum = fieldArithmetic.add(
          sum,
          fieldArithmetic.mul(
            getMatrixElement(matrixA, rowIndex, innerIndex),
            getMatrixElement(matrixB, innerIndex, colIndex),
          ),
        );
      }
      row.push(sum);
    }
    result.push(row);
  }
  return result;
}

/**
 * Computes the element-wise sum of two matrices using field arithmetic.
 *
 * @remarks
 * Both matrices must have identical dimensions. Each element of the result
 * satisfies:
 * ```
 * result[i][j] = (a[i][j] + b[i][j]) mod p
 * ```
 *
 * Used during the Rescue permutation to add round constant vectors to the
 * current state (where the state and round constants are both `m x 1` column
 * vectors).
 *
 * @param fieldArithmetic - Field arithmetic for element-wise addition
 * @param matrixA - First operand matrix
 * @param matrixB - Second operand matrix (same dimensions as `matrixA`)
 * @returns A new matrix with each element being the field sum of the inputs
 *
 * @example
 * ```typescript
 * const F = getFieldArithmetic();
 * addMatrices(F, [[1n], [2n]], [[3n], [4n]]); // [[4n], [6n]]
 * ```
 *
 * @internal
 */
function addMatrices(
  fieldArithmetic: FieldArithmetic,
  matrixA: bigint[][],
  matrixB: bigint[][],
): bigint[][] {
  return matrixA.map((row, rowIndex) =>
    row.map((value, colIndex) =>
      fieldArithmetic.add(value, getMatrixElement(matrixB, rowIndex, colIndex)),
    ),
  );
}

/**
 * Element-wise matrix addition using constant-time bigint arithmetic.
 *
 * @remarks
 * Unlike `addMatrices` (which delegates to `fieldArithmetic.add`), this variant
 * performs the modular reduction using the constant-time bit-array helpers
 * (`constantTimeAdd`, `constantTimeLessThan`, `constantTimeSelect`,
 * `constantTimeSubtract`) to resist timing side-channel attacks.
 *
 * The reduction computes:
 * ```
 * s = a + b   (constant-time addition, may overflow p)
 * r = s < p ? s : s - p   (constant-time conditional subtraction)
 * ```
 *
 * Used during the sponge absorption phase (where the message block is XOR'd
 * into the sponge state before each permutation call) to prevent leaking
 * information about the sponge state through timing differences.
 *
 * @param matrixA - First operand matrix of field elements
 * @param matrixB - Second operand matrix of field elements (same dimensions)
 * @param binarySize - Bit width for the constant-time arithmetic (from `computeBinarySize`)
 * @returns A new matrix with each element being `(a[i][j] + b[i][j]) mod p`,
 *   computed in constant time
 *
 * @see `constantTimeAdd` — the underlying constant-time addition primitive
 * @see `computeBinarySize` — computes the required `binarySize` from the field order
 *
 * @internal
 */
function addMatricesConstantTime(
  matrixA: bigint[][],
  matrixB: bigint[][],
  binarySize: bigint,
): bigint[][] {
  return matrixA.map((row, rowIndex) =>
    row.map((value, colIndex) => {
      const sum = constantTimeAdd(value, getMatrixElement(matrixB, rowIndex, colIndex), binarySize);
      return constantTimeSelect(
        constantTimeLessThan(sum, FIELD_PRIME, binarySize),
        sum,
        constantTimeSubtract(sum, FIELD_PRIME, binarySize),
        binarySize,
      );
    }),
  );
}

/**
 * Applies element-wise modular exponentiation to every element of a matrix.
 *
 * @remarks
 * Returns a new matrix where each element `e` is replaced with
 * `fieldArithmetic.pow(e, exponent)`. This implements the S-box layer of the
 * Rescue permutation: raising each state element to the power `ALPHA` (forward
 * S-box) or `ALPHA_INVERSE` (inverse S-box).
 *
 * @param fieldArithmetic - Field arithmetic providing the `pow` operation
 * @param matrix - Input matrix of field elements
 * @param exponent - The exponent to raise each element to (e.g., `ALPHA` or `ALPHA_INVERSE`)
 * @returns A new matrix with each element raised to `exponent` mod p
 *
 * @example
 * ```typescript
 * const F = getFieldArithmetic();
 * // Apply the forward S-box (x^5) to a 1-element matrix
 * exponentiateMatrixElements(F, [[2n]], 5n); // [[32n]]  (2^5 = 32)
 * ```
 *
 * @internal
 */
function exponentiateMatrixElements(
  fieldArithmetic: FieldArithmetic,
  matrix: bigint[][],
  exponent: bigint,
): bigint[][] {
  return matrix.map((row) => row.map((value) => fieldArithmetic.pow(value, exponent)));
}

/**
 * Converts a flat array of field elements into a column vector (m x 1 matrix).
 *
 * @remarks
 * In this implementation, the Rescue permutation operates on column vectors
 * represented as `bigint[][]` (a matrix with one column). This function wraps
 * a flat `bigint[]` of length `m` into a `m x 1` matrix where each row
 * contains a single element: `[[v0], [v1], ..., [vm-1]]`.
 *
 * This representation is necessary for the matrix multiplication in
 * `multiplyMatrices` to work correctly.
 *
 * @param array - Flat array of field elements to convert
 * @returns A column vector (each row is a length-1 array)
 *
 * @example
 * ```typescript
 * toColumnVector([1n, 2n, 3n]); // [[1n], [2n], [3n]]
 * ```
 *
 * @see `fromColumnVector` — the inverse operation
 *
 * @internal
 */
function toColumnVector(array: bigint[]): bigint[][] {
  return array.map((value) => [value]);
}

/**
 * Extracts a flat array of field elements from an m x 1 column vector matrix.
 *
 * @remarks
 * This is the inverse of `toColumnVector`. After the Rescue permutation
 * produces its output as a column vector (m x 1 matrix), this function
 * flattens it back to a plain `bigint[]`.
 *
 * @param matrix - A column vector (each row must have exactly one element)
 * @returns Flat array of field elements extracted from column 0 of each row
 *
 * @throws `Error` (via `getElement`) if any row has zero elements
 *
 * @example
 * ```typescript
 * fromColumnVector([[1n], [2n], [3n]]); // [1n, 2n, 3n]
 * ```
 *
 * @see `toColumnVector` — the inverse operation
 *
 * @internal
 */
function fromColumnVector(matrix: bigint[][]): bigint[] {
  return matrix.map((row) => getElement(row, 0));
}

/**
 * Computes the determinant of a square matrix over the field using Laplace cofactor expansion.
 *
 * @remarks
 * Uses recursive cofactor expansion along the top row. Time complexity is
 * `O(m!)` in the general case, but this function is only called once per
 * cipher instantiation (to verify that the round constant matrix is invertible)
 * and only on small matrices (`m = BLOCK_SIZE = 5`), so the exponential
 * growth is acceptable.
 *
 * The base case for a 1x1 matrix returns the single element. Cofactors for
 * even columns are positive, odd columns are negated via `sub(0, element)`.
 *
 * @param fieldArithmetic - Field arithmetic for all intermediate operations
 * @param matrix - Square matrix of field elements (any dimension ≥ 1)
 * @returns The determinant as a field element in `[0, ORDER)`
 *
 * @example
 * ```typescript
 * const F = getFieldArithmetic();
 * // det([[1,2],[3,4]]) = 1*4 - 2*3 = 4 - 6 = -2 ≡ p-2 (mod p)
 * computeMatrixDeterminant(F, [[1n,2n],[3n,4n]]); // FIELD_PRIME - 2n
 * // det([[0,0],[0,0]]) = 0 → matrix is singular
 * computeMatrixDeterminant(F, [[0n,0n],[0n,0n]]); // 0n
 * ```
 *
 * @internal
 */
function computeMatrixDeterminant(fieldArithmetic: FieldArithmetic, matrix: bigint[][]): bigint {
  const dimension = matrix.length;
  if (dimension === 1) {
    return getMatrixElement(matrix, 0, 0);
  }
  let determinant = 0n;
  for (let colIndex = 0; colIndex < dimension; colIndex++) {
    const minor: bigint[][] = [];
    for (let rowIndex = 1; rowIndex < dimension; rowIndex++) {
      const minorRow: bigint[] = [];
      for (let innerCol = 0; innerCol < dimension; innerCol++) {
        if (innerCol !== colIndex) {
          minorRow.push(getMatrixElement(matrix, rowIndex, innerCol));
        }
      }
      minor.push(minorRow);
    }
    const cofactor =
      colIndex % 2 === 0
        ? getMatrixElement(matrix, 0, colIndex)
        : fieldArithmetic.sub(0n, getMatrixElement(matrix, 0, colIndex));
    determinant = fieldArithmetic.add(
      determinant,
      fieldArithmetic.mul(cofactor, computeMatrixDeterminant(fieldArithmetic, minor)),
    );
  }
  return determinant;
}

/* =============================================================================
 * CONSTANT-TIME HELPERS
 *
 * 2's complement bit-array arithmetic for side-channel resistance in CTR mode.
 * Ported from @arcium-hq/client's ctAdd/ctSub/ctSelect.
 * ============================================================================= */

/**
 * Converts a bigint to a little-endian boolean bit array of a fixed width.
 *
 * @remarks
 * Bit `i` of the result is `true` if bit `i` of `value` is set. The array has
 * exactly `binarySize` entries. Bits beyond `value`'s significant bits are
 * always `false`.
 *
 * This is the entry point for the constant-time arithmetic pipeline: all
 * subsequent operations consume and produce boolean arrays to avoid leaking
 * timing information through data-dependent branch prediction.
 *
 * @param value - The non-negative bigint to convert
 * @param binarySize - Number of bits in the output (must be ≥ `value.bit_length()`)
 * @returns A boolean array where index `i` corresponds to bit `2^i` of `value`
 *
 * @example
 * ```typescript
 * toBinaryLittleEndian(5n, 4n); // [true, false, true, false]  (5 = 0b101)
 * ```
 *
 * @internal
 */
function toBinaryLittleEndian(value: bigint, binarySize: bigint): boolean[] {
  const result: boolean[] = [];
  for (let bitIndex = 0n; bitIndex < binarySize; ++bitIndex) {
    result.push(((value >> bitIndex) & 1n) === 1n);
  }
  return result;
}

/**
 * Converts a little-endian boolean bit array (in 2's complement) back to a bigint.
 *
 * @remarks
 * Interprets the input as a 2's complement signed integer where the last bit
 * is the sign bit. The conversion is:
 * ```
 * value = (sum of bits[i] * 2^i for i = 0..n-2)
 *       - (bits[n-1] * 2^(n-1))   (sign bit negates)
 * ```
 *
 * This 2's complement interpretation is essential for the constant-time
 * subtraction (`constantTimeSubtract`) to correctly represent negative
 * intermediate results, which are then detected by `constantTimeSignBit`.
 *
 * @param binaryBits - Boolean array in little-endian bit order (2's complement)
 * @returns The signed `bigint` value represented by the bits
 *
 * @example
 * ```typescript
 * // Positive: 0b0101 = 5
 * fromBinaryLittleEndian([true, false, true, false]); // 5n
 * // Negative (2's complement): 0b1111 = -1 in 4-bit 2's complement
 * fromBinaryLittleEndian([true, true, true, true]); // -1n
 * ```
 *
 * @internal
 */
function fromBinaryLittleEndian(binaryBits: boolean[]): bigint {
  let result = 0n;
  for (let bitIndex = 0; bitIndex < binaryBits.length - 1; ++bitIndex) {
    result |= BigInt(getElement(binaryBits, bitIndex)) << BigInt(bitIndex);
  }
  return (
    result -
    (BigInt(getElement(binaryBits, binaryBits.length - 1)) << BigInt(binaryBits.length - 1))
  );
}

/**
 * A constant-time full-adder operating on two boolean bit arrays.
 *
 * @remarks
 * Computes `bitsX + bitsY + carryIn` bit-by-bit using XOR and AND gates that
 * have data-independent control flow. This is the fundamental building block
 * for all constant-time arithmetic in this module.
 *
 * The implementation uses only boolean operations (`!==`, `&&`), which are
 * branch-free on most JavaScript engines when compiled to native code.
 * The carry propagation at each step follows:
 * ```
 * sum[i]   = x[i] XOR y[i] XOR carry
 * carry'   = (x[i] AND y[i]) OR (carry AND (x[i] XOR y[i]))
 * ```
 *
 * @param bitsX - First operand as a little-endian boolean bit array
 * @param bitsY - Second operand as a little-endian boolean bit array (same length as `bitsX`)
 * @param carryIn - Initial carry bit (true = 1, false = 0)
 * @param binarySize - Number of bits to process (should equal `bitsX.length`)
 * @returns The sum as a little-endian boolean bit array
 *
 * @example
 * ```typescript
 * // 3 (011) + 1 (001) = 4 (100) in 4 bits
 * const bitsA = [true, true, false, false]; // 3 in LE
 * const bitsB = [true, false, false, false]; // 1 in LE
 * binaryAdder(bitsA, bitsB, false, 4n);
 * // [false, false, true, false]  → 4
 * ```
 *
 * @internal
 */
function binaryAdder(
  bitsX: boolean[],
  bitsY: boolean[],
  carryIn: boolean,
  binarySize: bigint,
): boolean[] {
  const result: boolean[] = [];
  let carry = carryIn;
  for (let bitIndex = 0; bitIndex < Number(binarySize); ++bitIndex) {
    const bitY = getElement(bitsY, bitIndex);
    const bitX = getElement(bitsX, bitIndex);
    const yXorCarry = bitY !== carry;
    result.push(bitX !== yXorCarry);
    carry = bitY !== (yXorCarry && bitX !== bitY);
  }
  return result;
}

/**
 * Adds two field-range bigints using constant-time bit-array arithmetic.
 *
 * @remarks
 * Converts both operands to `binarySize`-wide boolean arrays, feeds them
 * through `binaryAdder`, and converts the result back to a bigint. The
 * returned value may be larger than `FIELD_PRIME` if the sum overflows; the
 * caller is responsible for applying the conditional subtraction via
 * `constantTimeSelect`.
 *
 * @param valueX - First addend; must be a non-negative bigint < 2^(binarySize-1)
 * @param valueY - Second addend; must be a non-negative bigint < 2^(binarySize-1)
 * @param binarySize - Bit width of the arithmetic (from `computeBinarySize`)
 * @returns `valueX + valueY` as a signed 2's complement bigint at `binarySize` bits
 *
 * @example
 * ```typescript
 * const binarySize = computeBinarySize(FIELD_PRIME - 1n);
 * constantTimeAdd(10n, 20n, binarySize); // 30n
 * ```
 *
 * @internal
 */
function constantTimeAdd(valueX: bigint, valueY: bigint, binarySize: bigint): bigint {
  const resultBits = binaryAdder(
    toBinaryLittleEndian(valueX, binarySize),
    toBinaryLittleEndian(valueY, binarySize),
    false,
    binarySize,
  );
  return fromBinaryLittleEndian(resultBits);
}

/**
 * Subtracts one bigint from another using constant-time bit-array arithmetic.
 *
 * @remarks
 * Implements subtraction via the 2's complement trick:
 * ```
 * x - y = x + (~y) + 1
 * ```
 * where `~y` means bitwise NOT (invert all bits of the boolean array). The
 * carry-in of 1 to `binaryAdder` provides the `+1`.
 *
 * The returned value is the 2's complement representation of `x - y` at
 * `binarySize` bits. If the result is negative (i.e., `x < y`), the sign bit
 * (bit `binarySize`) will be set, which is detected by `constantTimeSignBit`.
 *
 * @param valueX - Minuend; must be a non-negative bigint < 2^(binarySize-1)
 * @param valueY - Subtrahend; must be a non-negative bigint < 2^(binarySize-1)
 * @param binarySize - Bit width of the arithmetic (from `computeBinarySize`)
 * @returns `valueX - valueY` as a signed 2's complement bigint at `binarySize` bits
 *
 * @example
 * ```typescript
 * const binarySize = computeBinarySize(FIELD_PRIME - 1n);
 * constantTimeSubtract(10n, 3n, binarySize);  // 7n
 * constantTimeSubtract(3n, 10n, binarySize);  // negative (sign bit set)
 * ```
 *
 * @internal
 */
function constantTimeSubtract(valueX: bigint, valueY: bigint, binarySize: bigint): bigint {
  const bitsY = toBinaryLittleEndian(valueY, binarySize);
  const invertedBitsY = bitsY.map((bit) => !bit);
  const resultBits = binaryAdder(
    toBinaryLittleEndian(valueX, binarySize),
    invertedBitsY,
    true,
    binarySize,
  );
  return fromBinaryLittleEndian(resultBits);
}

/**
 * Extracts the 2's complement sign bit from a constant-time arithmetic result.
 *
 * @remarks
 * In a `binarySize`-bit 2's complement representation, the most significant bit
 * at position `binarySize` (the `(binarySize+1)`-th bit) determines the sign.
 * This function checks whether that bit is set, indicating a negative value
 * (i.e., the result of a constant-time subtraction underflowed).
 *
 * Used by `constantTimeLessThan` to detect `x < y` after computing `x - y`.
 *
 * @param value - A signed 2's complement bigint at `binarySize` bits
 * @param binarySize - The bit width used in the constant-time arithmetic
 * @returns `true` if `value` is negative (sign bit set), `false` otherwise
 *
 * @example
 * ```typescript
 * const binarySize = computeBinarySize(FIELD_PRIME - 1n);
 * const diff = constantTimeSubtract(3n, 10n, binarySize); // negative
 * constantTimeSignBit(diff, binarySize); // true
 * ```
 *
 * @internal
 */
function constantTimeSignBit(value: bigint, binarySize: bigint): boolean {
  return ((value >> binarySize) & 1n) === 1n;
}

/**
 * Tests whether `valueX < valueY` using constant-time bit-array arithmetic.
 *
 * @remarks
 * Computes `x - y` via `constantTimeSubtract` and then checks the sign bit
 * via `constantTimeSignBit`. If the subtraction underflows (sign bit set),
 * then `x < y`.
 *
 * The entire comparison runs in constant time, independent of the actual
 * values of `x` and `y`. This is important in the CTR encryption loop where
 * the compared values may be sensitive (plaintext-derived).
 *
 * @param valueX - Left operand
 * @param valueY - Right operand
 * @param binarySize - Bit width from `computeBinarySize`
 * @returns `true` if `valueX < valueY`, `false` otherwise
 *
 * @example
 * ```typescript
 * const binarySize = computeBinarySize(FIELD_PRIME - 1n);
 * constantTimeLessThan(3n, 10n, binarySize); // true
 * constantTimeLessThan(10n, 3n, binarySize); // false
 * ```
 *
 * @internal
 */
function constantTimeLessThan(valueX: bigint, valueY: bigint, binarySize: bigint): boolean {
  return constantTimeSignBit(constantTimeSubtract(valueX, valueY, binarySize), binarySize);
}

/**
 * Selects between two bigints based on a boolean condition, in constant time.
 *
 * @remarks
 * Implements the constant-time conditional move (`cmov`) pattern:
 * ```
 * result = ifFalse + condition * (ifTrue - ifFalse)
 * ```
 * where the multiplication by `BigInt(condition)` (0 or 1) and the addition
 * are both performed via the constant-time bit-array helpers. The result
 * equals `valueIfTrue` when `condition` is `true` and `valueIfFalse`
 * when `condition` is `false`, without any data-dependent branching.
 *
 * @param condition - Boolean selector (true → return `valueIfTrue`)
 * @param valueIfTrue - Value returned when `condition` is `true`
 * @param valueIfFalse - Value returned when `condition` is `false`
 * @param binarySize - Bit width from `computeBinarySize`
 * @returns `valueIfTrue` if `condition`, otherwise `valueIfFalse`
 *
 * @example
 * ```typescript
 * const binarySize = computeBinarySize(FIELD_PRIME - 1n);
 * constantTimeSelect(true, 42n, 99n, binarySize);  // 42n
 * constantTimeSelect(false, 42n, 99n, binarySize); // 99n
 * ```
 *
 * @internal
 */
function constantTimeSelect(
  condition: boolean,
  valueIfTrue: bigint,
  valueIfFalse: bigint,
  binarySize: bigint,
): bigint {
  return constantTimeAdd(
    valueIfFalse,
    BigInt(condition) * constantTimeSubtract(valueIfTrue, valueIfFalse, binarySize),
    binarySize,
  );
}

/**
 * Computes the required bit width for constant-time arithmetic on values up to `maxValue`.
 *
 * @remarks
 * Adds 3 bits of headroom above `floor(log2(maxValue))` to accommodate:
 * - 1 bit for the 2's complement sign in subtraction results
 * - 2 bits for overflow in intermediate additions (sum of two field elements
 *   can be at most `2*p - 2 < 2^256`)
 *
 * For the Curve25519 field where `maxValue = p - 1`:
 * ```
 * binarySize = floor(log2(p-1)) + 3 = 254 + 3 = 257
 * ```
 *
 * @param maxValue - The maximum value that will appear as an operand in
 *   constant-time arithmetic (typically `fieldArithmetic.ORDER - 1n`)
 * @returns The bit width to use for all constant-time operations
 *
 * @example
 * ```typescript
 * computeBinarySize(FIELD_PRIME - 1n); // 257n
 * computeBinarySize(255n);             // 10n  (floor(log2(255)) + 3 = 7 + 3)
 * ```
 *
 * @internal
 */
function computeBinarySize(maxValue: bigint): bigint {
  return BigInt(Math.floor(Math.log2(Number(maxValue)))) + 3n;
}

/* =============================================================================
 * SHAKE256 FIELD ELEMENT SAMPLING
 * ============================================================================= */

/**
 * Creates a stateful SHAKE256 XOF sampler that yields uniformly distributed
 * field elements on each invocation.
 *
 * @remarks
 * Seeds a SHAKE256 XOF with the provided ASCII `seed` string. Each call to the
 * returned function reads `SAMPLE_BUFFER_BYTE_LENGTH = 48` bytes from the XOF
 * output stream and reduces them to a field element via `reduceToFieldElement`.
 *
 * Because SHAKE256 is an XOF, successive calls to the returned function advance
 * the stream cursor, producing non-overlapping 48-byte windows. This allows
 * arbitrarily many field elements to be sampled from a single seeded instance
 * without re-hashing.
 *
 * The `assertXofMode` guard ensures that the `@noble/hashes` SHAKE256 instance
 * exposes `.xof()` at runtime before sampling begins.
 *
 * @param seed - ASCII domain-separation string used to initialise the XOF
 * @param fieldArithmetic - Field arithmetic for the `reduceToFieldElement` call
 * @returns A zero-argument function that produces one GF(p) element per call
 *
 * @example
 * ```typescript
 * const sample = createShake256FieldElementSampler("my-seed", getFieldArithmetic());
 * const e1 = sample(); // first field element
 * const e2 = sample(); // second (independent) field element
 * ```
 *
 * @see `reduceToFieldElement` — the 48-byte-to-field-element reduction
 * @see {@link SHAKE256_CIPHER_SEED} — the seed used for cipher round constants
 *
 * @internal
 */
function createShake256FieldElementSampler(
  seed: string,
  fieldArithmetic: FieldArithmetic,
): () => bigint {
  const encoder = new TextEncoder();
  const hasher = shake256.create({ dkLen: SAMPLE_BUFFER_BYTE_LENGTH });
  hasher.update(encoder.encode(seed));

  assertXofMode(hasher);
  const xofHasher: Shake256ExtendableOutputHasher = hasher;

  return (): bigint => {
    const randomBytes = xofHasher.xof(SAMPLE_BUFFER_BYTE_LENGTH);
    return reduceToFieldElement(randomBytes, fieldArithmetic);
  };
}

/**
 * Reduces a 48-byte (384-bit) SHAKE256 sample to a field element in GF(p).
 *
 * @remarks
 * The reduction uses the Curve25519 fast-reduction identity `2^256 ≡ 38 (mod p)`:
 *
 * 1. Read `low256` from bytes 0..31 (little-endian bigint, 256 bits).
 * 2. Read `high128` from bytes 32..47 (little-endian bigint, 128 bits).
 * 3. Compute `element = (low256 + high128 * 38) mod p` via `fieldArithmetic.create`.
 *
 * The extra 128 bits (beyond the 255-bit field prime) ensure that the
 * statistical distance of the output distribution from uniform GF(p) is at
 * most `2^(-128)`, which is negligible for 128-bit security targets.
 *
 * @param bytes - A `Uint8Array` of exactly `SAMPLE_BUFFER_BYTE_LENGTH = 48` bytes
 * @param fieldArithmetic - Field arithmetic providing the `create` reduction method
 * @returns A uniformly distributed field element in `[0, ORDER)`
 *
 * @example
 * ```typescript
 * const F = getFieldArithmetic();
 * const sample = new Uint8Array(48).fill(0xff);
 * const elem = reduceToFieldElement(sample, F);
 * // elem is a valid field element: 0 <= elem < FIELD_PRIME
 * ```
 *
 * @see {@link REDUCTION_CONST} — the constant `2^256 mod p = 38`
 * @see {@link SAMPLE_BUFFER_BYTE_LENGTH} — the 48-byte sample window size
 *
 * @internal
 */
function reduceToFieldElement(bytes: Uint8Array, fieldArithmetic: FieldArithmetic): bigint {
  const lowBits = deserializeLittleEndianBytesToBigint(bytes.subarray(0, 32));
  const highBits = deserializeLittleEndianBytesToBigint(bytes.subarray(32, 48));
  return fieldArithmetic.create(lowBits + highBits * REDUCTION_CONST);
}

/* =============================================================================
 * MDS MATRIX CONSTRUCTION
 * ============================================================================= */

/**
 * Module-level cache for the 5x5 cipher MDS matrix.
 *
 * @remarks
 * Lazily populated by `buildCipherMdsMatrix()` on first use. The matrix is
 * independent of any key or message, so it is safe to cache as a module
 * singleton.
 *
 * @internal
 */
let cachedCipherMdsMatrix: bigint[][] | null = null;

/**
 * Module-level cache for the 12x12 hash MDS matrix.
 *
 * @remarks
 * Lazily populated by `buildHashMdsMatrix()` on first use.
 *
 * @internal
 */
let cachedHashMdsMatrix: bigint[][] | null = null;

/**
 * Builds (and caches) the 5x5 Cauchy MDS matrix for cipher mode.
 *
 * @remarks
 * The Maximum Distance Separable (MDS) matrix is a key component of the
 * Rescue permutation's linear layer. It ensures that any non-zero difference
 * in the input to the linear layer results in at least `m + 1 = 6` non-zero
 * differences in the concatenation of input and output (the branch number).
 *
 * The matrix is defined as a Cauchy matrix:
 * ```
 * M[i][j] = 1 / (i + j + 2)   for i, j = 0..4
 * ```
 * This maps to `PRECOMPUTED_FIELD_INVERSES[i + j]` because:
 * ```
 * 1 / (i + j + 2)  →  PRECOMPUTED_FIELD_INVERSES[(i + j + 2) - 2] = index i + j
 * ```
 *
 * The Cauchy structure guarantees the MDS property as long as all
 * `(i + j + 2)` are distinct and non-zero in GF(p), which holds trivially
 * since 2 through 10 are all much smaller than p.
 *
 * @returns The cached 5x5 MDS matrix as a `bigint[][]`
 *
 * @example
 * ```typescript
 * const mds = buildCipherMdsMatrix();
 * // mds[0][0] = 1/2 mod p, mds[0][1] = 1/3 mod p, ..., mds[4][4] = 1/10 mod p
 * ```
 *
 * @see {@link PRECOMPUTED_FIELD_INVERSES} — the precomputed inverse table
 * @see {@link BLOCK_SIZE} — the cipher state width (5)
 *
 * @internal
 */
function buildCipherMdsMatrix(): bigint[][] {
  if (cachedCipherMdsMatrix !== null) {
    return cachedCipherMdsMatrix;
  }

  const dimension = BLOCK_SIZE;
  const matrixData: bigint[][] = [];
  for (let rowIndex = 0; rowIndex < dimension; rowIndex++) {
    const row: bigint[] = [];
    for (let colIndex = 0; colIndex < dimension; colIndex++) {
      // 1/(i+1+j+1) = 1/(i+j+2), index in PRECOMPUTED_FIELD_INVERSES = (i+j+2) - 2 = i+j
      row.push(getElement(PRECOMPUTED_FIELD_INVERSES, rowIndex + colIndex));
    }
    matrixData.push(row);
  }
  cachedCipherMdsMatrix = matrixData;
  return matrixData;
}

/**
 * Builds (and caches) the 12x12 Cauchy MDS matrix for hash mode.
 *
 * @remarks
 * Follows the same Cauchy construction as `buildCipherMdsMatrix`, extended
 * to `HASH_STATE_SIZE = 12` dimensions:
 * ```
 * M[i][j] = 1 / (i + j + 2)   for i, j = 0..11
 * ```
 * Index into `PRECOMPUTED_FIELD_INVERSES` ranges from 0 (1/2) to 22 (1/24),
 * consuming all 23 precomputed values.
 *
 * The branch number of this 12x12 matrix is 13, providing stronger diffusion
 * than the cipher's 5x5 matrix (branch number 6). This is appropriate given
 * the hash's higher security target (256 bits vs 128 bits for the cipher).
 *
 * @returns The cached 12x12 MDS matrix as a `bigint[][]`
 *
 * @example
 * ```typescript
 * const mds = buildHashMdsMatrix();
 * // mds[0][0] = 1/2, ..., mds[11][11] = 1/24 mod p
 * ```
 *
 * @see {@link PRECOMPUTED_FIELD_INVERSES} — requires all 23 entries (indices 0..22)
 * @see {@link HASH_STATE_SIZE} — the hash state width (12)
 *
 * @internal
 */
function buildHashMdsMatrix(): bigint[][] {
  if (cachedHashMdsMatrix !== null) {
    return cachedHashMdsMatrix;
  }

  const dimension = HASH_STATE_SIZE;
  const matrixData: bigint[][] = [];
  for (let rowIndex = 0; rowIndex < dimension; rowIndex++) {
    const row: bigint[] = [];
    for (let colIndex = 0; colIndex < dimension; colIndex++) {
      row.push(getElement(PRECOMPUTED_FIELD_INVERSES, rowIndex + colIndex));
    }
    matrixData.push(row);
  }
  cachedHashMdsMatrix = matrixData;
  return matrixData;
}

/* =============================================================================
 * ROUND CONSTANT GENERATION
 * ============================================================================= */

/**
 * Module-level cache for the cipher round constant vectors.
 *
 * @remarks
 * Contains `2 * CIPHER_ROUND_COUNT + 1 = 21` column vectors once populated.
 * Cached as a module singleton because the constants are purely a function of
 * the field and the cipher seed string, both of which are fixed at compile time.
 *
 * @internal
 */
let cachedCipherRoundConstantVectors: bigint[][][] | null = null;

/**
 * Module-level cache for the hash round constant vectors.
 *
 * @remarks
 * Contains `2 * HASH_ROUND_COUNT + 1 = 17` column vectors (including the
 * prepended zero vector) once populated.
 *
 * @internal
 */
let cachedHashRoundConstantVectors: bigint[][][] | null = null;

/**
 * Samples and caches the cipher round constant vectors using SHAKE256 and an
 * affine recurrence relation.
 *
 * @remarks
 * The cipher round constants are generated following the Rescue-XLIX
 * specification for the cipher instantiation:
 *
 * 1. Sample `m*m + 2*m` field elements from SHAKE256 seeded with
 *    `SHAKE256_CIPHER_SEED = "encrypt everything, compute anything"`.
 * 2. Form a `m x m` round constant matrix `A` and two length-`m` vectors:
 *    the initial vector `c_0` and an affine term `b`.
 * 3. If `det(A) === 0` (singular matrix), resample `A` until it is invertible.
 * 4. Generate `2 * CIPHER_ROUND_COUNT` subsequent vectors via the affine
 *    recurrence:
 *    ```
 *    c_{k+1} = A * c_k + b
 *    ```
 * 5. Return all `2 * CIPHER_ROUND_COUNT + 1` vectors `[c_0, c_1, ..., c_{20}]`.
 *
 * The affine recurrence ensures the round constants have good statistical
 * properties (pseudo-randomness, linear independence) while being compactly
 * generated from a small seed.
 *
 * @param fieldArithmetic - Field arithmetic for matrix operations and determinant check
 * @returns An array of `2 * CIPHER_ROUND_COUNT + 1` column vectors, each of
 *   length `BLOCK_SIZE = 5`
 *
 * @example
 * ```typescript
 * const F = getFieldArithmetic();
 * const constants = sampleCipherRoundConstantVectors(F);
 * // constants.length === 21
 * // constants[0].length === 5  (each is a 5x1 column vector)
 * // constants[0][0].length === 1
 * ```
 *
 * @see {@link SHAKE256_CIPHER_SEED} — the XOF seed string
 * @see `computeMatrixDeterminant` — used to check for matrix singularity
 *
 * @internal
 */
function sampleCipherRoundConstantVectors(fieldArithmetic: FieldArithmetic): bigint[][][] {
  if (cachedCipherRoundConstantVectors !== null) {
    return cachedCipherRoundConstantVectors;
  }

  const dimension = BLOCK_SIZE;
  const roundCount = CIPHER_ROUND_COUNT;
  const sampleFieldElement = createShake256FieldElementSampler(
    SHAKE256_CIPHER_SEED,
    fieldArithmetic,
  );

  // Sample m*m + 2*m elements
  const sampledElements: bigint[] = [];
  for (let elementIndex = 0; elementIndex < dimension * dimension + 2 * dimension; elementIndex++) {
    sampledElements.push(sampleFieldElement());
  }

  // Build round constant matrix (m x m)
  let roundConstantMatrix: bigint[][] = [];
  for (let rowIndex = 0; rowIndex < dimension; rowIndex++) {
    const row: bigint[] = [];
    for (let colIndex = 0; colIndex < dimension; colIndex++) {
      row.push(getElement(sampledElements, rowIndex * dimension + colIndex));
    }
    roundConstantMatrix.push(row);
  }

  // Build initial round constant (m x 1 column vector)
  const initialRoundConstant: bigint[][] = [];
  for (let rowIndex = 0; rowIndex < dimension; rowIndex++) {
    initialRoundConstant.push([getElement(sampledElements, dimension * dimension + rowIndex)]);
  }

  // Build affine term (m x 1 column vector)
  const affineTerm: bigint[][] = [];
  for (let rowIndex = 0; rowIndex < dimension; rowIndex++) {
    affineTerm.push([getElement(sampledElements, dimension * dimension + dimension + rowIndex)]);
  }

  // Resample matrix if singular (determinant = 0)
  while (fieldArithmetic.is0(computeMatrixDeterminant(fieldArithmetic, roundConstantMatrix))) {
    roundConstantMatrix = [];
    for (let rowIndex = 0; rowIndex < dimension; rowIndex++) {
      const row: bigint[] = [];
      for (let colIndex = 0; colIndex < dimension; colIndex++) {
        row.push(sampleFieldElement());
      }
      roundConstantMatrix.push(row);
    }
  }

  // Generate round constants via affine recurrence
  const roundConstantVectors: bigint[][][] = [initialRoundConstant];
  for (let roundIndex = 0; roundIndex < 2 * roundCount; roundIndex++) {
    const previousVector = getElement(roundConstantVectors, roundConstantVectors.length - 1);
    const nextVector = addMatrices(
      fieldArithmetic,
      multiplyMatrices(fieldArithmetic, roundConstantMatrix, previousVector),
      affineTerm,
    );
    roundConstantVectors.push(nextVector);
  }

  cachedCipherRoundConstantVectors = roundConstantVectors;
  return roundConstantVectors;
}

/**
 * Samples and caches the hash round constant vectors using SHAKE256 with
 * direct (non-recurrent) sampling.
 *
 * @remarks
 * The hash round constants follow the standard Rescue-XLIX hash specification
 * rather than the affine recurrence used for cipher constants. The generation
 * procedure is:
 *
 * 1. Prepend a zero vector of length `HASH_STATE_SIZE = 12` as `c_0`.
 * 2. Build a domain-separation seed string:
 *    ```
 *    "Rescue-XLIX(p, 12, 5, 256)"
 *    ```
 *    where `p = fieldArithmetic.ORDER` and the parameters are `m=12`,
 *    `capacity=5`, security level = 256.
 * 3. Sample `2 * HASH_ROUND_COUNT * HASH_STATE_SIZE = 192` field elements
 *    from SHAKE256 seeded with that string.
 * 4. Reshape the flat sample into `2 * HASH_ROUND_COUNT = 16` column vectors
 *    of length `HASH_STATE_SIZE = 12` and append to the zero vector.
 *
 * The resulting array `[c_0, c_1, ..., c_{16}]` has 17 vectors in total.
 *
 * @param fieldArithmetic - Field arithmetic providing `ORDER` for the seed string
 * @returns An array of `2 * HASH_ROUND_COUNT + 1 = 17` column vectors, each of
 *   length `HASH_STATE_SIZE = 12` (the first is always the zero vector)
 *
 * @example
 * ```typescript
 * const F = getFieldArithmetic();
 * const constants = sampleHashRoundConstantVectors(F);
 * // constants.length === 17
 * // constants[0] is all zeros (prepended zero vector)
 * // constants[1..16] are SHAKE256-sampled field elements
 * ```
 *
 * @see `createShake256FieldElementSampler` — the XOF sampler used for generation
 * @see {@link HASH_CAPACITY} — appears in the domain-separation seed string
 *
 * @internal
 */
function sampleHashRoundConstantVectors(fieldArithmetic: FieldArithmetic): bigint[][][] {
  if (cachedHashRoundConstantVectors !== null) {
    return cachedHashRoundConstantVectors;
  }

  const dimension = HASH_STATE_SIZE;
  const roundCount = HASH_ROUND_COUNT;

  // Build hash seed string dynamically
  const hashSeed = `Rescue-XLIX(${String(fieldArithmetic.ORDER)},${String(dimension)},${String(HASH_CAPACITY)},256)`;
  const sampleFieldElement = createShake256FieldElementSampler(hashSeed, fieldArithmetic);

  // Prepend a zero column vector
  const zeroVector: bigint[][] = [];
  for (let rowIndex = 0; rowIndex < dimension; rowIndex++) {
    zeroVector.push([0n]);
  }
  const roundConstantVectors: bigint[][][] = [zeroVector];

  // Sample 2 * roundCount * m elements
  const sampledElements: bigint[] = [];
  for (let elementIndex = 0; elementIndex < 2 * roundCount * dimension; elementIndex++) {
    sampledElements.push(sampleFieldElement());
  }

  // Reshape into column vectors
  for (let vectorIndex = 0; vectorIndex < 2 * roundCount; vectorIndex++) {
    const columnVector: bigint[][] = [];
    for (let rowIndex = 0; rowIndex < dimension; rowIndex++) {
      columnVector.push([getElement(sampledElements, vectorIndex * dimension + rowIndex)]);
    }
    roundConstantVectors.push(columnVector);
  }

  cachedHashRoundConstantVectors = roundConstantVectors;
  return roundConstantVectors;
}

/* =============================================================================
 * RESCUE PERMUTATION
 * ============================================================================= */

/**
 * Runs the Rescue-XLIX permutation and returns ALL intermediate states.
 *
 * @remarks
 * This is the core computational engine of the entire module. It implements
 * the full Rescue-XLIX round function and is used in two contexts:
 *
 * - **Hash mode** (`cipherMode = false`): even half-rounds apply the forward
 *   S-box (`x^ALPHA`), odd half-rounds apply the inverse S-box
 *   (`x^ALPHA_INVERSE`). Round constants (`subkeys`) are publicly fixed.
 *
 * - **Cipher mode** (`cipherMode = true`): the exponent ordering is swapped —
 *   even half-rounds use the inverse S-box and odd half-rounds use the forward
 *   S-box. The `subkeys` are derived from the cipher key (the key schedule).
 *
 * ## Round Structure
 *
 * Each full round consists of two half-rounds. Starting from the initial state
 * `s_0 = state + subkeys[0]`, the permutation proceeds:
 * ```
 * for r = 0..nRounds-1:
 *   s_{2r+1} = MDS * S_even(s_{2r}) + subkeys[2r+1]
 *   s_{2r+2} = MDS * S_odd(s_{2r+1}) + subkeys[2r+2]
 * ```
 * where `S_even` and `S_odd` are element-wise power maps determined by
 * `cipherMode`.
 *
 * ## Intermediate States
 *
 * Unlike a minimal implementation that only returns the final state, this
 * function returns ALL intermediate states `[s_0, s_1, ..., s_{2*nRounds}]`.
 * For hash mode this is wasteful but acceptable (only the final state is used).
 * For the cipher's key schedule, the intermediate states ARE the round keys:
 * the key schedule runs the permutation on the derived key and uses each
 * intermediate state as the subkey for a subsequent CTR encryption.
 *
 * @param fieldArithmetic - Field arithmetic for all operations
 * @param mdsMatrix - The `m x m` MDS matrix (5x5 for cipher, 12x12 for hash)
 * @param subkeys - Array of `2*nRounds + 1` column vectors (each `m x 1`),
 *   used as additive round keys / round constants
 * @param state - The initial `m x 1` column vector
 * @param cipherMode - When `true`, uses inverse S-box in even half-rounds and
 *   forward S-box in odd half-rounds; when `false`, the order is reversed
 * @returns Array of all `2*nRounds + 1` intermediate states, each an `m x 1`
 *   column vector; the last element is the final output state
 *
 * @example
 * ```typescript
 * const F = getFieldArithmetic();
 * const mds = buildCipherMdsMatrix();
 * const constants = sampleCipherRoundConstantVectors(F);
 * const key = toColumnVector([1n, 2n, 3n, 4n, 5n]);
 * const states = computeRescuePermutationWithIntermediateStates(F, mds, constants, key, true);
 * // states.length === 21  (2 * CIPHER_ROUND_COUNT + 1)
 * // fromColumnVector(states[states.length - 1]) is the permuted output
 * ```
 *
 * @internal
 */
function computeRescuePermutationWithIntermediateStates(
  fieldArithmetic: FieldArithmetic,
  mdsMatrix: bigint[][],
  subkeys: bigint[][][],
  state: bigint[][],
  cipherMode: boolean,
): bigint[][][] {
  const exponentEven = cipherMode ? ALPHA_INVERSE : ALPHA;
  const exponentOdd = cipherMode ? ALPHA : ALPHA_INVERSE;

  const intermediateStates: bigint[][][] = [
    addMatrices(fieldArithmetic, state, getElement(subkeys, 0)),
  ];

  for (let roundIndex = 0; roundIndex < subkeys.length - 1; roundIndex++) {
    let currentState = getElement(intermediateStates, intermediateStates.length - 1);
    currentState = exponentiateMatrixElements(
      fieldArithmetic,
      currentState,
      roundIndex % 2 === 0 ? exponentEven : exponentOdd,
    );
    intermediateStates.push(
      addMatrices(
        fieldArithmetic,
        multiplyMatrices(fieldArithmetic, mdsMatrix, currentState),
        getElement(subkeys, roundIndex + 1),
      ),
    );
  }

  return intermediateStates;
}

/**
 * Creates an uncached hash-mode Rescue permutation function.
 *
 * @remarks
 * Closes over the 12x12 MDS matrix and the hash round constants, both of which
 * are themselves cached as module singletons. The returned function accepts and
 * returns flat `bigint[]` arrays of length `HASH_STATE_SIZE = 12`.
 *
 * Internally, the flat array is converted to/from a column vector (12x1 matrix)
 * so that `computeRescuePermutationWithIntermediateStates` can use standard
 * matrix arithmetic. Only the last (final) intermediate state is extracted and
 * returned.
 *
 * @param fieldArithmetic - Field arithmetic for the MDS matrix and round constants
 * @returns A `RescuePermuteFunction` that maps a 12-element state to a 12-element
 *   permuted state
 *
 * @example
 * ```typescript
 * const F = getFieldArithmetic();
 * const permute = createHashPermutationFunction(F);
 * const zeros = Array(12).fill(0n);
 * const out = permute(zeros); // 12-element permuted state
 * ```
 *
 * @see `getHashPermutationFunction` — the cached accessor for this function
 *
 * @internal
 */
function createHashPermutationFunction(fieldArithmetic: FieldArithmetic): RescuePermuteFunction {
  const mdsMatrix = buildHashMdsMatrix();
  const roundConstants = sampleHashRoundConstantVectors(fieldArithmetic);

  return (state: bigint[]): bigint[] => {
    const stateVector = toColumnVector(state);
    const allStates = computeRescuePermutationWithIntermediateStates(
      fieldArithmetic,
      mdsMatrix,
      roundConstants,
      stateVector,
      false,
    );
    return fromColumnVector(getElement(allStates, allStates.length - 1));
  };
}

/**
 * Module-level singleton cache for the hash permutation function.
 *
 * @remarks
 * Lazily populated by `getHashPermutationFunction()`. Cached to avoid
 * redundant allocation on every sponge hash call.
 *
 * @internal
 */
let cachedHashPermutationFunction: RescuePermuteFunction | null = null;

/**
 * Returns the cached hash-mode Rescue permutation function, creating it on
 * first call.
 *
 * @remarks
 * Delegates to `createHashPermutationFunction` the first time it is called
 * with the given `fieldArithmetic`. If `fieldArithmetic` is the default
 * adapter, the result is stored in `cachedHashPermutationFunction`.
 *
 * @param fieldArithmetic - Field arithmetic for the permutation internals
 * @returns The cached (or freshly created) `RescuePermuteFunction` for hash mode
 *
 * @example
 * ```typescript
 * const F = getFieldArithmetic();
 * const p1 = getHashPermutationFunction(F);
 * const p2 = getHashPermutationFunction(F);
 * // p1 === p2  (same cached reference)
 * ```
 *
 * @internal
 */
function getHashPermutationFunction(fieldArithmetic: FieldArithmetic): RescuePermuteFunction {
  if (cachedHashPermutationFunction !== null) {
    return cachedHashPermutationFunction;
  }
  cachedHashPermutationFunction = createHashPermutationFunction(fieldArithmetic);
  return cachedHashPermutationFunction;
}

/* =============================================================================
 * RESCUE-PRIME HASH (SPONGE)
 * ============================================================================= */

/**
 * Module-level singleton cache for the Rescue-Prime hash function.
 *
 * @remarks
 * Lazily populated by `getRescuePrimeHashFunction()` on first call without
 * custom deps. Cached to avoid redundant construction of the permutation closure
 * on subsequent calls.
 *
 * @internal
 */
let cachedRescuePrimeHashFunction: RescuePrimeHashFunction | null = null;

/**
 * Creates an uncached Rescue-Prime sponge hash function.
 *
 * @remarks
 * Implements the Rescue-Prime hash as a sponge construction with
 * `rate = HASH_RATE = 7`, `capacity = HASH_CAPACITY = 5`,
 * `state = HASH_STATE_SIZE = 12`, `digest = HASH_DIGEST_LENGTH = 5`.
 *
 * ## Sponge Construction
 *
 * The sponge operates in two phases:
 *
 * ### Absorb Phase
 *
 * 1. Pad the message with the "10*" scheme (append `1n`, then `0n`s until the
 *    length is a multiple of `HASH_RATE = 7`).
 * 2. For each 7-element block in the padded message:
 *    a. Build a 12-element absorption block: `[block[0..6], 0, 0, 0, 0, 0]`.
 *    b. Add the absorption block to the current state element-wise mod p,
 *       using constant-time arithmetic to resist side-channel leakage.
 *    c. Apply the Rescue-XLIX permutation to the updated state.
 *
 * ### Squeeze Phase
 *
 * Extract the first `HASH_DIGEST_LENGTH = 5` elements of the final state as
 * the digest. No additional permutation is applied (single-call squeezing).
 *
 * ## Security
 *
 * The constant-time addition of the absorption block (via `addMatricesConstantTime`)
 * prevents an attacker from inferring the sponge state from the timing of the
 * absorb operations. The permutation itself is not required to be constant-time
 * because the Rescue round functions are purely algebraic with no secret-dependent
 * branching.
 *
 * @param fieldArithmetic - Field arithmetic for the permutation and constant-time helpers
 * @returns A `RescuePrimeHashFunction` that maps `bigint[]` messages to 5-element digests
 *
 * @example
 * ```typescript
 * const F = getFieldArithmetic();
 * const hash = createRescuePrimeHashFunction(F);
 * const digest = hash([1n, 2n, 3n, 4n, 5n, 6n, 7n, 8n]);
 * // digest.length === 5, each element in [0, FIELD_PRIME)
 * ```
 *
 * @see `getRescuePrimeHashFunction` — the public cached accessor
 * @see `getHashPermutationFunction` — the permutation used in the sponge
 *
 * @internal
 */
function createRescuePrimeHashFunction(fieldArithmetic: FieldArithmetic): RescuePrimeHashFunction {
  const permute = getHashPermutationFunction(fieldArithmetic);
  const binarySize = computeBinarySize(fieldArithmetic.ORDER - 1n);

  return (message: bigint[]): bigint[] => {
    // Padding: append 1n, then 0n until length is multiple of rate
    const paddedMessage = [...message, 1n];
    while (paddedMessage.length % HASH_RATE !== 0) {
      paddedMessage.push(0n);
    }

    // Initialize state to zeros
    let state: bigint[] = Array.from<bigint>({ length: HASH_STATE_SIZE }).fill(0n);

    // Absorb phase
    for (let blockIndex = 0; blockIndex < paddedMessage.length / HASH_RATE; blockIndex++) {
      // Build absorption block: rate elements from message + capacity zeros
      const absorptionBlock: bigint[] = [];
      for (let elementIndex = 0; elementIndex < HASH_RATE; elementIndex++) {
        absorptionBlock.push(getElement(paddedMessage, blockIndex * HASH_RATE + elementIndex));
      }
      for (let elementIndex = HASH_RATE; elementIndex < HASH_STATE_SIZE; elementIndex++) {
        absorptionBlock.push(0n);
      }

      // Constant-time addition of block to state
      const stateVector = toColumnVector(state);
      const blockVector = toColumnVector(absorptionBlock);
      const addedVector = addMatricesConstantTime(stateVector, blockVector, binarySize);
      state = permute(fromColumnVector(addedVector));
    }

    // Squeeze: return first HASH_DIGEST_LENGTH elements
    return state.slice(0, HASH_DIGEST_LENGTH);
  };
}

/**
 * Returns a (cached) Rescue-Prime hash function using the sponge construction.
 *
 * @remarks
 * This is the main entry point for Rescue-Prime hashing. When called without
 * arguments (or without a custom `getFieldArithmetic`), it returns and caches a
 * singleton. Custom deps bypass the cache and always create a fresh instance,
 * which is useful for testing with alternative field implementations.
 *
 * ## Caching Behaviour
 *
 * - No deps provided: returns `cachedRescuePrimeHashFunction` (created on first call).
 * - Custom `getFieldArithmetic` provided: always creates a fresh instance (no caching).
 *
 * @param deps - Optional dependency injection; see `RescuePrimeHashDeps`
 * @returns A `RescuePrimeHashFunction` that computes Rescue-Prime hash digests
 *
 * @example
 * ```typescript
 * import { getRescuePrimeHashFunction } from "./index";
 *
 * // Default usage — cached singleton
 * const hash = getRescuePrimeHashFunction();
 * const digest = hash([1n, 2n, 3n]);
 * // digest.length === 5
 *
 * // Custom field for testing
 * const testHash = getRescuePrimeHashFunction({
 *   getFieldArithmetic: () => myTestField,
 * });
 * const testDigest = testHash([0n]);
 * ```
 *
 * @see `createRescuePrimeHashFunction` — the uncached factory this wraps
 * @see `deriveRescueCipherKey` — uses this hash function internally for KDF
 *
 * @public
 */
export function getRescuePrimeHashFunction(deps?: RescuePrimeHashDeps): RescuePrimeHashFunction {
  const { getFieldArithmetic: getCustomFieldArithmetic } = deps ?? {};

  if (getCustomFieldArithmetic === undefined) {
    if (cachedRescuePrimeHashFunction !== null) {
      return cachedRescuePrimeHashFunction;
    }

    const defaultFieldArithmetic = getFieldArithmetic();
    cachedRescuePrimeHashFunction = createRescuePrimeHashFunction(defaultFieldArithmetic);
    return cachedRescuePrimeHashFunction;
  }

  return createRescuePrimeHashFunction(getCustomFieldArithmetic());
}

/* =============================================================================
 * KEY DERIVATION
 * ============================================================================= */

/**
 * Derives a `BLOCK_SIZE`-element Rescue cipher key from a 32-byte shared secret.
 *
 * @remarks
 * Implements a key derivation function (KDF) based on NIST SP 800-56C Rev 2,
 * Section 4, Option 1 ("one-step KDF using an approved hash function"). The
 * KDF input is constructed as:
 * ```
 * KDF_input = [counter=1,  Z=sharedSecret_as_field_element,  FixedInfo=BLOCK_SIZE=5]
 * ```
 * and the output is:
 * ```
 * key = RescuePrimeHash(KDF_input)   (5 field elements)
 * ```
 *
 * ## Shared Secret Encoding
 *
 * The 32-byte shared secret is interpreted as a little-endian bigint and treated
 * as a single field element. Since the Curve25519 field prime `p = 2^255 - 19`
 * is slightly less than `2^255`, a 32-byte secret may represent a value larger
 * than `p`. The `getRescuePrimeHashFunction()` sponge accepts arbitrary bigints
 * as input (it absorbs without reducing), so the secret is passed through
 * unchanged.
 *
 * @param fieldArithmetic - Field arithmetic (passed to `getRescuePrimeHashFunction`)
 * @param sharedSecret - Exactly `SECRET_BYTES = 32` bytes of shared secret material
 *   (e.g., from X25519 Diffie-Hellman)
 * @returns A `bigint[]` of length `BLOCK_SIZE = 5`, suitable for use as a cipher key
 *
 * @throws `Error` if `sharedSecret.length !== SECRET_BYTES`
 *
 * @example
 * ```typescript
 * const F = getFieldArithmetic();
 * const secret = crypto.getRandomValues(new Uint8Array(32));
 * const key = deriveRescueCipherKey(F, secret);
 * // key.length === 5
 * // each element is a valid field element in [0, FIELD_PRIME)
 * ```
 *
 * @see `getRescuePrimeHashFunction` — the hash function used as the KDF core
 * @see {@link SECRET_BYTES} — the required byte length of the shared secret
 *
 * @internal
 */
function deriveRescueCipherKey(
  fieldArithmetic: FieldArithmetic,
  sharedSecret: Uint8Array,
): bigint[] {
  if (sharedSecret.length !== SECRET_BYTES) {
    throw new Error(
      `Shared secret must be exactly ${String(SECRET_BYTES)} bytes, got ${String(sharedSecret.length)}`,
    );
  }

  const hashFunction = getRescuePrimeHashFunction();

  // Convert shared secret to a field element (full 32 bytes for base field)
  const secretAsFieldElement = deserializeLittleEndianBytesToBigint(sharedSecret);

  // KDF input: [counter=1, Z=secret, FixedInfo=blockSize]
  const kdfInput: bigint[] = [1n, secretAsFieldElement, BigInt(BLOCK_SIZE)];

  return hashFunction(kdfInput);
}

/* =============================================================================
 * CTR MODE CIPHER
 * ============================================================================= */

/**
 * Encrypts an array of field elements in CTR (counter) mode using the
 * Rescue-XLIX permutation as the underlying block cipher.
 *
 * @remarks
 * ## Counter Block Construction
 *
 * For each block of `BLOCK_SIZE = 5` plaintext elements (block index `b`), the
 * counter block is:
 * ```
 * counterBlock = [nonce_as_bigint, b, 0, 0, 0]
 * ```
 * This is permuted by the key-scheduled Rescue cipher to produce a keystream
 * block of 5 field elements.
 *
 * ## XOR in GF(p) — Constant-Time Field Addition
 *
 * The "XOR" of CTR mode is replaced by field addition (mod p). The
 * implementation uses constant-time arithmetic (`constantTimeAdd`,
 * `constantTimeLessThan`, `constantTimeSubtract`, `constantTimeSelect`) to
 * ensure that the running time does not depend on the plaintext values.
 *
 * The reduction to `[0, p)` after addition:
 * ```
 * s = plaintext[i] + keystream[i]   (constant-time add, may overflow p)
 * c = s < p ? s : s - p             (constant-time conditional subtract)
 * ```
 *
 * ## Partial Last Block
 *
 * If `plaintext.length` is not a multiple of `BLOCK_SIZE`, the last keystream
 * block is truncated to the number of remaining plaintext elements. Only the
 * needed keystream elements are computed via the inner loop bound
 * `endIndex - startIndex`.
 *
 * @param fieldArithmetic - Field arithmetic for the binary size computation
 * @param permute - The key-scheduled Rescue permutation (closure over round keys)
 * @param plaintext - Array of field elements to encrypt; length may be any positive integer
 * @param nonce - Exactly `NONCE_BYTES = 16` bytes; deserialized as a LE bigint
 * @returns Array of bigint ciphertext field elements (same length as `plaintext`)
 *
 * @throws `Error` if `nonce.length !== NONCE_BYTES`
 *
 * @example
 * ```typescript
 * const F = getFieldArithmetic();
 * const nonce = new Uint8Array(16).fill(0x01);
 * const plain = [1n, 2n, 3n];
 * // (permute is the key-scheduled cipher permutation)
 * const enc = encryptFieldElementsInCtrMode(F, permute, plain, nonce);
 * // enc.length === 3, enc[i] in [0, FIELD_PRIME)
 * ```
 *
 * @see `decryptFieldElementsInCtrMode` — the symmetric decryption function
 *
 * @internal
 */
function encryptFieldElementsInCtrMode(
  fieldArithmetic: FieldArithmetic,
  permute: RescuePermuteFunction,
  plaintext: bigint[],
  nonce: Uint8Array,
): bigint[] {
  if (nonce.length !== NONCE_BYTES) {
    throw new Error(`Nonce must be exactly ${String(NONCE_BYTES)} bytes`);
  }

  const nonceValue = deserializeLittleEndianBytesToBigint(nonce);
  const blockCount = Math.ceil(plaintext.length / BLOCK_SIZE);
  const binarySize = computeBinarySize(fieldArithmetic.ORDER - 1n);
  const ciphertext: bigint[] = [];

  for (let blockIndex = 0; blockIndex < blockCount; blockIndex++) {
    // Build counter block
    const counterBlock: bigint[] = [nonceValue, BigInt(blockIndex), 0n, 0n, 0n];

    // Permute the counter
    const keystream = permute(counterBlock);

    // XOR (field add) plaintext with keystream
    const startIndex = blockIndex * BLOCK_SIZE;
    const endIndex = Math.min(startIndex + BLOCK_SIZE, plaintext.length);
    for (let elementIndex = 0; elementIndex < endIndex - startIndex; elementIndex++) {
      const sum = constantTimeAdd(
        getElement(plaintext, startIndex + elementIndex),
        getElement(keystream, elementIndex),
        binarySize,
      );
      const reduced = constantTimeSelect(
        constantTimeLessThan(sum, fieldArithmetic.ORDER, binarySize),
        sum,
        constantTimeSubtract(sum, fieldArithmetic.ORDER, binarySize),
        binarySize,
      );
      ciphertext.push(reduced);
    }
  }

  return ciphertext;
}

/**
 * Decrypts an array of field elements in CTR (counter) mode using the
 * Rescue-XLIX permutation.
 *
 * @remarks
 * CTR mode decryption is structurally identical to encryption: the same
 * keystream is generated from the nonce and block index, and each ciphertext
 * element is combined with the keystream by field subtraction (mod p), which
 * is the inverse of the field addition used during encryption.
 *
 * The constant-time subtraction handles the underflow case:
 * ```
 * d = ciphertext[i] - keystream[i]   (constant-time subtract, may be negative)
 * p = d < 0 ? d + FIELD_PRIME : d    (constant-time conditional add of p)
 * ```
 *
 * The sign bit of the 2's complement result is used by `constantTimeSignBit`
 * to detect the underflow without branching on the data value.
 *
 * @param fieldArithmetic - Field arithmetic for the binary size computation
 * @param permute - The key-scheduled Rescue permutation (same closure as used for encryption)
 * @param ciphertext - Array of bigint ciphertext field elements to decrypt
 * @param nonce - The same `NONCE_BYTES = 16`-byte nonce used during encryption
 * @returns Array of bigint plaintext field elements (same length as `ciphertext`)
 *
 * @throws `Error` if `nonce.length !== NONCE_BYTES`
 *
 * @example
 * ```typescript
 * const F = getFieldArithmetic();
 * const nonce = new Uint8Array(16).fill(0x01);
 * const enc = [someEncryptedValue];
 * const dec = decryptFieldElementsInCtrMode(F, permute, enc, nonce);
 * // dec contains the original plaintext field elements
 * ```
 *
 * @see `encryptFieldElementsInCtrMode` — the symmetric encryption function
 *
 * @internal
 */
function decryptFieldElementsInCtrMode(
  fieldArithmetic: FieldArithmetic,
  permute: RescuePermuteFunction,
  ciphertext: bigint[],
  nonce: Uint8Array,
): bigint[] {
  if (nonce.length !== NONCE_BYTES) {
    throw new Error(`Nonce must be exactly ${String(NONCE_BYTES)} bytes`);
  }

  const nonceValue = deserializeLittleEndianBytesToBigint(nonce);
  const blockCount = Math.ceil(ciphertext.length / BLOCK_SIZE);
  const binarySize = computeBinarySize(fieldArithmetic.ORDER - 1n);
  const plaintext: bigint[] = [];

  for (let blockIndex = 0; blockIndex < blockCount; blockIndex++) {
    const counterBlock: bigint[] = [nonceValue, BigInt(blockIndex), 0n, 0n, 0n];
    const keystream = permute(counterBlock);

    const startIndex = blockIndex * BLOCK_SIZE;
    const endIndex = Math.min(startIndex + BLOCK_SIZE, ciphertext.length);
    for (let elementIndex = 0; elementIndex < endIndex - startIndex; elementIndex++) {
      const difference = constantTimeSubtract(
        getElement(ciphertext, startIndex + elementIndex),
        getElement(keystream, elementIndex),
        binarySize,
      );
      const reduced = constantTimeSelect(
        constantTimeSignBit(difference, binarySize),
        constantTimeAdd(difference, fieldArithmetic.ORDER, binarySize),
        difference,
        binarySize,
      );
      plaintext.push(reduced);
    }
  }

  return plaintext;
}

/* =============================================================================
 * PUBLIC API
 * ============================================================================= */

/**
 * Creates an uncached `RescueCipherInstance` from a shared secret.
 *
 * @remarks
 * Performs the full cipher initialisation sequence:
 *
 * 1. **Key derivation**: calls `deriveKey(fieldArithmetic, sharedSecret)` to
 *    produce a `BLOCK_SIZE = 5` element key from the raw shared secret.
 *
 * 2. **Key schedule**: runs the Rescue-XLIX permutation on the derived key
 *    in cipher mode (`cipherMode = true`), capturing all 21 intermediate states.
 *    These intermediate states become the round keys for subsequent CTR-mode
 *    encryptions and decryptions. This is the Rescue-XLIX key expansion.
 *
 * 3. **Cipher permutation closure**: wraps a `RescuePermuteFunction` that
 *    closes over the 21 round keys and applies them to any input state.
 *
 * 4. **Encrypt/decrypt methods**: builds the `RescueCipherInstance` methods
 *    that call `encryptFieldElementsInCtrMode` / `decryptFieldElementsInCtrMode`
 *    and handle byte serialisation/deserialisation of field elements.
 *
 * ## Key Schedule Details
 *
 * The Rescue-XLIX cipher's key schedule is non-standard: instead of expanding
 * the key using a separate schedule, it runs the cipher permutation on the key
 * itself and uses each intermediate state as an additive round constant. This
 * is structurally similar to the AES key schedule but built entirely in GF(p).
 *
 * ## Byte Serialisation
 *
 * The `encrypt` method serialises each output field element to a 32-byte
 * little-endian `number[]`. The `decrypt` method deserialises each input
 * element back to a `bigint` before processing.
 *
 * @param sharedSecret - Raw 32-byte shared secret (must be `SECRET_BYTES` bytes)
 * @param fieldArithmetic - Field arithmetic for all operations
 * @param deriveKey - Key derivation function; receives `fieldArithmetic` and `sharedSecret`
 * @returns A fresh `RescueCipherInstance` with `encrypt` and `decrypt` methods
 *
 * @example
 * ```typescript
 * const F = getFieldArithmetic();
 * const secret = crypto.getRandomValues(new Uint8Array(32));
 * const cipher = createRescueCipherInstance(secret, F, deriveRescueCipherKey);
 * const nonce = crypto.getRandomValues(new Uint8Array(16));
 * const enc = cipher.encrypt([1n, 2n, 3n], nonce);
 * const dec = cipher.decrypt(enc, nonce);
 * // dec deepEquals [1n, 2n, 3n]
 * ```
 *
 * @see `getRescueCipherInstance` — the public factory that wraps this function
 * @see `encryptFieldElementsInCtrMode` — the CTR encryption called by `encrypt`
 * @see `decryptFieldElementsInCtrMode` — the CTR decryption called by `decrypt`
 *
 * @internal
 */
function createRescueCipherInstance(
  sharedSecret: Uint8Array,
  fieldArithmetic: FieldArithmetic,
  deriveKey: (fieldArithmetic: FieldArithmetic, sharedSecret: Uint8Array) => bigint[],
): RescueCipherInstance {
  const cipherKey = deriveKey(fieldArithmetic, sharedSecret);

  // Build cipher-mode key schedule
  const mdsMatrix = buildCipherMdsMatrix();
  const roundConstants = sampleCipherRoundConstantVectors(fieldArithmetic);

  // Key schedule: run the Rescue permutation on the cipher key using round constants
  const keyVector = toColumnVector(cipherKey);
  const allStates = computeRescuePermutationWithIntermediateStates(
    fieldArithmetic,
    mdsMatrix,
    roundConstants,
    keyVector,
    true,
  );

  // The intermediate states become the round keys for encryption
  const roundKeys = allStates;

  // Create cipher-mode permutation function using the derived round keys
  const permuteCipher: RescuePermuteFunction = (state: bigint[]): bigint[] => {
    const stateVector = toColumnVector(state);
    const states = computeRescuePermutationWithIntermediateStates(
      fieldArithmetic,
      mdsMatrix,
      roundKeys,
      stateVector,
      true,
    );
    return fromColumnVector(getElement(states, states.length - 1));
  };

  return {
    encrypt(plaintext: bigint[], nonce: Uint8Array): number[][] {
      const rawCiphertext = encryptFieldElementsInCtrMode(
        fieldArithmetic,
        permuteCipher,
        plaintext,
        nonce,
      );
      return rawCiphertext.map((element) => [
        ...serializeBigintToLittleEndianBytes(element, FIELD_ELEMENT_BYTE_LENGTH),
      ]);
    },

    decrypt(ciphertext: number[][], nonce: Uint8Array): bigint[] {
      const rawCiphertext = ciphertext.map((element) => {
        if (element.length !== FIELD_ELEMENT_BYTE_LENGTH) {
          throw new Error(
            `Each ciphertext element must be ${String(FIELD_ELEMENT_BYTE_LENGTH)} bytes, got ${String(element.length)}`,
          );
        }
        return deserializeLittleEndianBytesToBigint(Uint8Array.from(element));
      });
      return decryptFieldElementsInCtrMode(fieldArithmetic, permuteCipher, rawCiphertext, nonce);
    },
  };
}

/**
 * Returns a Rescue-XLIX cipher instance initialised from a shared secret.
 *
 * @remarks
 * This is the primary public entry point of the `rescue-cipher` module. It:
 *
 * 1. Resolves field arithmetic from `deps.getFieldArithmetic` or the default
 *    SDK adapter (`getFieldArithmetic()`).
 * 2. Resolves the KDF from `deps.deriveKey` or the default NIST SP 800-56C
 *    implementation (`deriveRescueCipherKey`).
 * 3. Delegates to `createRescueCipherInstance` with the resolved dependencies.
 *
 * The returned `RescueCipherInstance` is compatible with the `RescueCipher`
 * class from `@arcium-hq/client`, providing the same `encrypt` and `decrypt`
 * method signatures.
 *
 * ## Security
 *
 * Cipher instances are intentionally NOT cached. Each call to this function
 * creates a fresh instance, which limits the lifetime of the derived key
 * material in memory and reduces the risk of key leakage across multiple
 * independent encryption operations.
 *
 * ## Dependency Injection
 *
 * Custom `deps` bypass the module-level caches. This is useful for:
 * - Unit testing with a fixed/known key derivation function
 * - Benchmarking alternative field arithmetic implementations
 * - Future support for hardware-accelerated field operations
 *
 * @param sharedSecret - A `Uint8Array` of exactly `SECRET_BYTES = 32` bytes
 *   representing a shared secret (typically from X25519 ECDH)
 * @param deps - Optional dependencies; see `RescueCipherDeps`
 * @returns A `RescueCipherInstance` with `encrypt()` and `decrypt()` methods
 *
 * @throws `Error` (via `deriveRescueCipherKey`) if `sharedSecret.length !== 32`
 *
 * @example
 * ```typescript
 * import { getRescueCipherInstance } from "@umbra/sdk/crypto/rescue-cipher";
 *
 * // Typical usage — X25519 shared secret from key exchange
 * const sharedSecret = performX25519KeyExchange(myPrivateKey, theirPublicKey);
 * const nonce = crypto.getRandomValues(new Uint8Array(16));
 * const cipher = getRescueCipherInstance(sharedSecret);
 *
 * // Encrypt a vector of field elements (e.g., confidential token amounts)
 * const plaintext: bigint[] = [1_000_000n, 500_000n];
 * const ciphertext = cipher.encrypt(plaintext, nonce);
 * // ciphertext: number[][], each inner array is 32 bytes
 *
 * // Decrypt on the other side
 * const sameSecret = performX25519KeyExchange(theirPrivateKey, myPublicKey);
 * const cipher2 = getRescueCipherInstance(sameSecret);
 * const recovered = cipher2.decrypt(ciphertext, nonce);
 * // recovered deepEquals plaintext
 *
 * // Testing with injected deps
 * const testCipher = getRescueCipherInstance(sharedSecret, {
 *   deriveKey: (_secret) => [1n, 2n, 3n, 4n, 5n],
 * });
 * ```
 *
 * @see `createRescueCipherInstance` — the internal factory this delegates to
 * @see {@link RescueCipherInstance} — the returned interface
 * @see {@link RescueCipherDeps} — the optional dependency injection interface
 * @see {@link SECRET_BYTES} — the required shared secret byte length (32)
 * @see {@link NONCE_BYTES} — the required nonce byte length for encrypt/decrypt (16)
 *
 * @public
 */
export function getRescueCipherInstance(
  sharedSecret: Uint8Array,
  deps?: RescueCipherDeps,
): RescueCipherInstance {
  const { getFieldArithmetic: getCustomFieldArithmetic, deriveKey } = deps ?? {};

  const resolvedFieldArithmetic =
    getCustomFieldArithmetic === undefined ? getFieldArithmetic() : getCustomFieldArithmetic();

  const resolvedDeriveKey =
    deriveKey === undefined
      ? deriveRescueCipherKey
      : (_fieldArithmetic: FieldArithmetic, secret: Uint8Array) => deriveKey(secret);

  return createRescueCipherInstance(sharedSecret, resolvedFieldArithmetic, resolvedDeriveKey);
}
