/* =============================================================================
 * CONSTANTS
 * ============================================================================= */

/**
 * Minimum number of inputs supported by the Poseidon hash function.
 * @internal
 */
const MIN_INPUTS = 1;

/**
 * Maximum number of inputs supported by the Poseidon hash function.
 *
 * This limit is determined by the Circom Poseidon specification, which defines
 * constants for state sizes t=2 to t=13 (corresponding to 1 to 12 inputs).
 *
 * @remarks
 * The Poseidon permutation uses a state of size `t = inputs.length + 1` where the
 * extra element serves as the capacity element (initialized to 0). With t ranging
 * from 2 to 13, the maximum number of data inputs is 12.
 *
 * For hashing more than 12 elements, use the aggregator which chains two rounds
 * of Poseidon and supports up to {@link MAX_AGGREGATOR_INPUTS} (144) total elements.
 *
 * @example
 * ```typescript
 * import { getPoseidonHasher, MAX_POSEIDON_INPUTS } from '@umbra/sdk';
 *
 * const hasher = getPoseidonHasher();
 *
 * // Hash exactly at the limit
 * const inputs = Array.from({ length: MAX_POSEIDON_INPUTS }, (_, i) => BigInt(i));
 * inputs.forEach(assertBn254FieldElement);
 * const hash = await hasher(inputs);
 * ```
 *
 * @see {@link getPoseidonHasher} for the direct hash function (1–12 inputs)
 * @see {@link getPoseidonAggregator} for hashing more than 12 inputs
 * @see {@link MAX_AGGREGATOR_INPUTS} for the aggregator's limit (144 inputs)
 * @public
 */
export const MAX_POSEIDON_INPUTS = 12;

/**
 * Maximum number of seeds supported by the Poseidon PRF.
 *
 * Since the PRF combines seeds with an evaluation point as the last input,
 * and Poseidon supports at most 12 total inputs, the maximum number of
 * seeds is 11.
 *
 * @remarks
 * The PRF computes `Poseidon(seed_0, ..., seed_n, evaluationPoint)` where the
 * evaluation point occupies the last slot. With {@link MAX_POSEIDON_INPUTS} = 12,
 * at most 11 seeds can be used (11 seeds + 1 evaluation point = 12 total inputs).
 *
 * @example
 * ```typescript
 * import { getPoseidonPrf, MAX_PRF_SEEDS } from '@umbra/sdk';
 *
 * const prf = getPoseidonPrf();
 *
 * // Use up to MAX_PRF_SEEDS seeds
 * const seeds = Array.from({ length: MAX_PRF_SEEDS }, (_, i) => BigInt(i + 1));
 * seeds.forEach(assertBn254FieldElement);
 * const output = await prf(seeds, 0n as Bn254FieldElement);
 * ```
 *
 * @see {@link getPoseidonPrf} for the PRF function factory
 * @see {@link MAX_POSEIDON_INPUTS} for the underlying hash input limit
 * @public
 */
export const MAX_PRF_SEEDS = 11;

/* =============================================================================
 * MODULE-LEVEL CACHES
 * ============================================================================= */

/**
 * Cached instance of the Poseidon hasher function.
 *
 * This cache ensures that `getPoseidonHasher()` always returns the same
 * function instance, avoiding unnecessary allocations.
 *
 * @internal
 */
let cachedHasher: PoseidonHashFunction | null = null;

/**
 * Cached instances of Poseidon PRF functions, keyed by hasher reference.
 *
 * Uses a WeakMap to allow garbage collection of PRF functions when their
 * associated hasher is no longer referenced.
 *
 * @internal
 */
const prfCache = new WeakMap<PoseidonHashFunction, PoseidonPrfFunction>();

/**
 * Cached instance of the default Poseidon PRF function.
 *
 * This cache stores the PRF created with the default hasher for quick access.
 *
 * @internal
 */
let cachedDefaultPrf: PoseidonPrfFunction | null = null;

/**
 * Cached instances of Poseidon keystream generator functions, keyed by PRF reference.
 *
 * Uses a WeakMap to allow garbage collection of keystream generators when their
 * associated PRF is no longer referenced.
 *
 * @internal
 */
const keystreamGeneratorCache = new WeakMap<
  PoseidonPrfFunction,
  PoseidonKeystreamGeneratorFunction
>();

/**
 * Cached instance of the default Poseidon keystream generator function.
 *
 * This cache stores the keystream generator created with the default PRF for quick access.
 *
 * @internal
 */
let cachedDefaultKeystreamGenerator: PoseidonKeystreamGeneratorFunction | null = null;

/**
 * Evaluation point for keystream generation via the Poseidon PRF.
 *
 * This constant is the fixed `x` value passed as the last argument to the PRF
 * when generating keystream values:
 * ```
 * keystream[counter] = PRF([key, counter], KEYSTREAM_EVALUATION_POINT)
 *                    = Poseidon([key, counter, 2])
 * ```
 *
 * @remarks
 * Using a fixed, non-zero evaluation point distinct from other PRF usages (such as
 * viewing key derivation at point 1, or nullifier generation at the commitment value)
 * provides domain separation. This ensures that keystream outputs cannot be confused
 * with outputs of the same PRF key evaluated at different points, even if an adversary
 * knows some keystream values.
 *
 * The value `2n` is chosen to be simple and memorable while being distinct from `0n`
 * (which is often reserved as a "default" or "no domain" separator) and `1n` (commonly
 * used for the first alternative domain).
 *
 * @internal
 */
const KEYSTREAM_EVALUATION_POINT = 2n;

/* =============================================================================
 * INTERNAL FUNCTIONS
 * ============================================================================= */

/**
 * Retrieves Circom-compatible Poseidon parameters for a given state size.
 *
 * This function looks up the pre-computed constants (MDS matrix and round constants)
 * required for the Poseidon permutation with the specified state size.
 *
 * @param t - The state size (number of field elements in the permutation state).
 *            Must be between 2 and 13 inclusive, corresponding to 1-12 inputs.
 * @returns An object containing:
 *          - `roundsPartial`: Number of partial rounds for this state size
 *          - `mds`: The MDS (Maximum Distance Separable) matrix for mixing
 *          - `roundConstants`: The round constants organized by round
 *
 * @throws {Error} If `t` is outside the valid range [2, 13]
 * @throws {Error} If constants are missing for the specified state size
 *
 * @remarks
 * The state size `t` equals `inputs.length + 1` because Poseidon uses an
 * initial state element (set to 0) followed by the input values.
 *
 * ## Circom Compatibility
 *
 * These constants are sourced from circomlibjs v0.1.7 to ensure bit-exact
 * compatibility with Circom's Poseidon implementation.
 *
 * @internal
 */
function getCircomParameters(t: number): {
  roundsPartial: number;
  mds: bigint[][];
  roundConstants: bigint[][];
} {
  // Validate state size is within supported range
  if (!Number.isInteger(t)) {
    throw new TypeError(`Invalid state size t=${String(t)}. Must be an integer.`);
  }

  if (t < 2 || t > 13) {
    throw new Error(
      `Invalid state size t=${String(t)}. Must be between 2 and 13 (inclusive), ` +
        `corresponding to ${String(MIN_INPUTS)} to ${String(MAX_POSEIDON_INPUTS)} inputs.`,
    );
  }

  const index = t - 2;
  const roundsPartial = ROUNDS_PARTIAL[index];

   
  if (roundsPartial === undefined) {
    throw new Error(
      `Missing roundsPartial constant for state size t=${String(t)}. ` +
        `This indicates corrupted or incomplete constant data.`,
    );
  }

  const mds = POSEIDON_M[index];
  const roundConstantsFlattened = POSEIDON_C[index];

   
  if (mds === undefined || roundConstantsFlattened === undefined) {
    throw new Error(
      `Missing MDS matrix or round constants for state size t=${String(t)}. ` +
        `This indicates corrupted or incomplete constant data.`,
    );
  }

  const roundConstants = splitConstants(roundConstantsFlattened, t);

  return { roundsPartial, mds, roundConstants };
}

/* =============================================================================
 * INTERNAL HASH FUNCTION
 * ============================================================================= */

/**
 * Synchronous internal implementation of the Poseidon hash function.
 *
 * This function performs the actual Poseidon permutation computation using the
 * `@noble/curves` library with Circom-compatible constants. It is the core
 * computation shared by all public-facing hasher functions.
 *
 * @param inputs - A read-only array of 1 to {@link MAX_POSEIDON_INPUTS} (12) BN254 field elements to hash.
 * @returns The first element of the Poseidon permutation output state, typed as `Bn254FieldElement`.
 *
 * @throws {Error} If `inputs` is empty (length 0).
 * @throws {Error} If `inputs.length` exceeds `MAX_POSEIDON_INPUTS` (12).
 * @throws {TypeError} If any input element fails BN254 field validation at the given index.
 * @throws {TypeError} If the `@noble/curves` library returns a non-bigint result (internal error).
 *
 * @remarks
 * ## Permutation Construction
 *
 * For `n` inputs, the state size is `t = n + 1`. The initial state is
 * `[0n, inputs[0], inputs[1], ..., inputs[n-1]]`. After applying the Poseidon
 * permutation, the output hash is `state[0]`.
 *
 * ## Circom Compatibility
 *
 * Constants (`POSEIDON_M` MDS matrices and `POSEIDON_C` round constants) are
 * sourced from circomlibjs v0.1.7 to ensure bit-exact agreement with Circom's
 * `Poseidon` template at any arity from 1 to 12.
 *
 * @privateRemarks
 * This function is synchronous. The async wrapper in `getPoseidonHasher()` exists
 * to satisfy the `PoseidonHashFunction` interface contract and maintain consistency
 * with other async crypto APIs in the SDK.
 *
 * @internal
 */
function poseidonHashInternal(inputs: readonly Bn254FieldElement[]): Bn254FieldElement {
  // Validate input array length
  if (inputs.length === 0) {
    throw new Error(`Poseidon hash requires at least ${String(MIN_INPUTS)} input.`);
  }

  if (inputs.length > MAX_POSEIDON_INPUTS) {
    throw new Error(
      `Poseidon hash supports at most ${String(MAX_POSEIDON_INPUTS)} inputs, ` +
        `got ${String(inputs.length)}.`,
    );
  }

  // Validate each input element is a valid BN254 field element
  for (const [index, inputElement] of inputs.entries()) {
    const input = inputElement;
    try {
      assertBn254FieldElement(input);
    } catch (error) {
      if (error instanceof Error) {
        throw new TypeError(`Invalid input at index ${String(index)}: ${error.message}`);
      }
      throw error;
    }
  }

  // Compute the state size (inputs + initial state element)
  const t = inputs.length + 1;
  const initState = 0n;

  // Retrieve Circom-compatible parameters for this state size
  const { roundsPartial, mds, roundConstants } = getCircomParameters(t);

  // Create the Poseidon permutation function with the appropriate parameters
  const poseidonNoble = createPoseidon({
    Fp: Fr,
    t,
    roundsFull: ROUNDS_FULL,
    roundsPartial,
    sboxPower: SBOX_POWER,
    mds,
    roundConstants,
  });

  // Execute the Poseidon permutation
  // Note: We cast inputs to bigint[] because the noble library expects plain bigints,
  // but our branded Bn254FieldElement type is structurally compatible.
  const nobleState = poseidonNoble([initState, ...(inputs as readonly bigint[])]);
  const nobleHash = nobleState[0];

  // Validate the hash result type
  if (typeof nobleHash !== "bigint") {
    throw new TypeError(
      `Unexpected hash result type: expected bigint, got ${typeof nobleHash}. ` +
        `This indicates an internal error in the noble-curves library.`,
    );
  }

  // Validate the output is a valid BN254 field element
  assertBn254FieldElement(nobleHash);
  return nobleHash;
}

/* =============================================================================
 * PUBLIC API
 * ============================================================================= */

/**
 * Returns a cached Poseidon hash function.
 *
 * This function returns a `PoseidonHashFunction` that computes Poseidon hashes
 * compatible with Circom's implementation. The function instance is cached,
 * so repeated calls return the same function.
 *
 * @returns A `PoseidonHashFunction` that hashes arrays of BN254 field elements
 *
 * @remarks
 * ## Caching
 *
 * The returned function is a cached singleton. Calling `getPoseidonHasher()`
 * multiple times returns the exact same function instance.
 *
 * ## Hash Computation
 *
 * The returned hasher:
 * - Accepts 1 to 12 BN254 field elements
 * - Uses an initial state of `0n` followed by the inputs
 * - Returns a single `Bn254FieldElement` hash output
 * - Produces outputs identical to Circom's Poseidon implementation
 *
 * ## Input Validation
 *
 * Each input element is validated using `assertBn254FieldElement` to ensure:
 * - The value is a `bigint`
 * - The value is non-negative
 * - The value is less than the BN254 field prime
 *
 * @example
 * ```typescript
 * import { getPoseidonHasher } from '@umbra/sdk';
 * import { assertBn254FieldElement } from '@umbra/sdk/types';
 *
 * // Get the hasher (cached singleton)
 * const hasher = getPoseidonHasher();
 *
 * // Hash a single value
 * const input = 123n;
 * assertBn254FieldElement(input);
 * const hash1 = await hasher([input]);
 *
 * // Hash multiple values
 * const inputs: Bn254FieldElement[] = [1n, 2n, 3n];
 * inputs.forEach(assertBn254FieldElement);
 * const hash2 = await hasher(inputs);
 *
 * // Use in Merkle tree construction
 * const left = 100n;
 * const right = 200n;
 * assertBn254FieldElement(left);
 * assertBn254FieldElement(right);
 * const merkleNode = await hasher([left, right]);
 * ```
 *
 * @public
 */
export function getPoseidonHasher(): PoseidonHashFunction {
  if (cachedHasher !== null) {
    return cachedHasher;
  }

  const hasher: PoseidonHashFunction = async (
    dataPoints: readonly Bn254FieldElement[],
  ): Promise<Bn254FieldElement> => {
    return poseidonHashInternal(dataPoints);
  };

  cachedHasher = hasher;
  return hasher;
}

/**
 * Optional dependencies for the Poseidon PRF factory.
 *
 * @remarks
 * This interface enables dependency injection for the Poseidon PRF. By providing
 * a custom hasher, callers can substitute test doubles or alternative hash
 * implementations without changing the PRF logic itself.
 *
 * When no dependencies are supplied, `getPoseidonPrf()` uses the cached default
 * hasher returned by `getPoseidonHasher()`.
 *
 * @example
 * ```typescript
 * import { getPoseidonPrf } from '@umbra/sdk';
 *
 * // Use a mock hasher in tests
 * const mockHasher: PoseidonHashFunction = async (inputs) => 42n as Bn254FieldElement;
 * const prf = getPoseidonPrf({ hasher: mockHasher });
 * ```
 *
 * @see {@link getPoseidonPrf}
 * @public
 */
export interface PoseidonPrfDeps {
  /**
   * Optional custom hasher function.
   *
   * @remarks
   * When provided, the PRF uses this hasher instead of the default
   * `getPoseidonHasher()` singleton. The result is cached per hasher
   * reference using a `WeakMap`.
   *
   * If not provided, the PRF is cached as a module-level singleton.
   *
   * @defaultValue The return value of `getPoseidonHasher()`
   */
  readonly hasher?: PoseidonHashFunction;
}

/**
 * Returns a cached Poseidon PRF (Pseudo-Random Function).
 *
 * This function returns a `PoseidonPrfFunction` that computes pseudo-random outputs
 * from secret seeds and an evaluation point. The PRF is built on top of the
 * Poseidon hash function.
 *
 * @param deps - Optional dependencies including custom hasher function.
 * @returns A `PoseidonPrfFunction` that computes PRF outputs
 *
 * @remarks
 * ## Caching
 *
 * - When called without arguments (using default hasher), returns a cached singleton
 * - When called with a custom hasher, returns a cached function per hasher instance
 * - The cache uses WeakMap for custom hashers to allow garbage collection
 *
 * ## PRF Computation
 *
 * The PRF combines seeds with the evaluation point:
 * ```
 * PRF(seeds, x) = Poseidon(seed_0, seed_1, ..., seed_n, x)
 * ```
 *
 * ## Input Constraints
 *
 * - Seeds: 1 to 11 elements (to leave room for the evaluation point)
 * - Total inputs (seeds.length + 1) must not exceed 12
 *
 * ## Security Properties
 *
 * - **Deterministic**: Same (seeds, evaluationPoint) always produces the same output
 * - **Pseudo-random**: Output is computationally indistinguishable from random if seeds are secret
 * - **Key-dependent**: Different seeds produce completely different outputs
 *
 * ## Use Cases
 *
 * - Key derivation from master secrets
 * - Nullifier generation in ZK protocols
 * - Commitment schemes
 * - Verifiable random functions
 *
 * @example
 * ```typescript
 * import { getPoseidonPrf } from '@umbra/sdk';
 * import { assertBn254FieldElement } from '@umbra/sdk/types';
 *
 * // Get the PRF (cached singleton)
 * const prf = getPoseidonPrf();
 *
 * // Use with a single seed
 * const seed = secretKey;
 * assertBn254FieldElement(seed);
 * const output = await prf([seed], evaluationPoint);
 *
 * // Use with multiple seeds (up to 11)
 * const seeds: Bn254FieldElement[] = [seed1, seed2, seed3];
 * seeds.forEach(assertBn254FieldElement);
 * const output2 = await prf(seeds, evaluationPoint);
 * ```
 *
 * @example
 * ```typescript
 * // Nullifier generation
 * const prf = getPoseidonPrf();
 *
 * const secretKey: Bn254FieldElement = userPrivateKey;
 * const commitment: Bn254FieldElement = noteCommitment;
 *
 * // Generate nullifier: PRF(sk, commitment)
 * const nullifier = await prf([secretKey], commitment);
 * ```
 *
 * @example
 * ```typescript
 * // Using a custom hasher
 * const customHasher: PoseidonHashFunction = myCustomHasher;
 * const prf = getPoseidonPrf(customHasher);
 *
 * const output = await prf([seed], evaluationPoint);
 * ```
 *
 * @public
 */
export function getPoseidonPrf(deps?: PoseidonPrfDeps): PoseidonPrfFunction {
  const { hasher } = deps ?? {};

  // If no hasher provided, use the default cached hasher
  if (hasher === undefined) {
    if (cachedDefaultPrf !== null) {
      return cachedDefaultPrf;
    }

    const defaultHasher = getPoseidonHasher();
    const prf = createPrfFunction(defaultHasher);
    cachedDefaultPrf = prf;
    return prf;
  }

  // Check if we have a cached PRF for this hasher
  const cachedPrf = prfCache.get(hasher);
  if (cachedPrf !== undefined) {
    return cachedPrf;
  }

  // Create and cache a new PRF for this hasher
  const prf = createPrfFunction(hasher);
  prfCache.set(hasher, prf);
  return prf;
}

/**
 * Creates a PRF function using the provided hasher.
 *
 * This internal factory function constructs a `PoseidonPrfFunction` that uses the
 * specified hasher for computing pseudo-random outputs. The returned function
 * performs full input validation on seeds and the evaluation point before
 * invoking the hasher.
 *
 * @param hasher - The `PoseidonHashFunction` to use for computing the PRF output.
 *                 This allows for dependency injection of custom hashers.
 * @returns A `PoseidonPrfFunction` implementation that validates inputs and delegates
 *          to the provided hasher.
 *
 * @throws {Error} If the returned PRF function is called with:
 *         - An empty seeds array
 *         - More than 11 seeds (since total inputs must not exceed 12)
 *         - Invalid BN254 field elements in seeds or evaluation point
 *
 * @remarks
 * ## PRF Construction
 *
 * The PRF is constructed by concatenating seeds with the evaluation point
 * and passing them to the Poseidon hash function:
 * ```
 * PRF(seeds, x) = Poseidon(seed_0, seed_1, ..., seed_n, x)
 * ```
 *
 * ## Input Validation
 *
 * The returned function performs the following validations:
 * 1. Seeds array must have 1 to 11 elements
 * 2. Each seed must be a valid BN254 field element
 * 3. The evaluation point must be a valid BN254 field element
 * 4. The output is validated to be a valid BN254 field element
 *
 * ## Why This Factory Pattern
 *
 * This factory function enables:
 * - Separation of PRF logic from hasher implementation
 * - Dependency injection for testing with mock hashers
 * - Caching of PRF functions per hasher instance in `getPoseidonPrf()`
 *
 * @internal
 */
function createPrfFunction(hasher: PoseidonHashFunction): PoseidonPrfFunction {
  return async (
    seeds: readonly Bn254FieldElement[],
    evaluationPoint: Bn254FieldElement,
  ): Promise<Bn254FieldElement> => {
    // Validate seeds array length
    if (seeds.length === 0) {
      throw new Error(`Poseidon PRF requires at least ${String(MIN_INPUTS)} seed.`);
    }

    if (seeds.length > MAX_PRF_SEEDS) {
      throw new Error(
        `Poseidon PRF supports at most ${String(MAX_PRF_SEEDS)} seeds, ` +
          `got ${String(seeds.length)}. Total inputs (seeds + evaluation point) ` +
          `must not exceed ${String(MAX_POSEIDON_INPUTS)}.`,
      );
    }

    // Validate each seed is a valid BN254 field element
    for (const [index, seedElement] of seeds.entries()) {
      const seed = seedElement;
      try {
        assertBn254FieldElement(seed);
      } catch (error) {
        if (error instanceof Error) {
          throw new TypeError(`Invalid seed at index ${String(index)}: ${error.message}`);
        }
        throw error;
      }
    }

    // Validate evaluation point
    try {
      assertBn254FieldElement(evaluationPoint);
    } catch (error) {
      if (error instanceof Error) {
        throw new TypeError(`Invalid evaluation point: ${error.message}`);
      }
      throw error;
    }

    // Combine seeds with evaluation point and hash
    // PRF(seeds, x) = Poseidon(seed_0, seed_1, ..., seed_n, x)
    const inputs: Bn254FieldElement[] = [...seeds, evaluationPoint];
    const result = await hasher(inputs);

    // Validate output
    assertBn254FieldElement(result);
    return result;
  };
}

/**
 * Optional dependencies for the Poseidon keystream generator factory.
 *
 * @remarks
 * This interface enables dependency injection for the keystream generator.
 * By providing a custom PRF, callers can inject test doubles or alternative
 * PRF implementations without changing the keystream generation logic.
 *
 * When no dependencies are provided, `getPoseidonKeystreamGenerator()` uses
 * the cached default PRF returned by `getPoseidonPrf()`.
 *
 * @example
 * ```typescript
 * import { getPoseidonKeystreamGenerator } from '@umbra/sdk';
 *
 * // Use a mock PRF in tests
 * const mockPrf: PoseidonPrfFunction = async (seeds, point) => 1n as Bn254FieldElement;
 * const gen = getPoseidonKeystreamGenerator({ prf: mockPrf });
 * ```
 *
 * @see {@link getPoseidonKeystreamGenerator}
 * @public
 */
export interface PoseidonKeystreamGeneratorDeps {
  /**
   * Optional custom PRF function.
   *
   * @remarks
   * When provided, the keystream generator uses this PRF instead of the default
   * `getPoseidonPrf()` singleton. The result is cached per PRF reference using
   * a `WeakMap`.
   *
   * If not provided, the generator is cached as a module-level singleton.
   *
   * @defaultValue The return value of `getPoseidonPrf()`
   */
  readonly prf?: PoseidonPrfFunction;
}

/**
 * Returns a cached Poseidon keystream generator function.
 *
 * This function returns a `PoseidonKeystreamGeneratorFunction` that generates keystream
 * values for counter-mode encryption operations. The keystream is computed using
 * the Poseidon PRF with a domain-separated evaluation point.
 *
 * @param deps - Optional dependencies including custom PRF function.
 * @returns A `PoseidonKeystreamGeneratorFunction` that generates keystreams for counters
 *
 * @remarks
 * ## Caching
 *
 * - When called without arguments (using default PRF), returns a cached singleton
 * - When called with a custom PRF, returns a cached function per PRF instance
 * - The cache uses WeakMap for custom PRFs to allow garbage collection
 *
 * ## Keystream Generation Formula
 *
 * For each counter, the keystream is computed as:
 * ```
 * keystream = Poseidon([transactionViewingKey, counter, evaluationPoint])
 * ```
 *
 * Where:
 * - `transactionViewingKey` is the master key
 * - `counter` is the position/index for this keystream
 * - `evaluationPoint` is 2 (domain separation constant)
 *
 * ## Security Properties
 *
 * - **Deterministic**: Same (key, counter) pair always produces the same keystream
 * - **Domain-separated**: The evaluation point (2) ensures this PRF is distinct
 *   from other uses of the same key
 * - **Counter-dependent**: Different counters produce completely different keystreams
 *
 * ## Use Cases
 *
 * - Stream cipher encryption in ZK protocols
 * - Generating unique encryption masks for each position
 * - Confidential transaction data encryption
 *
 * @example
 * ```typescript
 * import { getPoseidonKeystreamGenerator } from '@umbra/sdk';
 * import { assertPoseidonKey, assertPoseidonCounter } from '@umbra/sdk/types';
 *
 * // Get the keystream generator (cached singleton)
 * const keystreamGenerator = getPoseidonKeystreamGenerator();
 *
 * // Generate keystreams for positions 0, 1, 2
 * const key: PoseidonKey = transactionViewingKey;
 * assertPoseidonKey(key);
 *
 * const counters: PoseidonCounter[] = [0n, 1n, 2n];
 * counters.forEach(assertPoseidonCounter);
 *
 * const keystreamMap = await keystreamGenerator(counters, key);
 *
 * // Use keystreams for encryption
 * const keystream0 = keystreamMap.get(0n)!;
 * const ciphertext0 = (plaintext0 + keystream0) % BN254_FIELD_PRIME;
 * ```
 *
 * @example
 * ```typescript
 * // Using a custom PRF
 * const customPrf: PoseidonPrfFunction = myCustomPrf;
 * const keystreamGenerator = getPoseidonKeystreamGenerator(customPrf);
 *
 * const keystreamMap = await keystreamGenerator([0n, 1n], key);
 * ```
 *
 * @public
 */
export function getPoseidonKeystreamGenerator(
  deps?: PoseidonKeystreamGeneratorDeps,
): PoseidonKeystreamGeneratorFunction {
  const { prf } = deps ?? {};

  // If no PRF provided, use the default cached PRF
  if (prf === undefined) {
    if (cachedDefaultKeystreamGenerator !== null) {
      return cachedDefaultKeystreamGenerator;
    }

    const defaultPrf = getPoseidonPrf();
    const generator = createKeystreamGeneratorFunction(defaultPrf);
    cachedDefaultKeystreamGenerator = generator;
    return generator;
  }

  // Check if we have a cached keystream generator for this PRF
  const cachedGenerator = keystreamGeneratorCache.get(prf);
  if (cachedGenerator !== undefined) {
    return cachedGenerator;
  }

  // Create and cache a new keystream generator for this PRF
  const generator = createKeystreamGeneratorFunction(prf);
  keystreamGeneratorCache.set(prf, generator);
  return generator;
}

/**
 * Creates a keystream generator function using the provided PRF.
 *
 * This internal factory function constructs a `PoseidonKeystreamGeneratorFunction` that
 * uses the specified PRF for computing keystreams. The returned function performs
 * full input validation on counters and the key before invoking the PRF.
 *
 * @param prf - The `PoseidonPrfFunction` to use for computing keystreams.
 *              This allows for dependency injection of custom PRFs.
 * @returns A `PoseidonKeystreamGeneratorFunction` implementation that validates inputs
 *          and delegates to the provided PRF.
 *
 * @throws {Error} If the returned generator function is called with:
 *         - An empty counters array
 *         - Invalid PoseidonCounter values in counters
 *         - Invalid PoseidonKey
 *
 * @remarks
 * ## Keystream Generation
 *
 * For each counter in the input array, the keystream is computed as:
 * ```
 * keystream[counter] = PRF([key, counter], KEYSTREAM_EVALUATION_POINT)
 *                    = Poseidon([key, counter, 2])
 * ```
 *
 * ## Input Validation
 *
 * The returned function performs the following validations:
 * 1. Counters array must have at least 1 element
 * 2. Each counter must be a valid PoseidonCounter (BN254 field element)
 * 3. The key must be a valid PoseidonKey (BN254 field element)
 * 4. Each output keystream is validated to be a valid PoseidonKeystream
 *
 * ## Why This Factory Pattern
 *
 * This factory function enables:
 * - Separation of keystream logic from PRF implementation
 * - Dependency injection for testing with mock PRFs
 * - Caching of generator functions per PRF instance in `getPoseidonKeystreamGenerator()`
 *
 * @internal
 */
function createKeystreamGeneratorFunction(
  prf: PoseidonPrfFunction,
): PoseidonKeystreamGeneratorFunction {
  return async (
    counters: readonly PoseidonCounter[],
    key: PoseidonKey,
  ): Promise<Map<PoseidonCounter, PoseidonKeystream>> => {
    // Validate counters array is not empty
    if (counters.length === 0) {
      throw new Error("Keystream generator requires at least 1 counter.");
    }

    // Validate each counter is a valid PoseidonCounter
    for (const [index, counterElement] of counters.entries()) {
      const counter = counterElement;
      try {
        assertPoseidonCounter(counter);
      } catch (error) {
        if (error instanceof Error) {
          throw new TypeError(`Invalid counter at index ${String(index)}: ${error.message}`);
        }
        throw error;
      }
    }

    // Validate the key is a valid PoseidonKey
    try {
      assertPoseidonKey(key);
    } catch (error) {
      if (error instanceof Error) {
        throw new TypeError(`Invalid key: ${error.message}`);
      }
      throw error;
    }

    // Generate keystreams for each counter
    // keystream = PRF([key, counter], evaluationPoint)
    //           = Poseidon([key, counter, evaluationPoint])
    const keystreamMap = new Map<PoseidonCounter, PoseidonKeystream>();

    for (const counter of counters) {
      // Compute keystream using PRF with key and counter as seeds
      const keystream = await prf([key, counter], KEYSTREAM_EVALUATION_POINT as Bn254FieldElement);

      // Validate output is a valid PoseidonKeystream
      assertPoseidonKeystream(keystream);
      keystreamMap.set(counter, keystream);
    }

    return keystreamMap;
  };
}

// ============================================================================
// Encryptor/Decryptor Caches
// ============================================================================

/**
 * Cache for the default encryptor function (using default keystream generator and modAdd).
 * @internal
 */
let cachedDefaultEncryptor: PoseidonEncryptorFunction | null = null;

/**
 * Cache for encryptor functions with custom options.
 * Key is a composite of the keystream generator and modAdd function references.
 * @internal
 */
const encryptorCache = new WeakMap<
  PoseidonKeystreamGeneratorFunction,
  WeakMap<ModuleAddFunction, PoseidonEncryptorFunction>
>();

/**
 * Cache for the default decryptor function (using default keystream generator and modSub).
 * @internal
 */
let cachedDefaultDecryptor: PoseidonDecryptorFunction | null = null;

/**
 * Cache for decryptor functions with custom options.
 * Key is a composite of the keystream generator and modSub function references.
 * @internal
 */
const decryptorCache = new WeakMap<
  PoseidonKeystreamGeneratorFunction,
  WeakMap<ModuleSubFunction, PoseidonDecryptorFunction>
>();

// ============================================================================
// Encryptor/Decryptor Options
// ============================================================================

/**
 * Optional dependencies for the Poseidon encryptor factory.
 *
 * @remarks
 * This interface enables dependency injection for the Poseidon encryptor. By
 * providing custom implementations of the keystream generator and modular addition
 * function, callers can test the encryptor in isolation or substitute alternative
 * field arithmetic implementations.
 *
 * The encryption formula is:
 * ```
 * ciphertext[i] = modAdd(plaintext[i], keystream[i])
 * ```
 *
 * Where `keystream[i] = Poseidon([key, i, 2])`.
 *
 * @example
 * ```typescript
 * import { getPoseidonEncryptor } from '@umbra/sdk';
 *
 * // Use a mock keystream generator in tests
 * const mockGen: PoseidonKeystreamGeneratorFunction = async (counters, key) => {
 *   const map = new Map();
 *   for (const c of counters) map.set(c, 1n as PoseidonKeystream);
 *   return map;
 * };
 * const encryptor = getPoseidonEncryptor({ keystreamGenerator: mockGen });
 * ```
 *
 * @see {@link getPoseidonEncryptor}
 * @public
 */
export interface PoseidonEncryptorDeps {
  /**
   * Custom keystream generator function.
   *
   * @remarks
   * When provided, the encryptor derives keystream values using this function
   * instead of the default `getPoseidonKeystreamGenerator()` singleton.
   * The resulting encryptor is cached per generator reference using a `WeakMap`.
   *
   * @defaultValue The return value of `getPoseidonKeystreamGenerator()`
   */
  readonly keystreamGenerator?: PoseidonKeystreamGeneratorFunction;

  /**
   * Custom modular addition function for encryption.
   *
   * @remarks
   * The modular addition computes `(plaintext + keystream) mod p` where `p` is
   * the BN254 field prime. The default implementation runs in constant time to
   * prevent timing side-channels.
   *
   * @defaultValue The constant-time `bn254ModuloAdd` function
   */
  readonly modAdd?: ModuleAddFunction;
}

/**
 * Optional dependencies for the Poseidon decryptor factory.
 *
 * @remarks
 * This interface enables dependency injection for the Poseidon decryptor. By
 * providing custom implementations of the keystream generator and modular subtraction
 * function, callers can test the decryptor in isolation or substitute alternative
 * field arithmetic implementations.
 *
 * The decryption formula is:
 * ```
 * plaintext[i] = modSub(ciphertext[i], keystream[i])
 * ```
 *
 * Where `keystream[i] = Poseidon([key, i, 2])`. The key must match the one used
 * during encryption to recover the original plaintext.
 *
 * @example
 * ```typescript
 * import { getPoseidonDecryptor, getPoseidonEncryptor } from '@umbra/sdk';
 *
 * // Round-trip test with custom modular arithmetic
 * const p = 21888242871839275222246405745257275088548364400416034343698204186575808495617n;
 * const customModSub = (a: bigint, b: bigint): bigint => ((a - b) % p + p) % p;
 *
 * const decryptor = getPoseidonDecryptor({ modSub: customModSub });
 * ```
 *
 * @see {@link getPoseidonDecryptor}
 * @see {@link PoseidonEncryptorDeps} for the symmetric encryption configuration
 * @public
 */
export interface PoseidonDecryptorDeps {
  /**
   * Custom keystream generator function.
   *
   * @remarks
   * When provided, the decryptor derives keystream values using this function
   * instead of the default `getPoseidonKeystreamGenerator()` singleton.
   * The resulting decryptor is cached per generator reference using a `WeakMap`.
   *
   * @defaultValue The return value of `getPoseidonKeystreamGenerator()`
   */
  readonly keystreamGenerator?: PoseidonKeystreamGeneratorFunction;

  /**
   * Custom modular subtraction function for decryption.
   *
   * @remarks
   * The modular subtraction computes `(ciphertext - keystream) mod p` where `p` is
   * the BN254 field prime. The default implementation runs in constant time to
   * prevent timing side-channels.
   *
   * @defaultValue The constant-time `bn254ModuloSub` function
   */
  readonly modSub?: ModuleSubFunction;
}

// ============================================================================
// Encryptor Implementation
// ============================================================================

/**
 * Creates an encryptor function with the specified dependencies.
 *
 * This internal factory function creates a `PoseidonEncryptorFunction` that encrypts
 * plaintexts using a keystream-based approach. For each plaintext at index `i`,
 * the ciphertext is computed as:
 *
 * ```
 * ciphertext[i] = modAdd(plaintext[i], keystream[i])
 * ```
 *
 * Where `keystream[i]` is generated from the PRF with counter `i`.
 *
 * @param keystreamGenerator - The keystream generator to use
 * @param modAdd - The modular addition function to use
 * @returns A `PoseidonEncryptorFunction` implementation
 *
 * @internal
 */
function createEncryptorFunction(
  keystreamGenerator: PoseidonKeystreamGeneratorFunction,
  moduleAdd: ModuleAddFunction,
): PoseidonEncryptorFunction {
  return async (
    plaintexts: readonly PoseidonPlaintext[],
    key: PoseidonKey,
  ): Promise<PoseidonCiphertext[]> => {
    // Validate plaintexts array is not empty
    if (plaintexts.length === 0) {
      throw new Error("Encryptor requires at least 1 plaintext.");
    }

    // Validate each plaintext
    for (const [index, plaintextElement] of plaintexts.entries()) {
      const plaintext = plaintextElement;
      try {
        assertPoseidonPlaintext(plaintext);
      } catch (error) {
        if (error instanceof Error) {
          throw new TypeError(`Invalid plaintext at index ${String(index)}: ${error.message}`);
        }
        throw error;
      }
    }

    // Validate the key
    try {
      assertPoseidonKey(key);
    } catch (error) {
      if (error instanceof Error) {
        throw new TypeError(`Invalid key: ${error.message}`);
      }
      throw error;
    }

    // Generate counters 0, 1, 2, ..., n-1 for n plaintexts
    const counters: PoseidonCounter[] = [];
    for (let index = 0; index < plaintexts.length; index++) {
      const counter = BigInt(index) as PoseidonCounter;
      assertPoseidonCounter(counter);
      counters.push(counter);
    }

    // Generate keystreams for all counters
    const keystreamMap = await keystreamGenerator(counters, key);

    // Encrypt each plaintext
    const ciphertexts: PoseidonCiphertext[] = [];
    for (const [index, plaintextElement] of plaintexts.entries()) {
      const plaintext = plaintextElement;

      const counter = counters[index];
      const keystream = keystreamMap.get(counter);

      if (keystream === undefined) {
        throw new Error(
          `Keystream not found for counter ${String(counter)}. This should not happen.`,
        );
      }

      // ciphertext = (plaintext + keystream) mod p
      const ciphertextValue = moduleAdd(plaintext, keystream);

      // Validate output
      assertPoseidonCiphertext(ciphertextValue);
      ciphertexts.push(ciphertextValue);
    }

    return ciphertexts;
  };
}

/**
 * Returns a cached Poseidon encryptor function.
 *
 * This function returns a `PoseidonEncryptorFunction` that encrypts plaintexts using
 * a keystream-based approach. For each plaintext at position `i`, the ciphertext
 * is computed as:
 *
 * ```
 * ciphertext[i] = (plaintext[i] + keystream[i]) mod BN254_FIELD_PRIME
 * ```
 *
 * Where `keystream[i] = Poseidon([key, i, 2])`.
 *
 * @param opts - Optional configuration for the encryptor
 * @param opts.keystreamGenerator - Custom keystream generator (default: `getPoseidonKeystreamGenerator()`)
 * @param opts.modAdd - Custom modular addition function (default: `bn254ModuloAdd`)
 * @returns A `PoseidonEncryptorFunction` that encrypts plaintexts
 *
 * @remarks
 * ## Caching
 *
 * - When called without options, returns a cached singleton encryptor
 * - When called with custom options, caches the encryptor per option combination
 * - Uses WeakMap for caching to allow garbage collection
 *
 * ## Encryption Process
 *
 * 1. Validates all plaintexts are valid BN254 field elements
 * 2. Validates the key is a valid PoseidonKey
 * 3. Generates counters 0, 1, 2, ..., n-1 for n plaintexts
 * 4. Generates keystreams for each counter using the keystream generator
 * 5. Computes ciphertext[i] = modAdd(plaintext[i], keystream[i])
 * 6. Validates all outputs are valid PoseidonCiphertexts
 *
 * ## Security Notes
 *
 * - Uses constant-time modular addition by default to prevent timing attacks
 * - Each position gets a unique keystream derived from the key and counter
 * - The same (key, position) pair always produces the same keystream
 *
 * @example
 * ```typescript
 * import { getPoseidonEncryptor } from '@umbra/sdk';
 * import { assertPoseidonPlaintext, assertPoseidonKey } from '@umbra/sdk/types';
 *
 * // Get the encryptor (cached singleton)
 * const encryptor = getPoseidonEncryptor();
 *
 * // Prepare plaintexts
 * const plaintexts: PoseidonPlaintext[] = [100n, 200n, 300n];
 * plaintexts.forEach(assertPoseidonPlaintext);
 *
 * // Encrypt with a key
 * const key: PoseidonKey = transactionViewingKey;
 * assertPoseidonKey(key);
 *
 * const ciphertexts = await encryptor(plaintexts, key);
 * // ciphertexts[0] = (plaintexts[0] + keystream[0]) mod p
 * // ciphertexts[1] = (plaintexts[1] + keystream[1]) mod p
 * // ciphertexts[2] = (plaintexts[2] + keystream[2]) mod p
 * ```
 *
 * @example
 * ```typescript
 * // Using custom modular arithmetic
 * const customModAdd: ModuloAddFunction = (a, b) => (a + b) % BN254_FIELD_PRIME;
 *
 * const encryptor = getPoseidonEncryptor({
 *     modAdd: customModAdd
 * });
 *
 * const ciphertexts = await encryptor(plaintexts, key);
 * ```
 *
 * @public
 */
export function getPoseidonEncryptor(deps?: PoseidonEncryptorDeps): PoseidonEncryptorFunction {
  // Use defaults if no deps provided
  const keystreamGen = deps?.keystreamGenerator ?? getPoseidonKeystreamGenerator();
  const moduleAddFunction = deps?.modAdd ?? getBn254ModuleAdder();

  // If using all defaults, return cached singleton
  if (deps === undefined || (deps.keystreamGenerator === undefined && deps.modAdd === undefined)) {
    if (cachedDefaultEncryptor !== null) {
      return cachedDefaultEncryptor;
    }
    const encryptor = createEncryptorFunction(keystreamGen, moduleAddFunction);
    cachedDefaultEncryptor = encryptor;
    return encryptor;
  }

  // Check cache for this combination
  let moduleAddCache = encryptorCache.get(keystreamGen);
  if (moduleAddCache === undefined) {
    moduleAddCache = new WeakMap<ModuleAddFunction, PoseidonEncryptorFunction>();
    encryptorCache.set(keystreamGen, moduleAddCache);
  }

  const cachedEncryptor = moduleAddCache.get(moduleAddFunction);
  if (cachedEncryptor !== undefined) {
    return cachedEncryptor;
  }

  // Create and cache new encryptor
  const encryptor = createEncryptorFunction(keystreamGen, moduleAddFunction);
  moduleAddCache.set(moduleAddFunction, encryptor);
  return encryptor;
}

// ============================================================================
// Decryptor Implementation
// ============================================================================

/**
 * Creates a decryptor function with the specified dependencies.
 *
 * This internal factory function creates a `PoseidonDecryptorFunction` that decrypts
 * ciphertexts using a keystream-based approach. For each ciphertext at index `i`,
 * the plaintext is computed as:
 *
 * ```
 * plaintext[i] = modSub(ciphertext[i], keystream[i])
 * ```
 *
 * Where `keystream[i]` is generated from the PRF with counter `i`.
 *
 * @param keystreamGenerator - The keystream generator to use
 * @param modSub - The modular subtraction function to use
 * @returns A `PoseidonDecryptorFunction` implementation
 *
 * @internal
 */
function createDecryptorFunction(
  keystreamGenerator: PoseidonKeystreamGeneratorFunction,
  moduleSub: ModuleSubFunction,
): PoseidonDecryptorFunction {
  return async (
    ciphertexts: readonly PoseidonCiphertext[],
    key: PoseidonKey,
  ): Promise<PoseidonPlaintext[]> => {
    // Validate ciphertexts array is not empty
    if (ciphertexts.length === 0) {
      throw new Error("Decryptor requires at least 1 ciphertext.");
    }

    // Validate each ciphertext
    for (const [index, ciphertextElement] of ciphertexts.entries()) {
      const ciphertext = ciphertextElement;
      try {
        assertPoseidonCiphertext(ciphertext);
      } catch (error) {
        if (error instanceof Error) {
          throw new TypeError(`Invalid ciphertext at index ${String(index)}: ${error.message}`);
        }
        throw error;
      }
    }

    // Validate the key
    try {
      assertPoseidonKey(key);
    } catch (error) {
      if (error instanceof Error) {
        throw new TypeError(`Invalid key: ${error.message}`);
      }
      throw error;
    }

    // Generate counters 0, 1, 2, ..., n-1 for n ciphertexts
    const counters: PoseidonCounter[] = [];
    for (let index = 0; index < ciphertexts.length; index++) {
      const counter = BigInt(index) as PoseidonCounter;
      assertPoseidonCounter(counter);
      counters.push(counter);
    }

    // Generate keystreams for all counters
    const keystreamMap = await keystreamGenerator(counters, key);

    // Decrypt each ciphertext
    const plaintexts: PoseidonPlaintext[] = [];
    for (const [index, ciphertextElement] of ciphertexts.entries()) {
      const ciphertext = ciphertextElement;

      const counter = counters[index];
      const keystream = keystreamMap.get(counter);

      if (keystream === undefined) {
        throw new Error(
          `Keystream not found for counter ${String(counter)}. This should not happen.`,
        );
      }

      // plaintext = (ciphertext - keystream) mod p
      const plaintextValue = moduleSub(ciphertext, keystream);

      // Validate output
      assertPoseidonPlaintext(plaintextValue);
      plaintexts.push(plaintextValue);
    }

    return plaintexts;
  };
}

/**
 * Returns a cached Poseidon decryptor function.
 *
 * This function returns a `PoseidonDecryptorFunction` that decrypts ciphertexts using
 * a keystream-based approach. For each ciphertext at position `i`, the plaintext
 * is computed as:
 *
 * ```
 * plaintext[i] = (ciphertext[i] - keystream[i]) mod BN254_FIELD_PRIME
 * ```
 *
 * Where `keystream[i] = Poseidon([key, i, 2])`.
 *
 * @param opts - Optional configuration for the decryptor
 * @param opts.keystreamGenerator - Custom keystream generator (default: `getPoseidonKeystreamGenerator()`)
 * @param opts.modSub - Custom modular subtraction function (default: `bn254ModuloSub`)
 * @returns A `PoseidonDecryptorFunction` that decrypts ciphertexts
 *
 * @remarks
 * ## Caching
 *
 * - When called without options, returns a cached singleton decryptor
 * - When called with custom options, caches the decryptor per option combination
 * - Uses WeakMap for caching to allow garbage collection
 *
 * ## Decryption Process
 *
 * 1. Validates all ciphertexts are valid BN254 field elements
 * 2. Validates the key is a valid PoseidonKey
 * 3. Generates counters 0, 1, 2, ..., n-1 for n ciphertexts
 * 4. Generates keystreams for each counter using the keystream generator
 * 5. Computes plaintext[i] = modSub(ciphertext[i], keystream[i])
 * 6. Validates all outputs are valid PoseidonPlaintexts
 *
 * ## Security Notes
 *
 * - Uses constant-time modular subtraction by default to prevent timing attacks
 * - The key must be the same key used during encryption
 * - Using a wrong key will produce incorrect (garbage) plaintext output
 *
 * @example
 * ```typescript
 * import { getPoseidonDecryptor, getPoseidonEncryptor } from '@umbra/sdk';
 * import { assertPoseidonKey } from '@umbra/sdk/types';
 *
 * // Encrypt some data
 * const encryptor = getPoseidonEncryptor();
 * const plaintexts = [100n, 200n, 300n];
 * const key: PoseidonKey = transactionViewingKey;
 * const ciphertexts = await encryptor(plaintexts, key);
 *
 * // Decrypt the data
 * const decryptor = getPoseidonDecryptor();
 * const recovered = await decryptor(ciphertexts, key);
 * // recovered = [100n, 200n, 300n]
 * ```
 *
 * @example
 * ```typescript
 * // Using custom modular arithmetic
 * const customModSub: ModuloSubFunction = (a, b) => {
 *     const diff = a - b;
 *     return diff < 0n ? diff + BN254_FIELD_PRIME : diff;
 * };
 *
 * const decryptor = getPoseidonDecryptor({
 *     modSub: customModSub
 * });
 *
 * const plaintexts = await decryptor(ciphertexts, key);
 * ```
 *
 * @public
 */
export function getPoseidonDecryptor(deps?: PoseidonDecryptorDeps): PoseidonDecryptorFunction {
  // Use defaults if no deps provided
  const keystreamGen = deps?.keystreamGenerator ?? getPoseidonKeystreamGenerator();
  const moduleSubFunction = deps?.modSub ?? getBn254ModuleSubtractor();

  // If using all defaults, return cached singleton
  if (deps === undefined || (deps.keystreamGenerator === undefined && deps.modSub === undefined)) {
    if (cachedDefaultDecryptor !== null) {
      return cachedDefaultDecryptor;
    }
    const decryptor = createDecryptorFunction(keystreamGen, moduleSubFunction);
    cachedDefaultDecryptor = decryptor;
    return decryptor;
  }

  // Check cache for this combination
  let moduleSubCache = decryptorCache.get(keystreamGen);
  if (moduleSubCache === undefined) {
    moduleSubCache = new WeakMap<ModuleSubFunction, PoseidonDecryptorFunction>();
    decryptorCache.set(keystreamGen, moduleSubCache);
  }

  const cachedDecryptor = moduleSubCache.get(moduleSubFunction);
  if (cachedDecryptor !== undefined) {
    return cachedDecryptor;
  }

  // Create and cache new decryptor
  const decryptor = createDecryptorFunction(keystreamGen, moduleSubFunction);
  moduleSubCache.set(moduleSubFunction, decryptor);
  return decryptor;
}

// =============================================================================
// POSEIDON AGGREGATOR
// =============================================================================

/**
 * Maximum number of inputs the Poseidon aggregator can handle in a single call.
 *
 * @remarks
 * The aggregator uses a two-round approach:
 * - Round 1 splits inputs into chunks of up to {@link MAX_POSEIDON_INPUTS} (12) and hashes each chunk.
 * - Round 2 hashes all Round 1 outputs into a single final hash.
 *
 * Since Round 1 produces at most 12 outputs (each from a 12-element chunk),
 * Round 2 can handle them all in one call. This gives a theoretical maximum of
 * `12 * 12 = 144` inputs total.
 *
 * This limit directly constrains the ZK proof aggregated public input. The 70-element
 * aggregated Poseidon hash used as the single ZK proof public input for Umbra claim
 * operations (aggregating nullifiers, commitments, timestamps, addresses, etc.) fits
 * well within this bound.
 *
 * @example
 * ```typescript
 * import { getPoseidonAggregator, MAX_AGGREGATOR_INPUTS } from '@umbra/sdk';
 *
 * const aggregator = getPoseidonAggregator();
 *
 * // Maximum supported inputs
 * const maxInputs = Array.from({ length: MAX_AGGREGATOR_INPUTS }, (_, i) => BigInt(i));
 * maxInputs.forEach(assertBn254FieldElement);
 * const hash = await aggregator(maxInputs);
 * ```
 *
 * @see {@link getPoseidonAggregator} for the aggregator factory
 * @see {@link MAX_POSEIDON_INPUTS} for the base hash arity limit
 * @public
 */
export const MAX_AGGREGATOR_INPUTS = MAX_POSEIDON_INPUTS * MAX_POSEIDON_INPUTS;

/**
 * Asynchronous function type for Poseidon hash aggregation over large input sets.
 *
 * @remarks
 * The aggregator chains two rounds of Poseidon hashing to process input sets
 * larger than the 12-element per-call limit. It always performs two rounds for
 * Circom circuit compatibility, even when the input set would fit in one call.
 *
 * Two-round construction:
 * ```
 * Round 1: hash chunks of up to 12 elements
 *   intermediates[i] = Poseidon(inputs[i*12 .. (i+1)*12])
 *
 * Round 2: hash all intermediates
 *   result = Poseidon(intermediates)
 * ```
 *
 * In Umbra, this is the function used to produce the single 70-element aggregated
 * Poseidon hash that serves as the sole ZK proof public input for claim operations.
 * The 70 elements aggregate nullifiers, commitments, timestamps, destination addresses,
 * amounts, and other ZK-circuit inputs across up to 10 UTXOs.
 *
 * @param inputs - Array of `Bn254FieldElement` values to hash (1 to {@link MAX_AGGREGATOR_INPUTS} elements)
 * @returns A `Promise` resolving to the aggregated `Bn254FieldElement` hash output
 *
 * @throws {Error} If `inputs` is empty
 * @throws {Error} If `inputs.length` exceeds {@link MAX_AGGREGATOR_INPUTS}
 *
 * @example
 * ```typescript
 * const aggregator: PoseidonAggregatorFunction = getPoseidonAggregator();
 *
 * // 70-element aggregated hash for ZK public input
 * const publicInputs: Bn254FieldElement[] = [...nullifiers, ...commitments, ...rest];
 * const aggregatedHash = await aggregator(publicInputs);
 * ```
 *
 * @see {@link getPoseidonAggregator} for the factory function
 * @see {@link MAX_AGGREGATOR_INPUTS} for the maximum supported input count
 * @public
 */
export type PoseidonAggregatorFunction = (
  inputs: readonly Bn254FieldElement[],
) => Promise<Bn254FieldElement>;

/**
 * Optional dependencies for the Poseidon aggregator factory.
 *
 * @remarks
 * This interface enables dependency injection for the Poseidon aggregator.
 * Providing a custom hasher allows substituting test doubles or verifying
 * the aggregator's two-round structure independently of the hash implementation.
 *
 * When no dependencies are provided, `getPoseidonAggregator()` uses the cached
 * default hasher from `getPoseidonHasher()`.
 *
 * @example
 * ```typescript
 * import { getPoseidonAggregator } from '@umbra/sdk';
 *
 * const calls: Bn254FieldElement[][] = [];
 * const trackingHasher: PoseidonHashFunction = async (inputs) => {
 *   calls.push([...inputs]);
 *   return getPoseidonHasher()(inputs);
 * };
 * const aggregator = getPoseidonAggregator({ hasher: trackingHasher });
 * // After calling aggregator([a, b, ..., z]), inspect `calls` to verify
 * // Round 1 chunks and the Round 2 combination.
 * ```
 *
 * @see {@link getPoseidonAggregator}
 * @public
 */
export interface PoseidonAggregatorDeps {
  /**
   * Optional custom hasher function.
   *
   * @remarks
   * When provided, the aggregator uses this hasher for both rounds of hashing
   * instead of the default `getPoseidonHasher()` singleton. The resulting
   * aggregator is cached per hasher reference using a `WeakMap`.
   *
   * @defaultValue The return value of `getPoseidonHasher()`
   */
  readonly hasher?: PoseidonHashFunction;
}

/**
 * Cached default aggregator for singleton pattern.
 * @internal
 */
let cachedDefaultAggregator: PoseidonAggregatorFunction | null = null;

/**
 * Cache for aggregators with custom hashers.
 * @internal
 */
const aggregatorCache = new WeakMap<PoseidonHashFunction, PoseidonAggregatorFunction>();

/**
 * Creates a Poseidon aggregator function with the given hasher.
 *
 * @param hasher - The Poseidon hash function to use for both rounds of aggregation.
 * @returns A {@link PoseidonAggregatorFunction} that chains two rounds of Poseidon hashing.
 *
 * @remarks
 * This internal factory implements the two-round Circom-compatible aggregation:
 *
 * - Round 1: splits `inputs` into consecutive chunks of at most 12 elements and
 *   hashes each chunk independently. Produces `ceil(inputs.length / 12)` intermediate
 *   hashes.
 * - Round 2: hashes all intermediate outputs from Round 1 into a single final value.
 *
 * Critically, even for inputs that fit in a single 12-element call, the function still
 * performs both rounds (i.e., `Poseidon([Poseidon(inputs)])`), preserving compatibility
 * with the Circom `PoseidonAggregator` circuit which always executes two rounds.
 *
 * @throws {Error} If `inputs` is empty.
 * @throws {Error} If `inputs.length` exceeds `MAX_AGGREGATOR_INPUTS` (144).
 * @throws {TypeError} If any element of `inputs` is not a `bigint`.
 *
 * @privateRemarks
 * The factory pattern here enables caching of the returned closure per hasher instance.
 * `getPoseidonAggregator()` stores the result in a WeakMap keyed by `hasher`, so the
 * closure is created at most once per hasher object.
 *
 * @internal
 */
function createAggregatorFunction(hasher: PoseidonHashFunction): PoseidonAggregatorFunction {
  return async (inputs: readonly Bn254FieldElement[]): Promise<Bn254FieldElement> => {
    // Validate inputs
    if (inputs.length === 0) {
      throw new Error(
        "Poseidon aggregator requires at least one input. " +
          "Provide at least one Bn254FieldElement value in the inputs array.",
      );
    }

    if (inputs.length > MAX_AGGREGATOR_INPUTS) {
      throw new Error(
        `Poseidon aggregator supports at most ${String(MAX_AGGREGATOR_INPUTS)} inputs, got ${String(inputs.length)}. ` +
          `The maximum is ${String(MAX_POSEIDON_INPUTS)}^2 = ${String(MAX_AGGREGATOR_INPUTS)} due to the two-round aggregation approach.`,
      );
    }

    // Validate all inputs are bigints
    for (const [index, input] of inputs.entries()) {
      if (typeof input !== "bigint") {
        throw new TypeError(
          `Invalid input at index ${String(index)}: expected bigint (Bn254FieldElement), got ${typeof input}. ` +
            "All inputs must be Bn254FieldElement values.",
        );
      }
    }

    // ================================================================
    // Round 1: Hash input chunks
    // ================================================================
    // NOTE: Unlike a naive implementation, we ALWAYS perform two rounds to match
    // the Circom PoseidonAggregator circuit. Even for ≤12 inputs, the circuit
    // computes poseidon([poseidon(inputs)]), not just poseidon(inputs).

    const numberFirstRoundHashes = Math.ceil(inputs.length / MAX_POSEIDON_INPUTS);
    const firstRoundOutputs: Bn254FieldElement[] = [];

    let inputOffset = 0;

    for (let index = 0; index < numberFirstRoundHashes; index++) {
      const remainingInputs = inputs.length - inputOffset;
      const chunkSize = Math.min(MAX_POSEIDON_INPUTS, remainingInputs);
      const chunk = inputs.slice(inputOffset, inputOffset + chunkSize);
      const chunkHash = await hasher(chunk);
      firstRoundOutputs.push(chunkHash);
      inputOffset += MAX_POSEIDON_INPUTS;
    }

    // ================================================================
    // Round 2: Hash all round 1 outputs
    // ================================================================
    // Since we have at most 144 inputs, we have at most 12 outputs from round 1,
    // so this fits in a single Poseidon hash.
    const finalHash = await hasher(firstRoundOutputs);

    assertBn254FieldElement(finalHash);
    return finalHash;
  };
}

/**
 * Returns a cached Poseidon aggregator function.
 *
 * The aggregator chains Poseidon hash calls to process large input sets
 * (up to 144 elements), matching the behavior of the Circom `PoseidonAggregator` circuit.
 *
 * @param deps - Optional dependencies including custom hasher function.
 * @returns A `PoseidonAggregatorFunction` that computes aggregated hashes
 *
 * @remarks
 * ## Caching
 *
 * - When called without arguments (using default hasher), returns a cached singleton
 * - When called with a custom hasher, returns a cached function per hasher instance
 * - The cache uses WeakMap for custom hashers to allow garbage collection
 *
 * ## Two-Round Aggregation
 *
 * The aggregation works as follows:
 * 1. **Round 1**: Split inputs into chunks of up to 12 elements each
 *    and hash each chunk with Poseidon
 * 2. **Round 2**: Hash all the outputs from Round 1 together
 *
 * ## Circuit Compatibility
 *
 * Unlike a naive implementation that might skip Round 2 for small inputs,
 * this function ALWAYS performs both rounds. For example, with 5 inputs:
 *
 * ```
 * Naive:   Poseidon([a, b, c, d, e])
 * Correct: Poseidon([Poseidon([a, b, c, d, e])])
 * ```
 *
 * This matches the Circom circuit which always computes
 * `Poseidon(numFirstRoundHashes)(firstRoundOutputs)`.
 *
 * ## Input Constraints
 *
 * - Minimum: 1 input
 * - Maximum: 144 inputs (12 * 12)
 *
 * @example
 * ```typescript
 * import { getPoseidonAggregator } from '@umbra-privacy/sdk';
 * import { assertBn254FieldElement } from '@umbra-privacy/sdk/types';
 *
 * // Get the aggregator (cached singleton)
 * const aggregator = getPoseidonAggregator();
 *
 * // Hash 5 field elements
 * const inputs = [1n, 2n, 3n, 4n, 5n].map(x => {
 *   assertBn254FieldElement(x);
 *   return x;
 * });
 * const hash = await aggregator(inputs);
 *
 * // Hash 100 field elements (across multiple chunks)
 * const largeInputs = Array.from({ length: 100 }, (_, i) => {
 *   const val = BigInt(i);
 *   assertBn254FieldElement(val);
 *   return val;
 * });
 * const largeHash = await aggregator(largeInputs);
 * ```
 *
 * @example
 * ```typescript
 * // Using a custom hasher
 * const customHasher: PoseidonHashFunction = myCustomHasher;
 * const aggregator = getPoseidonAggregator({ hasher: customHasher });
 *
 * const hash = await aggregator(inputs);
 * ```
 *
 * @public
 */
export function getPoseidonAggregator(deps?: PoseidonAggregatorDeps): PoseidonAggregatorFunction {
  const { hasher } = deps ?? {};

  // If no hasher provided, use the default cached hasher
  if (hasher === undefined) {
    if (cachedDefaultAggregator !== null) {
      return cachedDefaultAggregator;
    }

    const defaultHasher = getPoseidonHasher();
    const aggregator = createAggregatorFunction(defaultHasher);
    cachedDefaultAggregator = aggregator;
    return aggregator;
  }

  // Check if we have a cached aggregator for this hasher
  const cachedAggregator = aggregatorCache.get(hasher);
  if (cachedAggregator !== undefined) {
    return cachedAggregator;
  }

  // Create and cache new aggregator
  const aggregator = createAggregatorFunction(hasher);
  aggregatorCache.set(hasher, aggregator);
  return aggregator;
}

// ============================================================================
// H2 Hash Generator
// ============================================================================

import type {
  H2CircuitProvableParams,
  H2HashFunction as H2HashFunction,
  H2CircuitProvableHashFunction as H2CircuitProvableHashFunction,
  H2GeneratorFns,
  KeystreamCommitmentFunction as KeystreamCommitmentFunction,
} from "./interfaces";

/**
 * Optional dependencies for the H2 hash generator factory.
 *
 * @remarks
 * The H2 hash is a flat Poseidon(6) commitment used as the leaf in the Umbra mixer's
 * Indexed Merkle Tree (IMT). This interface allows the hasher to be swapped for testing.
 *
 * @see {@link getUtxoCommitmentHashGenerator}
 * @see {@link H2GeneratorFns}
 * @public
 */
export interface H2GeneratorDeps {
  /**
   * Optional custom Poseidon hasher function.
   *
   * When provided, both H2 generator functions (`generateCircuitProvableHash`,
   * `generateH2`) will use this hasher. Cached per hasher reference via `WeakMap`.
   *
   * @defaultValue The return value of `getPoseidonHasher()`
   */
  readonly hasher?: PoseidonHashFunction;
}

/**
 * Cached default H2 generator.
 * @internal
 */
let cachedDefaultH2Generator: H2GeneratorFns | null = null;

/**
 * Cache for H2 generators with custom hashers.
 * @internal
 */
const h2GeneratorCache = new WeakMap<PoseidonHashFunction, H2GeneratorFns>();

/**
 * Creates H2 hash generator functions bound to the given hasher.
 *
 * @param hasher - The Poseidon hash function to use for H2 computations.
 * @returns An {@link H2GeneratorFns} object with `generateCircuitProvableHash` and `generateH2`.
 *
 * Both compute the same flat Poseidon(6):
 * ```
 * H2 = Poseidon([amount, nullifier, userCommitment, addrLow, addrHigh, h2BlindingFactor])
 * ```
 *
 * @privateRemarks
 * Returned as a plain object (not a class) to enable easy destructuring and mocking.
 * The factory pattern (rather than module-level functions) allows `getUtxoCommitmentHashGenerator()`
 * to cache generators per hasher via WeakMap.
 *
 * @internal
 */
function createH2GeneratorFunctions(hasher: PoseidonHashFunction): H2GeneratorFns {
  /**
   * Flat Poseidon(6) hash over the six core UTXO fields.
   */
  const generateCircuitProvableHash: H2CircuitProvableHashFunction = async (
    params: H2CircuitProvableParams,
  ): Promise<Bn254FieldElement> => {
    const {
      amount,
      nullifier,
      userCommitment,
      finalDestinationAddressLow,
      finalDestinationAddressHigh,
      h2BlindingFactor,
    } = params;

    assertBn254FieldElement(amount);
    assertBn254FieldElement(nullifier);
    assertBn254FieldElement(userCommitment);
    assertBn254FieldElement(finalDestinationAddressLow);
    assertBn254FieldElement(finalDestinationAddressHigh);
    assertBn254FieldElement(h2BlindingFactor);

    const result = await hasher([
      amount,
      nullifier,
      userCommitment,
      finalDestinationAddressLow,
      finalDestinationAddressHigh,
      h2BlindingFactor,
    ]);

    assertBn254FieldElement(result);
    return result;
  };

  /**
   * Complete H2 leaf — flat Poseidon(6), identical to generateCircuitProvableHash.
   */
  const generateH2: H2HashFunction = async (
    params: H2CircuitProvableParams,
  ): Promise<Bn254FieldElement> => {
    const {
      amount,
      nullifier,
      userCommitment,
      finalDestinationAddressLow,
      finalDestinationAddressHigh,
      h2BlindingFactor,
    } = params;

    assertBn254FieldElement(amount);
    assertBn254FieldElement(nullifier);
    assertBn254FieldElement(userCommitment);
    assertBn254FieldElement(finalDestinationAddressLow);
    assertBn254FieldElement(finalDestinationAddressHigh);
    assertBn254FieldElement(h2BlindingFactor);

    const result = await hasher([
      amount,
      nullifier,
      userCommitment,
      finalDestinationAddressLow,
      finalDestinationAddressHigh,
      h2BlindingFactor,
    ]);

    assertBn254FieldElement(result);
    return result;
  };

  return {
    generateCircuitProvableHash,
    generateH2,
  };
}

/**
 * Returns a cached H2 hash generator with all H2-related functions.
 *
 * @remarks
 * H2 is computed as a flat Poseidon(6) hash:
 * ```
 * H2 = Poseidon([amount, nullifier, userCommitment, addrLow, addrHigh, h2BlindingFactor])
 * ```
 *
 * Caching: without arguments returns a singleton; with a custom hasher, caches per instance.
 *
 * @param deps - Optional dependencies including custom hasher function.
 * @returns An `H2GeneratorFns` object containing H2-related hash functions.
 *
 * @example
 * ```typescript
 * import { getUtxoCommitmentHashGenerator } from '@umbra-privacy/sdk';
 *
 * const h2Generator = getUtxoCommitmentHashGenerator();
 *
 * const h2Hash = await h2Generator.generateH2({
 *   amount: 1000000n as Bn254FieldElement,
 *   nullifier: computedNullifier,
 *   userCommitment: receiverCommitment,
 *   finalDestinationAddressLow: addressLow,
 *   finalDestinationAddressHigh: addressHigh,
 *   h2BlindingFactor: randomBlinding
 * });
 * ```
 *
 * @public
 */
export function getUtxoCommitmentHashGenerator(deps?: H2GeneratorDeps): H2GeneratorFns {
  const { hasher } = deps ?? {};

  // If no hasher provided, use the default cached hasher
  if (hasher === undefined) {
    if (cachedDefaultH2Generator !== null) {
      return cachedDefaultH2Generator;
    }

    const defaultHasher = getPoseidonHasher();
    const generator = createH2GeneratorFunctions(defaultHasher);
    cachedDefaultH2Generator = generator;
    return generator;
  }

  // Check if we have a cached generator for this hasher
  const cachedGenerator = h2GeneratorCache.get(hasher);
  if (cachedGenerator !== undefined) {
    return cachedGenerator;
  }

  // Create and cache new generator
  const generator = createH2GeneratorFunctions(hasher);
  h2GeneratorCache.set(hasher, generator);
  return generator;
}

// ============================================================================
// Keystream Commitment Generator
// ============================================================================

/**
 * Optional dependencies for the keystream commitment generator factory.
 *
 * @remarks
 * Keystream commitments are used in the Umbra linker encryption scheme to bind the
 * encryption keystream values to a blinding factor without revealing the keystream
 * itself. The commitment is later used in zero-knowledge proof verification.
 *
 * The commitment formula is:
 * ```
 * commitment = Poseidon([keystream, blindingFactor])
 * ```
 *
 * Providing a custom hasher enables dependency injection for testing or for using
 * an alternative Poseidon implementation.
 *
 * @example
 * ```typescript
 * import { getKeystreamCommitmentGenerator } from '@umbra/sdk';
 *
 * // Substitute a mock hasher in unit tests
 * const mockHasher: PoseidonHashFunction = async ([k, b]) => (k + b) as Bn254FieldElement;
 * const commitmentGen = getKeystreamCommitmentGenerator({ hasher: mockHasher });
 * ```
 *
 * @see {@link getKeystreamCommitmentGenerator}
 * @see {@link KeystreamCommitmentFunction} for the generated function's type
 * @public
 */
export interface KeystreamCommitmentDeps {
  /**
   * Optional custom Poseidon hasher function.
   *
   * @remarks
   * When provided, the commitment function uses this hasher instead of the default
   * `getPoseidonHasher()` singleton. The result is cached per hasher reference
   * using a `WeakMap`.
   *
   * @defaultValue The return value of `getPoseidonHasher()`
   */
  readonly hasher?: PoseidonHashFunction;
}

/**
 * Cached default keystream commitment generator.
 * @internal
 */
let cachedDefaultKeystreamCommitmentFunction: KeystreamCommitmentFunction | null = null;

/**
 * Cache for keystream commitment generators with custom hashers.
 * @internal
 */
const keystreamCommitmentCache = new WeakMap<PoseidonHashFunction, KeystreamCommitmentFunction>();

/**
 * Creates a keystream commitment function bound to the given hasher.
 *
 * @param hasher - The Poseidon hash function to use for computing commitments.
 * @returns A {@link KeystreamCommitmentFunction} that computes
 *   `Poseidon([keystream, blindingFactor])`.
 *
 * @remarks
 * The returned function validates both inputs before hashing:
 * - `keystream` must be a valid BN254 field element
 * - `blindingFactor` must be a valid BN254 field element
 *
 * The commitment hides the keystream while binding it to the blinding factor.
 * A verifier who knows both `keystream` and `blindingFactor` can recompute the
 * commitment and confirm it matches what was published on-chain.
 *
 * @throws {CryptographyAssertionError} If either input is not a valid BN254 field element.
 *
 * @privateRemarks
 * This factory function enables the commitment function to be cached per hasher
 * reference by `getKeystreamCommitmentGenerator()`. The closure captures the
 * `hasher` argument to avoid re-resolving it on every call.
 *
 * @internal
 */
function createKeystreamCommitmentFunction(
  hasher: PoseidonHashFunction,
): KeystreamCommitmentFunction {
  return async (
    keystream: Bn254FieldElement,
    blindingFactor: Bn254FieldElement,
  ): Promise<Bn254FieldElement> => {
    // Validate inputs
    assertBn254FieldElement(keystream);
    assertBn254FieldElement(blindingFactor);

    // commitment = Poseidon([keystream, blindingFactor])
    const result = await hasher([keystream, blindingFactor]);

    assertBn254FieldElement(result);
    return result;
  };
}

/**
 * Returns a cached keystream commitment generator function.
 *
 * @remarks
 * Keystream commitments bind the encryption keystream values without revealing them.
 * Used in the linker encryption scheme for zero-knowledge proof verification.
 *
 * **Formula:**
 * ```
 * commitment = Poseidon([keystream, blindingFactor])
 * ```
 *
 * ## Caching
 *
 * - When called without arguments, returns a cached singleton
 * - When called with a custom hasher, returns a cached function per hasher instance
 *
 * @param deps - Optional dependencies including custom hasher function.
 * @returns A `KeystreamCommitmentFunction` that computes keystream commitments.
 *
 * @example
 * ```typescript
 * import { getKeystreamCommitmentGenerator } from '@umbra-privacy/sdk';
 *
 * const generateCommitment = getKeystreamCommitmentGenerator();
 *
 * const keystream = ... // From Poseidon cipher keystream
 * const blindingFactor = ... // Random blinding factor
 *
 * const commitment = await generateCommitment(keystream, blindingFactor);
 * ```
 *
 * @public
 */
export function getKeystreamCommitmentGenerator(
  deps?: KeystreamCommitmentDeps,
): KeystreamCommitmentFunction {
  const { hasher } = deps ?? {};

  // If no hasher provided, use the default cached hasher
  if (hasher === undefined) {
    if (cachedDefaultKeystreamCommitmentFunction !== null) {
      return cachedDefaultKeystreamCommitmentFunction;
    }

    const defaultHasher = getPoseidonHasher();
    const commitmentFunction = createKeystreamCommitmentFunction(defaultHasher);
    cachedDefaultKeystreamCommitmentFunction = commitmentFunction;
    return commitmentFunction;
  }

  // Check if we have a cached function for this hasher
  const cachedFunction = keystreamCommitmentCache.get(hasher);
  if (cachedFunction !== undefined) {
    return cachedFunction;
  }

  // Create and cache new function
  const commitmentFunction = createKeystreamCommitmentFunction(hasher);
  keystreamCommitmentCache.set(hasher, commitmentFunction);
  return commitmentFunction;
}
