/* =============================================================================
 * CONSTANTS
 * ============================================================================= */

/**
 * The base prefix prepended to every KMAC domain separator string.
 *
 * @remarks
 * All domain-separated keys in Umbra follow the pattern:
 * `"Umbra Privacy - {KeyType} - {offset}"`.
 * This shared prefix binds every derivation to the Umbra protocol namespace,
 * providing an additional layer of domain isolation above the KMAC key argument.
 *
 * @internal
 */
const DOMAIN_PREFIX = "Umbra Privacy";

/**
 * KMAC256 output length in bytes for 512-bit pseudorandom output.
 *
 * @remarks
 * 64 bytes (512 bits) of KMAC256 output is used before field-element sampling.
 * A 512-bit output ensures the statistical distance from uniform after reduction
 * modulo the BN254 or Curve25519 field prime is at most 2^{-128}, which is
 * negligible by standard cryptographic arguments.
 *
 * @defaultValue 64
 * @internal
 */
const KMAC_512_OUTPUT_LENGTH = 64;

/**
 * Domain separator prefix for ephemeral master seed derivation.
 *
 * @remarks
 * Used by {@link getEphemeralMasterSeedDeriver} to form:
 * `"Ephemeral Seed - {offset}"`. Each U256 offset produces an independent
 * 64-byte ephemeral master seed via the standard U512 KMAC pipeline.
 *
 * @internal
 */
const EPHEMERAL_SEED_PREFIX = "Ephemeral Seed";

/**
 * Domain separator for master viewing key derivation.
 *
 * @remarks
 * Used by {@link getMasterViewingKeyDeriver} to form:
 * `"Umbra Privacy - MasterViewingKey - {offset}"`.
 * The MVK is derived with 256-bit KMAC output, then masked to 252 bits.
 *
 * @internal
 */
const MASTER_VIEWING_KEY_DOMAIN = "MasterViewingKey";

/**
 * Domain separator prefix for Poseidon private key derivation.
 *
 * @remarks
 * Used by {@link getPoseidonPrivateKeyDeriver} to form:
 * `"PoseidonPrivateKey - {offset}"`.
 * The offset is read from `client.offsets.poseidonPrivateKey`.
 *
 * @internal
 */
const POSEIDON_PRIVATE_KEY_PREFIX = "PoseidonPrivateKey";

/**
 * Domain separator prefix for Poseidon blinding factor derivation.
 *
 * @remarks
 * Used by {@link getPoseidonBlindingFactorDeriver} directly as the domain:
 * `"PoseidonBlindingFactor"`. Unlike the private key, the blinding factor
 * does not include an offset in its domain string.
 *
 * @internal
 */
const POSEIDON_BLINDING_FACTOR_PREFIX = "PoseidonBlindingFactor";

/**
 * Domain separator for user-account X25519 keypair derivation.
 *
 * @remarks
 * Used by {@link getUserAccountX25519KeypairDeriver} to form:
 * `"UserAccountX25519Keypair - {offset}"`.
 * The resulting Ed25519 public key is submitted to `registerTokenPublicKey`
 * and converted to X25519 on-chain for confidential balance encryption.
 *
 * @internal
 */
const USER_ACCOUNT_X25519_KEYPAIR_DOMAIN = "UserAccountX25519Keypair";

/**
 * Domain separator for MVK-encrypting X25519 keypair derivation.
 *
 * @remarks
 * Used by {@link getMasterViewingKeyX25519KeypairDeriver} to form:
 * `"MasterViewingKeyEncryptingX25519Keypair - {offset}"`.
 * The X25519 private key encrypts the master viewing key via the Rescue cipher
 * in `registerUserForAnonymousUsageV3`, and the Ed25519 public key is stored
 * on-chain as the proving signer.
 *
 * @internal
 */
const MVK_ENCRYPTING_X25519_KEYPAIR_DOMAIN = "MasterViewingKeyEncryptingX25519Keypair";

/**
 * Domain separator for per-mint X25519 keypair derivation.
 *
 * @remarks
 * Used by {@link getMintX25519KeypairDeriver} to form:
 * `"MintX25519Keypair - {mint} - {offset}"`.
 * Including the mint address in the domain string guarantees that keypairs
 * for different mints are cryptographically independent even at the same offset.
 * Used in `reencrypt_shared` operations.
 *
 * @internal
 */
const MINT_X25519_KEYPAIR_DOMAIN = "MintX25519Keypair";

/**
 * Domain separator prefix for Rescue encryption commitment blinding factors.
 *
 * @remarks
 * Used by {@link getRescueCommitmentBlindingFactorDeriver} to form:
 * `"RescueEncryptionCommitmentBlindingFactor - {totalOffset}"`.
 * The total offset combines `client.offsets.rescueCommitmentBlindingFactor`
 * with the caller-supplied per-operation offset.
 *
 * @internal
 */
const RESCUE_ENCRYPTION_COMMITMENT_BLINDING_FACTOR_PREFIX =
  "RescueEncryptionCommitmentBlindingFactor";

/**
 * Domain separator prefix for random factors in polynomial commitments.
 *
 * @remarks
 * Used by {@link getPolynomialCommitmentFactorDeriver} to form:
 * `"RandomFactorForPolynomialCommitment - {totalOffset}"`.
 * The output is sampled to a Curve25519 (not BN254) field element because
 * polynomial commitments in Umbra operate over the Curve25519 scalar field.
 *
 * @internal
 */
const RANDOM_FACTOR_FOR_POLYNOMIAL_COMMITMENT_PREFIX = "RandomFactorForPolynomialCommitment";

/**
 * Bit mask constraining a 256-bit value to at most 252 bits.
 *
 * @remarks
 * Equal to `2^252 - 1`. Applied to the raw KMAC256 output when deriving
 * `MasterViewingKey` (and its ephemeral variants) so that the value fits in
 * the BN254 scalar field AND satisfies the additional 252-bit constraint
 * required by ZK circuits that operate on 252-bit inputs.
 *
 * After masking, an explicit `>= 2^252` check is performed to guard against
 * future changes that might remove the mask.
 *
 * @internal
 */
const MAX_252_BIT_VALUE = (1n << 252n) - 1n;

/**
 * Fixed personalization bytes used by all pure (stateless) KMAC256 derivations.
 *
 * @remarks
 * Pure derivation functions have no access to an `IUmbraClient` — they operate
 * solely on a 16-byte `modifiedGenerationIndex`. To maintain the KMAC
 * customization-string structure used everywhere else in the system, they use
 * this hard-coded personalization value.
 *
 * The `"pure"` token in the network slot signals that network isolation was
 * already baked in at the `deriveModifiedGenerationIndexFor*Claim` step, so
 * no further network disambiguation is needed here.
 *
 * Format: `"umbra/1.0.0|kmac256/1.0.0|kdf/1.0.0|pure"`
 *
 * @see {@link buildPersonalizationString} for the client-aware variant
 * @internal
 */
const PURE_PERSONALIZATION = new TextEncoder().encode("umbra/1.0.0|kmac256/1.0.0|kdf/1.0.0|pure");

/**
 * Function type that splits a Solana base58 address into low/high 128-bit halves.
 *
 * @remarks
 * Solana addresses are 32-byte values. Poseidon hashing requires BN254 field
 * elements. Splitting a 32-byte address into two 128-bit little-endian integers
 * guarantees both halves fit within the BN254 field prime and avoids any
 * reduction loss. This type alias is used for dependency injection so callers
 * can substitute test implementations.
 *
 * @see {@link splitAddressToLowHigh} for the production implementation
 * @public
 */
export type SplitAddressFunction = (address: Address) => AddressSplitResult;

/* =============================================================================
 * PSEUDORANDOM U512 GENERATOR
 * ============================================================================= */

/**
 * Required arguments for creating a pseudorandom U512 generator.
 *
 * @remarks
 * The client is the sole required input because it provides both the master
 * seed (via `client.masterSeed.getMasterSeed()`) and the version information
 * (via `client.versions`) used to build the KMAC personalization string.
 *
 * @public
 */
export interface PseudorandomU512DeriverArgs {
  /**
   * The Umbra client used to access the master seed and version information.
   *
   * @remarks
   * The master seed is passed as the KMAC256 message; version information is
   * encoded in the personalization string (S parameter per NIST SP 800-185).
   *
   * @readonly
   */
  readonly client: IUmbraClient;
}

/**
 * Optional dependencies for the pseudorandom U512 generator.
 *
 * @remarks
 * All fields are optional. Omitting them selects production-safe defaults.
 * Override them in unit tests to inject deterministic or instrumented
 * implementations without touching any production code paths.
 *
 * @public
 */
export interface PseudorandomU512DeriverDeps {
  /**
   * Custom KMAC256 implementation.
   *
   * @remarks
   * When omitted, defaults to the `kmac256` export from
   * `@noble/hashes/sha3-addons`, which is a constant-time, audited
   * implementation of KMAC-256 per NIST SP 800-185.
   *
   * @defaultValue `import("@noble/hashes/sha3-addons").kmac256`
   * @readonly
   */
  readonly kmac256?: Kmac256Function;
}

/**
 * Creates the base pseudorandom U512 generator that underpins all KMAC256
 * key derivations in Umbra.
 *
 * @remarks
 * This is the lowest-level keyed derivation primitive. Every higher-level
 * generator (`getMasterSeedBasedFieldElementDeriver`, `getEphemeralMasterSeedDeriver`,
 * all keypair generators, etc.) delegates to this function or calls KMAC256
 * directly using the same structural pattern.
 *
 * ## KMAC256 Call Structure
 *
 * ```
 * output = KMAC256(
 *   key   = UTF8("Umbra Privacy - {domainSeparator}"),
 *   msg   = masterSeed,               // 64 bytes
 *   dkLen = 64,                        // 512 bits
 *   S     = buildPersonalizationString(client)
 *           // e.g. "umbra/1.0.0|kmac256/1.0.0|kdf/1.0.0|mainnet"
 * )
 * ```
 *
 * ## Domain Separation Invariant
 *
 * Every caller must supply a domain separator that is unique to its key type.
 * Reusing the same separator with the same master seed produces the same output,
 * which would allow cross-type key substitution attacks. Higher-level factories
 * enforce uniqueness via their private module-level constants.
 *
 * ## Personalization String
 *
 * The KMAC S (customization) parameter encodes `protocol/version`,
 * `algorithm/version`, `scheme/version`, and `network` so that a version bump
 * or network change produces a completely independent key space without any
 * code changes in the derivation logic.
 *
 * @param args - Required arguments: the Umbra client
 * @param deps - Optional dependencies for testing; omit in production
 * @returns An async function `(domainSeparator: string) => Promise<U512BeBytes>`
 *
 * @throws `CryptographyAssertionError` if KMAC256 returns fewer than 64 bytes
 *   (should never occur with a conformant implementation)
 *
 * @example
 * ```typescript
 * const generator = getPseudorandomU512Deriver({ client });
 *
 * // Derive independent 512-bit values via domain separation
 * const mvkBytes  = await generator("MasterViewingKey");
 * const seedBytes = await generator("Ephemeral Seed - 0");
 * const pkBytes   = await generator("PoseidonPrivateKey - 0");
 * ```
 *
 * @see {@link getMasterSeedBasedFieldElementDeriver} — wraps this with BN254 sampling
 * @see {@link buildPersonalizationString} — builds the S parameter from the client
 * @public
 */
export function getPseudorandomU512Deriver(
  args: PseudorandomU512DeriverArgs,
  deps?: PseudorandomU512DeriverDeps,
): PseudorandomU512DeriverFunction {
  const { client } = args;
  const { kmac256 = defaultKmac256 } = deps ?? {};

  return async (domainSeparator: string): Promise<U512BeBytes> => {
    // Get the master seed from the client
    const masterSeed = await client.masterSeed.getMasterSeed();

    // Build personalization string with version information
    const personalization = buildPersonalizationString(client);

    // Construct domain-separated key
    const key = `${DOMAIN_PREFIX} - ${domainSeparator}`;

    // Compute KMAC256 with 64-byte (512-bit) output using personalization
    const output = kmac256(
      new TextEncoder().encode(key), // key (customization string)
      masterSeed, // message
      {
        dkLen: KMAC_512_OUTPUT_LENGTH, // 64 bytes = 512 bits
        personalization, // version info
      },
    );

    // Assert as U512BeBytes
    assertU512BeBytes(output);

    return output;
  };
}

/* =============================================================================
 * FIELD ELEMENT DERIVER
 * ============================================================================= */

/**
 * Required arguments for creating a master-seed-based BN254 field element deriver.
 *
 * @public
 */
export interface MasterSeedBasedFieldElementDeriverArgs {
  /**
   * The Umbra client used to access the master seed and version information.
   *
   * @remarks
   * Forwarded verbatim to {@link getPseudorandomU512Deriver} unless a custom
   * `u512Generator` is supplied via `deps`.
   *
   * @readonly
   */
  readonly client: IUmbraClient;
}

/**
 * Optional dependencies for the master-seed-based BN254 field element deriver.
 *
 * @remarks
 * Inject custom implementations in tests. Omit all fields in production.
 *
 * @public
 */
export interface MasterSeedBasedFieldElementDeriverDeps {
  /**
   * Custom pseudorandom U512 generator.
   *
   * @remarks
   * When omitted, a new generator is created via
   * `getPseudorandomU512Deriver({ client })`. Provide this to avoid
   * constructing a second generator when the caller already holds one.
   *
   * @defaultValue `getPseudorandomU512Deriver({ client })`
   * @readonly
   */
  readonly u512Generator?: PseudorandomU512DeriverFunction;

  /**
   * Custom constant-time BN254 field element sampler.
   *
   * @remarks
   * Applied after the 512-bit KMAC output to reduce it to a uniformly
   * distributed element in `[0, p-1]` where `p` is the BN254 scalar prime.
   * When omitted, defaults to {@link bn254FieldElementSampler}.
   *
   * @defaultValue `bn254FieldElementSampler`
   * @readonly
   */
  readonly sampler?: U512BasedBn254FieldElementSamplerFunction;
}

/**
 * Creates a master-seed-based BN254 field element deriver.
 *
 * @remarks
 * This factory composes {@link getPseudorandomU512Deriver} (KMAC256, 512-bit
 * output) with a constant-time BN254 field element sampler. The resulting
 * function accepts a domain separator string and returns a uniformly distributed
 * element of the BN254 scalar field.
 *
 * It is the preferred way to derive BN254 field elements for keys that are
 * indexed by a string (e.g. `"PoseidonBlindingFactor"`) rather than a numeric
 * offset. For offset-parameterised keys, the caller should construct the domain
 * string before passing it in (e.g. `"PoseidonPrivateKey - 0"`).
 *
 * ## Algorithm
 *
 * ```
 * u512 = KMAC256(
 *   key   = UTF8("Umbra Privacy - {domainSeparator}"),
 *   msg   = masterSeed,
 *   dkLen = 64,
 *   S     = personalizationString
 * )
 * fieldElement = bn254FieldElementSampler(u512)
 * ```
 *
 * @param args - Required: the Umbra client
 * @param deps - Optional: custom U512 generator and/or BN254 sampler
 * @returns An async function `(domainSeparator: string) => Promise<Bn254FieldElement>`
 *
 * @example
 * ```typescript
 * const deriver = getMasterSeedBasedFieldElementDeriver({ client });
 *
 * // Blinding factor — uses the module-level constant as domain
 * const bf = await deriver("UmbraPrivacy - Master Viewing Key Blinding Factor");
 *
 * // Poseidon private key with offset
 * const pk = await deriver("PoseidonPrivateKey - 0");
 * ```
 *
 * @see {@link getPseudorandomU512Deriver} — base KMAC256 abstraction
 * @public
 */
export function getMasterSeedBasedFieldElementDeriver(
  args: MasterSeedBasedFieldElementDeriverArgs,
  deps?: MasterSeedBasedFieldElementDeriverDeps,
): MasterSeedBasedFieldElementDeriverFunction {
  const { client } = args;
  const {
    u512Generator = getPseudorandomU512Deriver({ client }),
    sampler = bn254FieldElementSampler,
  } = deps ?? {};

  return async (domainSeparator: string): Promise<Bn254FieldElement> => {
    // Generate 512-bit pseudorandom value
    const u512Value = await u512Generator(domainSeparator);

    // Sample field element using constant-time reduction
    const fieldElement = sampler(u512Value);

    return fieldElement as Bn254FieldElement;
  };
}

/* =============================================================================
 * EPHEMERAL MASTER SEED GENERATOR
 * ============================================================================= */

/**
 * Required arguments for creating an ephemeral master seed generator.
 *
 * @public
 */
export interface EphemeralMasterSeedDeriverArgs {
  /**
   * The Umbra client used to access the master seed and version information.
   *
   * @remarks
   * Forwarded to {@link getPseudorandomU512Deriver} unless a custom
   * `u512Generator` is supplied via `deps`.
   *
   * @readonly
   */
  readonly client: IUmbraClient;
}

/**
 * Optional dependencies for the ephemeral master seed generator.
 *
 * @remarks
 * Provide a custom `u512Generator` to share an existing generator instance
 * and avoid redundant client lookups; omit for production use.
 *
 * @public
 */
export interface EphemeralMasterSeedDeriverDeps {
  /**
   * Custom pseudorandom U512 generator.
   *
   * @remarks
   * When omitted, a new instance is created via
   * `getPseudorandomU512Deriver({ client })`.
   *
   * @defaultValue `getPseudorandomU512Deriver({ client })`
   * @readonly
   */
  readonly u512Generator?: PseudorandomU512DeriverFunction;
}

/**
 * Creates an ephemeral master seed generator.
 *
 * @remarks
 * An ephemeral master seed is a full 64-byte seed derived from the permanent
 * master seed and a U256 offset. It enables single-operation key sub-hierarchies:
 * the entire permanent key hierarchy can be regenerated from the permanent master
 * seed, while each ephemeral seed's sub-hierarchy is forward-secret relative to
 * a different offset.
 *
 * ## Algorithm
 *
 * ```
 * domain = UTF8("Ephemeral Seed - {offset}")
 * output = KMAC256(
 *   key   = UTF8("Umbra Privacy - {domain}"),
 *   msg   = permanentMasterSeed,
 *   dkLen = 64,
 *   S     = personalizationString
 * )
 * // output is asserted as MasterSeed (64-byte branded Uint8Array)
 * ```
 *
 * ## Use Cases
 *
 * - Deriving a one-time key sub-hierarchy for a single UTXO operation so
 *   that compromising the ephemeral seed does not reveal the permanent master
 *   viewing key.
 * - Providing deterministic replay of ephemeral derivations using the same
 *   client and offset (useful for recovery and auditing).
 *
 * @param args - Required: the Umbra client
 * @param deps - Optional: custom U512 generator
 * @returns An async function `(offset: U256) => Promise<MasterSeed>`
 *
 * @example
 * ```typescript
 * const generator = getEphemeralMasterSeedDeriver({ client });
 *
 * // Each offset yields a fully independent ephemeral seed
 * const seed0 = await generator(0n as U256);
 * const seed1 = await generator(1n as U256);
 * ```
 *
 * @see {@link EphemeralMasterSeedDeriverFunction} — the returned function type
 * @public
 */
export function getEphemeralMasterSeedDeriver(
  args: EphemeralMasterSeedDeriverArgs,
  deps?: EphemeralMasterSeedDeriverDeps,
): EphemeralMasterSeedDeriverFunction {
  const { client } = args;
  const { u512Generator = getPseudorandomU512Deriver({ client }) } = deps ?? {};

  return async (offset: U256): Promise<MasterSeed> => {
    // Format domain separator with offset as decimal string
    const domainSeparator = `${EPHEMERAL_SEED_PREFIX} - ${offset.toString()}`;

    // Generate 512-bit pseudorandom value
    const u512Value = await u512Generator(domainSeparator);

    // The U512BeBytes needs to be treated as a MasterSeed
    // MasterSeed is a subbrand of Keccak512Hash which is U512LeBytes
    // We use the raw bytes and assert as MasterSeed
    assertMasterSeed(u512Value);

    return u512Value;
  };
}

/* =============================================================================
 * MASTER VIEWING KEY GENERATOR
 * ============================================================================= */

/**
 * Required arguments for creating a master viewing key generator.
 *
 * @public
 */
export interface MasterViewingKeyDeriverArgs {
  /**
   * The Umbra client used to access the master seed and version information.
   *
   * @remarks
   * The client's `offsets.masterViewingKey` is included in the domain separator
   * so that the user can rotate the MVK independently of the master seed.
   *
   * @readonly
   */
  readonly client: IUmbraClient;
}

/**
 * Optional dependencies for the master viewing key generator.
 *
 * @public
 */
export interface MasterViewingKeyDeriverDeps {
  /**
   * Custom KMAC256 implementation.
   *
   * @remarks
   * The MVK generator calls KMAC256 directly (not via the U512 generator)
   * because it needs a 256-bit output (not 512-bit) before masking to 252 bits.
   *
   * @defaultValue `import("@noble/hashes/sha3-addons").kmac256`
   * @readonly
   */
  readonly kmac256?: Kmac256Function;
}

/**
 * Creates a master viewing key (MVK) generator.
 *
 * @remarks
 * The MVK is the root of the Poseidon-based viewing key tree. It is constrained
 * to 252 bits so it fits in the BN254 scalar field AND satisfies the additional
 * bit-length requirement of the ZK circuits that use it as a public input.
 *
 * ## Algorithm
 *
 * ```
 * key    = UTF8("Umbra Privacy - MasterViewingKey - {client.offsets.masterViewingKey}")
 * raw256 = KMAC256(key, masterSeed, dkLen=32, S=personalizationString)
 * value  = BigEndianBytesToBigInt(raw256)
 * value  = value & ((1n << 252n) - 1n)   // clamp to 252 bits
 * assertBn254FieldElement(value)
 * assertMasterViewingKey(value)
 * ```
 *
 * Note that the output length is 32 bytes (256 bits), not 64, because the
 * 252-bit mask removes the top 4 bits before any field-modulus reduction; the
 * resulting value is already less than the BN254 prime.
 *
 * ## Key Rotation
 *
 * `client.offsets.masterViewingKey` is included in the domain string. Advancing
 * this offset produces a completely independent MVK — and therefore an entirely
 * independent viewing-key tree — without changing the master seed.
 *
 * @param args - Required: the Umbra client
 * @param deps - Optional: custom KMAC256 implementation
 * @returns An async zero-argument function `() => Promise<MasterViewingKey>`
 *
 * @throws `CryptographyAssertionError` if the masked value is still `>= 2^252`
 *   (indicates a logic error; should never occur after the bitmask)
 * @throws `CryptographyAssertionError` if the result is not a valid BN254 field element
 *
 * @example
 * ```typescript
 * const generator = getMasterViewingKeyDeriver({ client });
 * const mvk = await generator();
 * // mvk < 2n ** 252n  — guaranteed by implementation
 * ```
 *
 * @see {@link MasterViewingKeyDeriverFunction} — the returned function type
 * @see {@link getMintViewingKeyDeriver} — derives `Poseidon(MVK, mintLow, mintHigh)`
 * @public
 */
export function getMasterViewingKeyDeriver(
  args: MasterViewingKeyDeriverArgs,
  deps?: MasterViewingKeyDeriverDeps,
): MasterViewingKeyDeriverFunction {
  const { client } = args;
  const { kmac256 = defaultKmac256 } = deps ?? {};

  return async (): Promise<MasterViewingKey> => {
    // Get the master seed from the client
    const masterSeed = await client.masterSeed.getMasterSeed();

    // Get offset from client
    const offset = client.offsets.masterViewingKey;

    // Build personalization string with version information
    const personalization = buildPersonalizationString(client);

    // Include offset in domain separator
    const key = `${DOMAIN_PREFIX} - ${MASTER_VIEWING_KEY_DOMAIN} - ${offset.toString()}`;
    const hashOutput = kmac256(new TextEncoder().encode(key), masterSeed, {
      dkLen: U256_BYTE_LENGTH,
      personalization,
    });

    // Convert to bigint (big-endian interpretation)
    let value = 0n;
    for (const element of hashOutput) {
      value = (value << 8n) | BigInt(element);
    }

    // Constrain to 252 bits by masking
    value = value & MAX_252_BIT_VALUE;

    // Assert it's less than 2^252 (should always pass after masking)
    if (value >= 1n << 252n) {
      throw new CryptographyAssertionError(`Master viewing key must be < 2^252`, {
        value,
        expectedType: "MasterViewingKey",
        constraint: "value < 2^252",
      });
    }

    // Assert it's a valid BN254 field element
    assertBn254FieldElement(value, "masterViewingKey");
    assertMasterViewingKey(value);

    return value;
  };
}

/* =============================================================================
 * BLINDING FACTOR AND PRIVATE KEY GENERATORS
 * ============================================================================= */

/**
 * Required arguments for creating a master viewing key blinding factor generator.
 *
 * @public
 */
export interface MasterViewingKeyBlindingFactorDeriverArgs {
  /**
   * The Umbra client used to access the master seed and version information.
   *
   * @readonly
   */
  readonly client: IUmbraClient;
}

/**
 * Optional dependencies for the master viewing key blinding factor generator.
 *
 * @public
 */
export interface MasterViewingKeyBlindingFactorDeriverDeps {
  /**
   * Custom BN254 field element deriver.
   *
   * @remarks
   * When omitted, a new deriver is created via
   * `getMasterSeedBasedFieldElementDeriver({ client })`.
   *
   * @defaultValue `getMasterSeedBasedFieldElementDeriver({ client })`
   * @readonly
   */
  readonly fieldElementDeriver?: MasterSeedBasedFieldElementDeriverFunction;
}

/**
 * Creates a master viewing key blinding factor generator.
 *
 * @remarks
 * The MVK blinding factor is a BN254 field element derived from the master seed
 * with the fixed domain string `"UmbraPrivacy - Master Viewing Key Blinding Factor"`.
 * It is used to form Pedersen-style commitments over the MVK so that verifiers
 * can check knowledge of the MVK without learning its value.
 *
 * ## Domain Separator
 *
 * `"UmbraPrivacy - Master Viewing Key Blinding Factor"` (no offset; this value
 * is deterministic per master seed and is never rotated independently).
 *
 * @param args - Required: the Umbra client
 * @param deps - Optional: custom field element deriver
 * @returns An async zero-argument function `() => Promise<Bn254FieldElement>`
 *
 * @example
 * ```typescript
 * const generator = getMasterViewingKeyBlindingFactorDeriver({ client });
 * const bf = await generator();
 * // commitment = Poseidon([mvk, bf])
 * ```
 *
 * @see {@link MasterViewingKeyBlindingFactorDeriverFunction}
 * @public
 */
export function getMasterViewingKeyBlindingFactorDeriver(
  args: MasterViewingKeyBlindingFactorDeriverArgs,
  deps?: MasterViewingKeyBlindingFactorDeriverDeps,
): MasterViewingKeyBlindingFactorDeriverFunction {
  const { client } = args;
  const {
    fieldElementDeriver = getMasterSeedBasedFieldElementDeriver({
      client,
    }),
  } = deps ?? {};

  return async (): Promise<Bn254FieldElement> => {
    return fieldElementDeriver("UmbraPrivacy - Master Viewing Key Blinding Factor");
  };
}

/**
 * Required arguments for creating a Poseidon private key generator.
 *
 * @public
 */
export interface PoseidonPrivateKeyDeriverArgs {
  /**
   * The Umbra client used to access the master seed and version information.
   *
   * @remarks
   * `client.offsets.poseidonPrivateKey` is appended to the domain separator
   * to support independent rotation of the Poseidon key without changing the
   * master seed.
   *
   * @readonly
   */
  readonly client: IUmbraClient;
}

/**
 * Optional dependencies for the Poseidon private key generator.
 *
 * @public
 */
export interface PoseidonPrivateKeyDeriverDeps {
  /**
   * Custom BN254 field element deriver.
   *
   * @remarks
   * When omitted, a new deriver is created via
   * `getMasterSeedBasedFieldElementDeriver({ client })`.
   *
   * @defaultValue `getMasterSeedBasedFieldElementDeriver({ client })`
   * @readonly
   */
  readonly fieldElementDeriver?: MasterSeedBasedFieldElementDeriverFunction;
}

/**
 * Creates a Poseidon private key generator.
 *
 * @remarks
 * The Poseidon private key is a BN254 field element used as the secret key
 * parameter in Poseidon-based symmetric encryption within Umbra's MPC circuit.
 * Each master seed is associated with at most one Poseidon private key per
 * offset; advancing `client.offsets.poseidonPrivateKey` rotates the key.
 *
 * ## Domain Separator
 *
 * `"PoseidonPrivateKey - {client.offsets.poseidonPrivateKey}"`
 *
 * @param args - Required: the Umbra client
 * @param deps - Optional: custom field element deriver
 * @returns An async zero-argument function `() => Promise<Bn254FieldElement>`
 *
 * @example
 * ```typescript
 * const generator = getPoseidonPrivateKeyDeriver({ client });
 * const pk = await generator();
 * const ciphertext = await poseidonEncrypt(plaintext, pk);
 * ```
 *
 * @see {@link PoseidonPrivateKeyDeriverFunction}
 * @public
 */
export function getPoseidonPrivateKeyDeriver(
  args: PoseidonPrivateKeyDeriverArgs,
  deps?: PoseidonPrivateKeyDeriverDeps,
): PoseidonPrivateKeyDeriverFunction {
  const { client } = args;
  const {
    fieldElementDeriver = getMasterSeedBasedFieldElementDeriver({
      client,
    }),
  } = deps ?? {};

  return async (): Promise<Bn254FieldElement> => {
    // Get offset from client
    const offset = client.offsets.poseidonPrivateKey;
    // Include offset in domain separator
    const domain = `${POSEIDON_PRIVATE_KEY_PREFIX} - ${offset.toString()}`;
    return fieldElementDeriver(domain);
  };
}

/**
 * Required arguments for creating a Poseidon blinding factor generator.
 *
 * @public
 */
export interface PoseidonBlindingFactorDeriverArgs {
  /**
   * The Umbra client used to access the master seed and version information.
   *
   * @readonly
   */
  readonly client: IUmbraClient;
}

/**
 * Optional dependencies for the Poseidon blinding factor generator.
 *
 * @public
 */
export interface PoseidonBlindingFactorDeriverDeps {
  /**
   * Custom BN254 field element deriver.
   *
   * @defaultValue `getMasterSeedBasedFieldElementDeriver({ client })`
   * @readonly
   */
  readonly fieldElementDeriver?: MasterSeedBasedFieldElementDeriverFunction;
}

/**
 * Creates a Poseidon blinding factor generator.
 *
 * @remarks
 * The Poseidon blinding factor is a BN254 field element that adds randomness
 * to Poseidon-based commitments. It is deterministic per master seed (no offset
 * parameter) and is derived with the fixed domain `"PoseidonBlindingFactor"`.
 *
 * ## Domain Separator
 *
 * `"PoseidonBlindingFactor"` (no offset suffix)
 *
 * @param args - Required: the Umbra client
 * @param deps - Optional: custom field element deriver
 * @returns An async zero-argument function `() => Promise<Bn254FieldElement>`
 *
 * @example
 * ```typescript
 * const generator = getPoseidonBlindingFactorDeriver({ client });
 * const bf = await generator();
 * const commitment = await poseidonHash([value, bf]);
 * ```
 *
 * @see {@link PoseidonBlindingFactorDeriverFunction}
 * @public
 */
export function getPoseidonBlindingFactorDeriver(
  args: PoseidonBlindingFactorDeriverArgs,
  deps?: PoseidonBlindingFactorDeriverDeps,
): PoseidonBlindingFactorDeriverFunction {
  const { client } = args;
  const {
    fieldElementDeriver = getMasterSeedBasedFieldElementDeriver({
      client,
    }),
  } = deps ?? {};

  return async (): Promise<Bn254FieldElement> => {
    return fieldElementDeriver(POSEIDON_BLINDING_FACTOR_PREFIX);
  };
}

/* =============================================================================
 * MINT VIEWING KEY GENERATOR
 * ============================================================================= */

/**
 * Required arguments for creating a mint viewing key generator.
 *
 * @public
 */
export interface MintViewingKeyDeriverArgs {
  /**
   * The Umbra client used to access the master seed and version information.
   *
   * @readonly
   */
  readonly client: IUmbraClient;
}

/**
 * Optional dependencies for the mint viewing key generator.
 *
 * @public
 */
export interface MintViewingKeyDeriverDeps {
  /**
   * Custom Poseidon hash function.
   *
   * @remarks
   * Used to compute `Poseidon(MVK, mintLow, mintHigh)`. When omitted,
   * defaults to the output of `getPoseidonHasher()`.
   *
   * @defaultValue `getPoseidonHasher()`
   * @readonly
   */
  readonly hasher?: PoseidonHashFunction;

  /**
   * Custom address-splitting function.
   *
   * @remarks
   * Splits a 32-byte Solana address into two 128-bit little-endian halves.
   * When omitted, defaults to `splitAddressToLowHigh`.
   *
   * @defaultValue `splitAddressToLowHigh`
   * @readonly
   */
  readonly splitAddress?: SplitAddressFunction;

  /**
   * Custom KMAC256 function forwarded to the internal MVK generator.
   *
   * @remarks
   * Only needed when overriding the MVK derivation in tests. In production,
   * omit this field.
   *
   * @defaultValue `import("@noble/hashes/sha3-addons").kmac256`
   * @readonly
   */
  readonly kmac256?: Kmac256Function;
}

/**
 * Creates a mint viewing key generator.
 *
 * @remarks
 * A mint viewing key (MVK_mint) grants its holder the ability to decrypt and
 * view all confidential transactions involving a specific token mint without
 * exposing transactions of other mints and without revealing the master viewing
 * key.
 *
 * ## Algorithm
 *
 * ```
 * MVK          = getMasterViewingKeyDeriver(client)()
 * [low, high]  = splitAddressToLowHigh(mint)   // each is a 128-bit LE integer
 * MintVK       = Poseidon([MVK, low, high])
 * ```
 *
 * Binding the mint address in the Poseidon hash ensures that a mint viewing key
 * for one token cannot be mistaken for or reused as the mint key of a different
 * token.
 *
 * @param args - Required: the Umbra client
 * @param deps - Optional: custom Poseidon hasher, address splitter, KMAC256
 * @returns An async function `(mint: Address, options?) => Promise<MintViewingKey>`
 *
 * @example
 * ```typescript
 * import { address } from "@solana/kit";
 * const generator = getMintViewingKeyDeriver({ client });
 * const usdcMint = address("EPjFWdd5AufqSSqeM2qN1xzybapC8G4wEGGkZwyTDt1v");
 * const mintVK = await generator(usdcMint);
 * ```
 *
 * @see {@link MintViewingKeyDeriverFunction}
 * @see {@link getYearlyViewingKeyDeriver} — extends MVK_mint with a year component
 * @public
 */
export function getMintViewingKeyDeriver(
  args: MintViewingKeyDeriverArgs,
  deps?: MintViewingKeyDeriverDeps,
): MintViewingKeyDeriverFunction {
  const { client } = args;
  const {
    hasher = getPoseidonHasher(),
    splitAddress = splitAddressToLowHigh,
    kmac256,
  } = deps ?? {};

  return async (
    mint: Address,
    generatorOptions?: { readonly hasher?: PoseidonHashFunction },
  ): Promise<MintViewingKey> => {
    const effectiveHasher = generatorOptions?.hasher ?? hasher;

    // Derive master viewing key from the client
    const mvkGenerator = getMasterViewingKeyDeriver(
      { client },
      kmac256 === undefined ? undefined : { kmac256 },
    );
    const masterViewingKey = await mvkGenerator();

    // Split the mint address into low and high parts
    const { low, high } = splitAddress(mint);

    // h0 = Poseidon(MVK, mintAddressLow, mintAddressHigh)
    const h0 = await effectiveHasher([
      masterViewingKey,
      createBn254FieldElement(low, "mintAddressLow"),
      createBn254FieldElement(high, "mintAddressHigh"),
    ]);

    assertMintViewingKey(h0);
    return h0;
  };
}

