/* =============================================================================
 * RESCUE ENCRYPTION COMMITMENT BLINDING FACTOR GENERATOR
 * ============================================================================= */

/**
 * Required arguments for creating a Rescue encryption commitment blinding factor generator.
 *
 * @public
 */
export interface RescueCommitmentBlindingFactorDeriverArgs {
  /**
   * The Umbra client used to access the master seed and version information.
   *
   * @remarks
   * `client.offsets.rescueCommitmentBlindingFactor` is added to the caller-supplied
   * offset to form the total offset used in the domain separator.
   *
   * @readonly
   */
  readonly client: IUmbraClient;
}

/**
 * Optional dependencies for the Rescue encryption commitment blinding factor generator.
 *
 * @public
 */
export interface RescueCommitmentBlindingFactorDeriverDeps {
  /**
   * Custom pseudorandom U512 generator.
   *
   * @defaultValue `getPseudorandomU512Deriver({ client })`
   * @readonly
   */
  readonly u512Generator?: PseudorandomU512DeriverFunction;

  /**
   * Custom constant-time BN254 field element sampler.
   *
   * @defaultValue `bn254FieldElementSampler`
   * @readonly
   */
  readonly sampler?: U512BasedBn254FieldElementSamplerFunction;
}

/**
 * Creates a Rescue encryption commitment blinding factor generator.
 *
 * @remarks
 * Rescue encryption commitments bind ciphertexts, plaintexts, encryption keys,
 * nonces, and public key material together with a BN254 field element blinding
 * factor for zero-knowledge verification. This generator produces that blinding
 * factor deterministically from the master seed.
 *
 * ## Domain Separator
 *
 * `"RescueEncryptionCommitmentBlindingFactor - {totalOffset}"`
 *
 * where `totalOffset = client.offsets.rescueCommitmentBlindingFactor + offset`.
 * Using a combined offset lets callers generate per-operation blinding factors
 * (via the `offset` argument) while the client base offset provides an
 * additional rotation axis without changing the master seed.
 *
 * ## Algorithm
 *
 * ```
 * domain       = "RescueEncryptionCommitmentBlindingFactor - {totalOffset}"
 * u512         = KMAC256(UTF8("Umbra Privacy - " + domain), masterSeed, dkLen=64, S=personalization)
 * blindingFactor = bn254FieldElementSampler(u512)
 * ```
 *
 * @param args - Required: the Umbra client
 * @param deps - Optional: custom U512 generator and/or BN254 sampler
 * @returns An async function `(offset: U256) => Promise<Bn254FieldElement>`
 *
 * @example
 * ```typescript
 * const generator = getRescueCommitmentBlindingFactorDeriver({ client });
 * const bf = await generator(0n as U256);
 * // commitment = generateRescueEncryptionCommitment(ciphertexts, data, keys, bf, nonce, ...)
 * ```
 *
 * @see {@link RescueCommitmentBlindingFactorDeriverFunction}
 * @public
 */
export function getRescueCommitmentBlindingFactorDeriver(
  args: RescueCommitmentBlindingFactorDeriverArgs,
  deps?: RescueCommitmentBlindingFactorDeriverDeps,
): RescueCommitmentBlindingFactorDeriverFunction {
  const { client } = args;
  const {
    u512Generator = getPseudorandomU512Deriver({ client }),
    sampler = bn254FieldElementSampler,
  } = deps ?? {};

  return async (offset: U256): Promise<Bn254FieldElement> => {
    // Get base offset from client and combine with parameter offset
    const baseOffset = client.offsets.rescueCommitmentBlindingFactor;
    const totalOffset = baseOffset + BigInt(offset);

    // Build domain separator with combined offset
    const domainSeparator = `${RESCUE_ENCRYPTION_COMMITMENT_BLINDING_FACTOR_PREFIX} - ${totalOffset.toString()}`;

    // Generate 512-bit pseudorandom value
    const u512Value = await u512Generator(domainSeparator);

    // Sample BN254 field element using constant-time reduction
    const fieldElement = sampler(u512Value);

    assertBn254FieldElement(fieldElement, "fieldElement");
    return fieldElement;
  };
}

/* =============================================================================
 * RANDOM FACTOR FOR POLYNOMIAL COMMITMENT GENERATOR
 * ============================================================================= */

/**
 * Required arguments for creating a random factor for polynomial commitment generator.
 *
 * @public
 */
export interface PolynomialCommitmentFactorDeriverArgs {
  /**
   * The Umbra client used to access the master seed and version information.
   *
   * @remarks
   * `client.offsets.randomCommitmentFactor` is added to the caller-supplied
   * offset to form the total offset in the domain separator.
   *
   * @readonly
   */
  readonly client: IUmbraClient;
}

/**
 * Optional dependencies for the random factor for polynomial commitment generator.
 *
 * @public
 */
export interface PolynomialCommitmentFactorDeriverDeps {
  /**
   * Custom pseudorandom U512 generator.
   *
   * @defaultValue `getPseudorandomU512Deriver({ client })`
   * @readonly
   */
  readonly u512Generator?: PseudorandomU512DeriverFunction;

  /**
   * Custom constant-time Curve25519 field element sampler.
   *
   * @remarks
   * Note: This is a Curve25519 (not BN254) sampler because polynomial
   * commitments in Umbra operate over the Curve25519 scalar field.
   *
   * @defaultValue `curve25519FieldElementSampler`
   * @readonly
   */
  readonly sampler?: U512BasedCurve25519FieldElementSamplerFunction;
}

/**
 * Creates a random factor for polynomial commitment generator.
 *
 * @remarks
 * Polynomial commitments in Umbra use Curve25519 scalar field elements as
 * random evaluation points. This generator derives those elements deterministically
 * from the master seed and a per-operation offset.
 *
 * Note the output type: this is a `Curve25519FieldElement`, not a
 * `Bn254FieldElement`. The corresponding sampler (`curve25519FieldElementSampler`)
 * reduces modulo the Curve25519 scalar prime rather than the BN254 prime.
 *
 * ## Domain Separator
 *
 * `"RandomFactorForPolynomialCommitment - {totalOffset}"`
 *
 * where `totalOffset = client.offsets.randomCommitmentFactor + offset`.
 *
 * @param args - Required: the Umbra client
 * @param deps - Optional: custom U512 generator and/or Curve25519 sampler
 * @returns An async function `(offset: U256) => Promise<Curve25519FieldElement>`
 *
 * @example
 * ```typescript
 * const generator = getPolynomialCommitmentFactorDeriver({ client });
 * const rf = await generator(0n as U256);
 * const commitment = evaluatePolynomial([coeff0, coeff1, rf], challenge);
 * ```
 *
 * @see {@link PolynomialCommitmentFactorDeriverFunction}
 * @public
 */
export function getPolynomialCommitmentFactorDeriver(
  args: PolynomialCommitmentFactorDeriverArgs,
  deps?: PolynomialCommitmentFactorDeriverDeps,
): PolynomialCommitmentFactorDeriverFunction {
  const { client } = args;
  const {
    u512Generator = getPseudorandomU512Deriver({ client }),
    sampler = curve25519FieldElementSampler,
  } = deps ?? {};

  return async (offset: U256): Promise<Curve25519FieldElement> => {
    // Get base offset from client and combine with parameter offset
    const baseOffset = client.offsets.randomCommitmentFactor;
    const totalOffset = baseOffset + BigInt(offset);

    // Build domain separator with combined offset
    const domainSeparator = `${RANDOM_FACTOR_FOR_POLYNOMIAL_COMMITMENT_PREFIX} - ${totalOffset.toString()}`;

    // Generate 512-bit pseudorandom value
    const u512Value = await u512Generator(domainSeparator);

    // Sample Curve25519 field element using constant-time reduction
    const fieldElement = sampler(u512Value);

    return fieldElement;
  };
}

/* =============================================================================
 * MODIFIED GENERATION INDEX DERIVATION (KMAC128)
 * ============================================================================= */

/**
 * Domain separator token for deriving a modified generation index in the sender-claim path.
 *
 * @remarks
 * Used by {@link deriveModifiedGenerationIndexForSenderClaim} to form:
 * `"Umbra Privacy - etaToMixerWithSenderClaim/{generationIndex}"`.
 * The Greek letter eta (η) is Umbra's notation for the UTXO ephemeral seed.
 *
 * @internal
 */
const ETA_TO_MIXER_WITH_SENDER_CLAIM_PREFIX = "etaToMixerWithSenderClaim";

/**
 * Domain separator token for deriving a modified generation index in the receiver-claim path.
 *
 * @remarks
 * Used by {@link deriveModifiedGenerationIndexForReceiverClaim} to form:
 * `"Umbra Privacy - etaToMixerWithReceiverClaim/{generationIndex}"`.
 * Produces an independent 16-byte value from the same master seed and generation
 * index, enabling separate sender and receiver claiming flows.
 *
 * @internal
 */
const ETA_TO_MIXER_WITH_RECEIVER_CLAIM_PREFIX = "etaToMixerWithReceiverClaim";

/**
 * Function type for deriving a 128-bit modified generation index from a master seed.
 *
 * @remarks
 * A `modifiedGenerationIndex` is a 16-byte value derived from `masterSeed` and
 * a U256 `generationIndex` via KMAC256 with 16-byte output. Once derived, it
 * serves as the sole input to all "pure" derivation functions, which do not
 * need the master seed again.
 *
 * This two-step design means that:
 * - UTXO creation and UTXO claim perform identical derivations given the same
 *   `modifiedGenerationIndex`.
 * - The master seed is only touched in the first step; all subsequent circuit
 *   inputs are derived without it.
 *
 * @param masterSeed - The 64-byte permanent master seed (KMAC key input)
 * @param generationIndex - The U256 generation counter identifying the UTXO slot
 * @returns A 128-bit (16-byte) modified generation index as a `U128` bigint
 *
 * @public
 */
export type ModifiedGenerationIndexDeriverFunction = (
  masterSeed: MasterSeed,
  generationIndex: U256,
) => U128;

/**
 * Derives a 128-bit modified generation index for the sender-claim path.
 *
 * @remarks
 * The modified generation index (η_modified) is the gateway between the
 * master-seed world and the pure-derivation world. After this function runs,
 * all subsequent UTXO key derivations use the 16-byte output as their sole
 * secret input — no master seed required.
 *
 * This is the sender variant: callers who created the UTXO can re-derive the
 * same value using their own master seed and the UTXO's generation index.
 *
 * ## Algorithm
 *
 * ```
 * domain  = UTF8("Umbra Privacy - etaToMixerWithSenderClaim/{generationIndex}")
 * output  = KMAC256(key=domain, msg=masterSeed, dkLen=16, S=PURE_PERSONALIZATION)
 * result  = LittleEndianBytesToBigInt(output)   // U128
 * ```
 *
 * Note: Although the comment in the code says "KMAC128", the implementation
 * calls `kmac256` with `dkLen=16`. KMAC256 with 128-bit output provides
 * equivalent security to KMAC128 with proper parameters.
 *
 * @param masterSeed - The 64-byte permanent master seed (KMAC key input)
 * @param generationIndex - The U256 UTXO generation counter
 * @returns A 128-bit little-endian modified generation index as `U128`
 *
 * @throws `CryptographyAssertionError` if `masterSeed` does not pass `assertMasterSeed`
 *
 * @example
 * ```typescript
 * const modifiedIndex = deriveModifiedGenerationIndexForSenderClaim(
 *   masterSeed, generationIndex
 * );
 * const nullifier = deriveNullifierFromModifiedGenerationIndex(
 *   new Uint8Array(/* 16 bytes from modifiedIndex *\/)
 * );
 * ```
 *
 * @see {@link deriveModifiedGenerationIndexForReceiverClaim} — receiver variant
 * @see {@link expandModifiedGenerationIndex} — expands 16 bytes to 32 bytes
 * @public
 */
export function deriveModifiedGenerationIndexForSenderClaim(
  masterSeed: MasterSeed,
  generationIndex: U256,
): U128 {
  assertMasterSeed(masterSeed);

  // Build domain separator with generation index
  const domainSeparator = `${DOMAIN_PREFIX} - ${ETA_TO_MIXER_WITH_SENDER_CLAIM_PREFIX}/${generationIndex.toString()}`;

  // Use KMAC256 with domain as key, masterSeed as message
  const result = defaultKmac256(new TextEncoder().encode(domainSeparator), masterSeed, {
    dkLen: 16,
    personalization: PURE_PERSONALIZATION,
  });

  // Interpret as little-endian U128
  let value = 0n;
  for (let index = 0; index < 16; index++) {
    value |= BigInt(result[index]) << BigInt(index * 8);
  }

  return value as U128;
}

/**
 * Derives a 128-bit modified generation index for the receiver-claim path.
 *
 * @remarks
 * Identical in structure to {@link deriveModifiedGenerationIndexForSenderClaim}
 * but uses the domain token `"etaToMixerWithReceiverClaim"` instead of
 * `"etaToMixerWithSenderClaim"`. This ensures the receiver's modified index is
 * independent of the sender's, preventing the receiver from computing the
 * sender's nullifier or other sender-specific keys (and vice versa).
 *
 * ## Algorithm
 *
 * ```
 * domain  = UTF8("Umbra Privacy - etaToMixerWithReceiverClaim/{generationIndex}")
 * output  = KMAC256(key=domain, msg=masterSeed, dkLen=16, S=PURE_PERSONALIZATION)
 * result  = LittleEndianBytesToBigInt(output)   // U128
 * ```
 *
 * @param masterSeed - The 64-byte permanent master seed
 * @param generationIndex - The U256 UTXO generation counter
 * @returns A 128-bit little-endian modified generation index as `U128`
 *
 * @throws `CryptographyAssertionError` if `masterSeed` does not pass `assertMasterSeed`
 *
 * @example
 * ```typescript
 * const modifiedIndex = deriveModifiedGenerationIndexForReceiverClaim(
 *   masterSeed, generationIndex
 * );
 * ```
 *
 * @see {@link deriveModifiedGenerationIndexForSenderClaim} — sender variant
 * @public
 */
export function deriveModifiedGenerationIndexForReceiverClaim(
  masterSeed: MasterSeed,
  generationIndex: U256,
): U128 {
  assertMasterSeed(masterSeed);

  // Build domain separator with generation index
  const domainSeparator = `${DOMAIN_PREFIX} - ${ETA_TO_MIXER_WITH_RECEIVER_CLAIM_PREFIX}/${generationIndex.toString()}`;

  // Use KMAC256 with domain as key, masterSeed as message
  const result = defaultKmac256(new TextEncoder().encode(domainSeparator), masterSeed, {
    dkLen: 16,
    personalization: PURE_PERSONALIZATION,
  });

  // Interpret as little-endian U128
  let value = 0n;
  for (let index = 0; index < 16; index++) {
    value |= BigInt(result[index]) << BigInt(index * 8);
  }

  return value as U128;
}

/* =============================================================================
 * KECCAK512-BASED BN254 FIELD ELEMENT DERIVATION
 * ============================================================================= */

/**
 * Function type for deriving a BN254 field element from arbitrary seed bytes via Keccak512.
 *
 * @remarks
 * This function type is used for derivations that originate from an ephemeral
 * seed or an `expandedGenerationIndex` rather than from KMAC256. The caller is
 * responsible for encoding domain separation into the seed bytes before passing
 * them in.
 *
 * @param seed - The input seed bytes; must include any domain separation tokens
 * @returns A uniformly distributed BN254 field element in `[0, p-1]`
 *
 * @see {@link deriveBn254FieldElementFromKeccak512}
 * @see {@link getBn254FieldElementFromKeccak512Deriver}
 * @public
 */
export type Keccak512BasedBn254FieldElementDeriverFunction = (
  seed: Uint8Array,
) => Bn254FieldElement;

/**
 * Optional dependencies for the Keccak512-based BN254 field element deriver.
 *
 * @public
 */
export interface Keccak512BasedBn254FieldElementDeriverDeps {
  /**
   * Custom constant-time BN254 field element sampler.
   *
   * @remarks
   * Applied after the 64-byte Keccak512 digest to produce a field element
   * uniformly distributed in `[0, p-1]`.
   *
   * @defaultValue `bn254FieldElementSampler`
   * @readonly
   */
  readonly sampler?: U512BasedBn254FieldElementSamplerFunction;
}

/**
 * Derives a BN254 field element from arbitrary seed bytes using Keccak512.
 *
 * @remarks
 * This function provides a lightweight alternative to the KMAC256-based pipeline
 * for contexts where the derivation does not require a keyed MAC (e.g. when the
 * secret is already embedded in the seed by the caller). It is used internally by
 * the ephemeral key derivation functions that operate on an `expandedGenerationIndex`.
 *
 * ## Algorithm
 *
 * ```
 * hash         = Keccak512(seed)                    // 64 bytes
 * fieldElement = bn254FieldElementSampler(hash)
 * ```
 *
 * Because Keccak512 is not a MAC, the caller must ensure domain separation is
 * encoded in `seed` before calling this function. The standard pattern is:
 * ```
 * seed = UTF8("{DomainToken}/{expandedGenerationIndex}")
 * ```
 *
 * ## Security Note
 *
 * This function is NOT keyed. If the seed is predictable by an adversary, the
 * output is also predictable. Always include a secret value (e.g.
 * `expandedGenerationIndex` derived from a secret master seed) in the seed.
 *
 * @param seed - Input bytes including domain separation and secret material
 * @param deps - Optional: custom BN254 sampler
 * @returns A BN254 field element uniformly distributed in `[0, p-1]`
 *
 * @example
 * ```typescript
 * // Ephemeral MVK from expanded generation index
 * const seed = new TextEncoder().encode(
 *   `EphemeralMasterViewingKey/${expandedIndex.toString()}`
 * );
 * const ephemeralMvk = deriveBn254FieldElementFromKeccak512(seed);
 * ```
 *
 * @see {@link getBn254FieldElementFromKeccak512Deriver} — curried factory variant
 * @public
 */
export function deriveBn254FieldElementFromKeccak512(
  seed: Uint8Array,
  deps?: Keccak512BasedBn254FieldElementDeriverDeps,
): Bn254FieldElement {
  const { sampler = bn254FieldElementSampler } = deps ?? {};

  // Hash the seed with Keccak512 to produce 64 bytes
  const hash = keccak_512(seed);

  // Assert that the hash is valid U512BeBytes (64 bytes)
  assertU512BeBytes(hash);

  // Use the sampler to reduce to BN254 field element
  const fieldElement = sampler(hash);

  // Assert and return as Bn254FieldElement
  assertBn254FieldElement(fieldElement);
  return fieldElement;
}

/**
 * Creates a curried Keccak512-based BN254 field element deriver.
 *
 * @remarks
 * Returns a zero-configuration `(seed: Uint8Array) => Bn254FieldElement` function
 * with a custom sampler bound via closure. Useful when the same deriver is called
 * many times or needs to be passed as a dependency to another factory.
 *
 * @param deps - Optional: custom BN254 sampler
 * @returns A function `(seed: Uint8Array) => Bn254FieldElement`
 *
 * @example
 * ```typescript
 * const deriveField = getBn254FieldElementFromKeccak512Deriver();
 * const element = deriveField(new TextEncoder().encode("MyDomain/0"));
 * ```
 *
 * @see {@link deriveBn254FieldElementFromKeccak512} — one-shot variant
 * @public
 */
export function getBn254FieldElementFromKeccak512Deriver(
  deps?: Keccak512BasedBn254FieldElementDeriverDeps,
): Keccak512BasedBn254FieldElementDeriverFunction {
  const { sampler = bn254FieldElementSampler } = deps ?? {};

  return (seed: Uint8Array): Bn254FieldElement => {
    return deriveBn254FieldElementFromKeccak512(seed, { sampler });
  };
}

/* =============================================================================
 * KEYSTREAM BLINDING FACTOR DERIVATION
 * ============================================================================= */

/**
 * Domain separator token for keystream blinding factor derivation.
 *
 * @remarks
 * Used by {@link deriveKeystreamBlindingFactor} to form the Keccak512 seed:
 * `"KeystreamBlindingFactor/{offset}"`. Because this function is not keyed by
 * a master seed, the offset must be kept secret or the blinding factor must be
 * combined with a secret upstream (e.g. through the keystream value itself).
 *
 * @internal
 */
const KEYSTREAM_BLINDING_FACTOR_PREFIX = "KeystreamBlindingFactor";

/**
 * Derives a keystream commitment blinding factor from a U256 offset.
 *
 * @remarks
 * This function is not keyed; it relies entirely on the offset value for domain
 * separation. It is intended for use in contexts where the keystream value itself
 * already provides the required secrecy (e.g. the blinding factor is only secret
 * if the keystream is secret).
 *
 * ## Algorithm
 *
 * ```
 * seed         = UTF8("KeystreamBlindingFactor/{offset}")
 * hash         = Keccak512(seed)
 * blindingFactor = bn254FieldElementSampler(hash)
 * ```
 *
 * @param offset - The U256 offset providing per-operation domain separation
 * @returns A BN254 field element uniformly distributed in `[0, p-1]`
 *
 * @example
 * ```typescript
 * const bf = deriveKeystreamBlindingFactor(12345n as U256);
 * // commitment = Poseidon([keystream, bf])
 * ```
 *
 * @public
 */
export function deriveKeystreamBlindingFactor(offset: U256): Bn254FieldElement {
  // Build seed with domain separator and offset
  const domainBytes = new TextEncoder().encode(
    `${KEYSTREAM_BLINDING_FACTOR_PREFIX}/${offset.toString()}`,
  );

  // Use Keccak512-based derivation
  return deriveBn254FieldElementFromKeccak512(domainBytes);
}

/* =============================================================================
 * EPHEMERAL RESCUE ENCRYPTION COMMITMENT BLINDING FACTOR GENERATOR
 * ============================================================================= */

/**
 * Domain separator token for ephemeral Rescue encryption commitment blinding factor derivation.
 *
 * @remarks
 * Used by {@link getEphemeralRescueCommitmentBlindingFactorDeriver} to form:
 * `"Umbra Privacy - Ephemeral RescueEncryptionCommitmentBlindingFactor - {offset}"`.
 * Unlike the persistent rescue blinding factor generator, this function uses KMAC256
 * with the master seed directly (no intermediate U512 generator).
 *
 * @internal
 */
const EPHEMERAL_RESCUE_ENCRYPTION_COMMITMENT_BF_DOMAIN =
  "Ephemeral RescueEncryptionCommitmentBlindingFactor";

/**
 * Required arguments for creating an ephemeral Rescue encryption commitment blinding factor generator.
 *
 * @public
 */
export interface EphemeralRescueCommitmentBlindingFactorDeriverArgs {
  /**
   * The Umbra client providing access to the master seed and version information.
   *
   * @readonly
   */
  readonly client: IUmbraClient;
}

/**
 * Optional dependencies for the ephemeral Rescue encryption commitment blinding factor generator.
 *
 * @public
 */
export interface EphemeralRescueCommitmentBlindingFactorDeriverDeps {
  /**
   * Custom KMAC256 implementation for testing.
   *
   * @defaultValue `import("@noble/hashes/sha3-addons").kmac256`
   * @readonly
   */
  readonly kmac256?: typeof defaultKmac256;

  /**
   * Custom constant-time BN254 field element sampler for testing.
   *
   * @defaultValue `bn254FieldElementSampler`
   * @readonly
   */
  readonly sampler?: U512BasedBn254FieldElementSamplerFunction;
}

/**
 * Creates an ephemeral Rescue encryption commitment blinding factor generator.
 *
 * @remarks
 * Unlike {@link getRescueCommitmentBlindingFactorDeriver} which adds
 * a client base offset, this generator uses a caller-supplied U256 offset directly
 * (typically the `expandedModifiedGenerationIndex` converted to a bigint). It calls
 * KMAC256 with the master seed directly rather than going through the intermediate
 * U512 generator.
 *
 * ## Algorithm
 *
 * ```
 * domain       = UTF8("Umbra Privacy - Ephemeral RescueEncryptionCommitmentBlindingFactor - {offset}")
 * u512         = KMAC256(key=domain, msg=masterSeed, dkLen=64, S=personalization)
 * blindingFactor = bn254FieldElementSampler(u512)
 * ```
 *
 * @param args - Required: the Umbra client
 * @param deps - Optional: custom KMAC256 and/or BN254 sampler
 * @returns An async function `(offset: U256) => Promise<Bn254FieldElement>`
 *
 * @example
 * ```typescript
 * const generator = getEphemeralRescueCommitmentBlindingFactorDeriver({ client });
 * const bf = await generator(expandedModifiedGenerationIndexU256);
 * ```
 *
 * @see {@link EphemeralRescueCommitmentBlindingFactorDeriverFunction}
 * @public
 */
export function getEphemeralRescueCommitmentBlindingFactorDeriver(
  args: EphemeralRescueCommitmentBlindingFactorDeriverArgs,
  deps?: EphemeralRescueCommitmentBlindingFactorDeriverDeps,
): EphemeralRescueCommitmentBlindingFactorDeriverFunction {
  const { client } = args;
  const { kmac256 = defaultKmac256, sampler = bn254FieldElementSampler } = deps ?? {};

  return async (offset: U256): Promise<Bn254FieldElement> => {
    const masterSeed = await client.masterSeed.getMasterSeed();
    const domainSeparator = `${DOMAIN_PREFIX} - ${EPHEMERAL_RESCUE_ENCRYPTION_COMMITMENT_BF_DOMAIN} - ${offset.toString()}`;
    const personalization = buildPersonalizationString(client);

    const u512Bytes = kmac256(new TextEncoder().encode(domainSeparator), masterSeed, {
      dkLen: KMAC_512_OUTPUT_LENGTH,
      personalization,
    });

    assertU512BeBytes(u512Bytes);
    const fieldElement = sampler(u512Bytes);
    assertBn254FieldElement(fieldElement);

    return fieldElement;
  };
}

