/**
 * Required arguments for creating an ephemeral UTXO master viewing key generator.
 *
 * @public
 */
export interface EphemeralUtxoMasterViewingKeyDeriverArgs {
  /**
   * The Umbra client used to access the master seed and version information.
   *
   * @readonly
   */
  readonly client: IUmbraClient;
}

/**
 * Optional dependencies for the ephemeral UTXO master viewing key generator.
 *
 * @public
 */
export interface EphemeralUtxoMasterViewingKeyDeriverDeps {
  /**
   * Custom KMAC256 implementation.
   *
   * @defaultValue `import("@noble/hashes/sha3-addons").kmac256`
   * @readonly
   */
  readonly kmac256?: Kmac256Function;

  /**
   * Custom constant-time BN254 field element sampler.
   *
   * @defaultValue `bn254FieldElementSampler`
   * @readonly
   */
  readonly sampler?: U512BasedBn254FieldElementSamplerFunction;
}

/**
 * Creates an ephemeral UTXO master viewing key generator.
 *
 * @remarks
 * Produces BN254 field elements for use as ephemeral MVKs in UTXO creation.
 * The output is constrained to 252 bits (via bitmask) to match the permanent
 * MVK constraint required by ZK circuits.
 *
 * ## Algorithm
 *
 * ```
 * domain = UTF8("Umbra Privacy - Ephemeral UTXO MasterViewingKey - {offset}")
 * u512   = KMAC256(key=domain, msg=masterSeed, dkLen=64, S=personalization)
 * mvk    = bn254FieldElementSampler(u512) & MAX_252_BIT_VALUE
 * ```
 *
 * @param args - Required: the Umbra client
 * @param deps - Optional: custom KMAC256 and/or BN254 sampler
 * @returns An async function `(offset: U256) => Promise<Bn254FieldElement>`
 *
 * @example
 * ```typescript
 * const generator = getEphemeralUtxoMasterViewingKeyDeriver({ client });
 * const ephemeralMvk = await generator(generationIndex);
 * ```
 *
 * @see {@link EphemeralUtxoMasterViewingKeyDeriverFunction}
 * @public
 */
export function getEphemeralUtxoMasterViewingKeyDeriver(
  args: EphemeralUtxoMasterViewingKeyDeriverArgs,
  deps?: EphemeralUtxoMasterViewingKeyDeriverDeps,
): EphemeralUtxoMasterViewingKeyDeriverFunction {
  const { client } = args;
  const { kmac256 = defaultKmac256, sampler = bn254FieldElementSampler } = deps ?? {};

  return async (offset: U256): Promise<Bn254FieldElement> => {
    const masterSeed = await client.masterSeed.getMasterSeed();
    const domainSeparator = `${DOMAIN_PREFIX} - ${EPHEMERAL_UTXO_MVK_DOMAIN} - ${offset.toString()}`;
    const personalization = buildPersonalizationString(client);

    const u512Bytes = kmac256(new TextEncoder().encode(domainSeparator), masterSeed, {
      dkLen: KMAC_512_OUTPUT_LENGTH,
      personalization,
    });

    assertU512BeBytes(u512Bytes);
    let fieldElement = sampler(u512Bytes);

    // Constrain to 252 bits by masking (consistent with main MVK generator)
    fieldElement = fieldElement & MAX_252_BIT_VALUE;

    assertBn254FieldElement(fieldElement);

    return fieldElement;
  };
}

