/* -----------------------------------------------------------------------------
 * POSEIDON KEYSTREAM BLINDING FACTOR GENERATOR
 * -------------------------------------------------------------------------- */

/**
 * Required arguments for creating a Poseidon keystream blinding factor generator.
 *
 * @public
 */
export interface PoseidonKeystreamBlindingFactorDeriverArgs {
  /**
   * The Umbra client providing access to the master seed and version information.
   *
   * @readonly
   */
  readonly client: IUmbraClient;
}

/**
 * Optional dependencies for the Poseidon keystream blinding factor generator.
 *
 * @public
 */
export interface PoseidonKeystreamBlindingFactorDeriverDeps {
  /**
   * Custom KMAC256 implementation for testing.
   *
   * @defaultValue `import("@noble/hashes/sha3-addons").kmac256`
   * @readonly
   */
  readonly kmac256?: typeof defaultKmac256;

  /**
   * Custom constant-time BN254 field element sampler for testing.
   *
   * @defaultValue `bn254FieldElementSampler`
   * @readonly
   */
  readonly sampler?: U512BasedBn254FieldElementSamplerFunction;
}

/**
 * Creates a Poseidon keystream blinding factor generator.
 *
 * @remarks
 * The keystream blinding factor binds a specific keystream value to an offset
 * so that the commitment `Poseidon([keystream, bf])` cannot be forged or reused
 * across positions. Both the keystream value AND the master seed contribute to
 * the blinding factor, ensuring it is secret even if the keystream is partially
 * known.
 *
 * ## Algorithm
 *
 * ```
 * domain  = UTF8("Umbra Privacy - PoseidonKeystreamBlindingFactor - {offset}")
 * message = masterSeed || keystreamLE32 || offsetLE32
 *           // 64 + 32 + 32 = 128 bytes
 * u512    = KMAC256(key=domain, msg=message, dkLen=64, S=personalization)
 * bf      = bn254FieldElementSampler(u512)
 * ```
 *
 * Note: the KMAC key and message roles are reversed compared to most other
 * generators in this module. Here, `domain` is the KMAC key and `message`
 * contains `masterSeed || keystream || offset`.
 *
 * ## Usage in Keystream Commitments
 *
 * ```
 * commitment = Poseidon([keystream, blindingFactor])
 * ```
 *
 * @param args - Required: the Umbra client
 * @param deps - Optional: custom KMAC256 and/or BN254 sampler
 * @returns An async function `(keystream: Bn254FieldElement, offset: U256) => Promise<Bn254FieldElement>`
 *
 * @example
 * ```typescript
 * const generator = getPoseidonKeystreamBlindingFactorDeriver({ client });
 * const bf0 = await generator(keystream0, 0n as U256);
 * const bf1 = await generator(keystream1, 1n as U256);
 * ```
 *
 * @see {@link PoseidonKeystreamBlindingFactorDeriverFunction}
 * @public
 */
export function getPoseidonKeystreamBlindingFactorDeriver(
  args: PoseidonKeystreamBlindingFactorDeriverArgs,
  deps?: PoseidonKeystreamBlindingFactorDeriverDeps,
): PoseidonKeystreamBlindingFactorDeriverFunction {
  const { client } = args;
  const { kmac256 = defaultKmac256, sampler = bn254FieldElementSampler } = deps ?? {};

  return async (keystream: Bn254FieldElement, offset: U256): Promise<Bn254FieldElement> => {
    const masterSeed = await client.masterSeed.getMasterSeed();
    const domainSeparator = `${DOMAIN_PREFIX} - ${POSEIDON_KEYSTREAM_BLINDING_FACTOR_DOMAIN} - ${offset.toString()}`;
    const personalization = buildPersonalizationString(client);

    // Concatenate keystream (32 bytes LE) with offset (32 bytes LE)
    const keystreamBytes = new Uint8Array(32);
    let keystreamValue = keystream as bigint;
    for (let index = 0; index < 32; index++) {
      keystreamBytes[index] = Number(keystreamValue & 0xffn);
      keystreamValue >>= 8n;
    }

    const offsetBytes = new Uint8Array(32);
    let offsetValue = offset as bigint;
    for (let index = 0; index < 32; index++) {
      offsetBytes[index] = Number(offsetValue & 0xffn);
      offsetValue >>= 8n;
    }

    // Concatenate masterSeed (64 bytes) || keystream (32 bytes LE) || offset (32 bytes LE)
    const message = new Uint8Array(masterSeed.length + 64);
    message.set(masterSeed, 0);
    message.set(keystreamBytes, masterSeed.length);
    message.set(offsetBytes, masterSeed.length + 32);

    const u512Bytes = kmac256(new TextEncoder().encode(domainSeparator), message, {
      dkLen: KMAC_512_OUTPUT_LENGTH,
      personalization,
    });

    assertU512BeBytes(u512Bytes);
    const fieldElement = sampler(u512Bytes);
    assertBn254FieldElement(fieldElement);

    return fieldElement;
  };
}

